#[derive(Debug, Subcommand)]
enum CatalogCommands {
    /// List admin-approved catalog models and downloadable artifacts.
    List(CatalogListArgs),
    /// Verify catalog structure, maintainer signature, canary refs, and optional dev downloads.
    Verify(CatalogVerifyArgs),
    /// Sign an admin-reviewed catalog draft with an operator-held Ed25519 seed file.
    Sign(CatalogSignArgs),
    /// Compute launch catalog metadata for a local admin artifact without loading model weights.
    ArtifactMetadata(CatalogArtifactMetadataArgs),
    /// Apply bound artifact metadata reports into a catalog draft.
    ApplyArtifactMetadata(CatalogApplyArtifactMetadataArgs),
    /// Print copy/paste artifact metadata/apply/sign/verify commands for the launch matrix.
    ArtifactPlan(CatalogArtifactPlanArgs),
    /// Print copy/paste source download/build commands that stage launch artifacts for upload.
    ArtifactStagePlan(CatalogArtifactStagePlanArgs),
    /// Print copy/paste Hugging Face upload plus artifact finalization commands.
    ArtifactPublishPlan(CatalogArtifactPublishPlanArgs),
    /// Run catalog canaries against a local admin artifact and print catalog-ready fingerprints.
    CalibrateCanary(CatalogCalibrateCanaryArgs),
    /// Verify calibration report files cover the catalog canary matrix.
    CanaryEvidence(CatalogCanaryEvidenceArgs),
    /// Apply bound calibration report fingerprints into a catalog draft.
    ApplyCanaryReports(CatalogApplyCanaryReportsArgs),
    /// Audit per-backend canary fingerprint coverage for launch artifacts.
    CanaryMatrix(CatalogCanaryMatrixArgs),
    /// Print copy/paste calibration commands for the catalog canary matrix.
    CanaryPlan(CatalogCanaryPlanArgs),
}

