fn catalog_artifact_metadata_apply_report(
    catalog_doc: &catalog::CatalogDocument,
    catalog_path: PathBuf,
    launch_only: bool,
    report_paths: &[PathBuf],
) -> CatalogArtifactMetadataApplyReport {
    let mut entries = Vec::new();
    let mut errors = Vec::new();
    let mut seen = BTreeSet::new();

    for path in report_paths {
        let mut entry_errors = Vec::new();
        let metadata = match read_json_file(path).and_then(|value| {
            serde_json::from_value::<CatalogArtifactMetadataReport>(value)
                .with_context(|| format!("parsing artifact metadata report {}", path.display()))
        }) {
            Ok(report) => report,
            Err(err) => {
                errors.push(format!("{}: {err}", path.display()));
                continue;
            }
        };

        if !metadata.ok {
            entry_errors.push("artifact metadata report ok=false".to_owned());
        }
        if metadata.catalog_patch.artifact_root_kind != "blake3_merkle_v1" {
            entry_errors.push(format!(
                "report artifact_root_kind must be blake3_merkle_v1, got {}",
                metadata.catalog_patch.artifact_root_kind
            ));
        }
        if !is_hex_len(&metadata.catalog_patch.artifact_root, 64) {
            entry_errors.push("report artifact_root must be 32-byte hex".to_owned());
        }
        if !is_hex_len(&metadata.catalog_patch.source_sha256, 64) {
            entry_errors.push("report source_sha256 must be 32-byte hex".to_owned());
        }
        if let Some(source_revision) = &metadata.catalog_patch.source_revision {
            if !is_hex_len(source_revision, 40) {
                entry_errors
                    .push("report source_revision must be 40-byte git commit hex".to_owned());
            }
        }
        if metadata.catalog_patch.weights_bytes == 0 || metadata.total_bytes == 0 {
            entry_errors.push("report weights_bytes/total_bytes must be positive".to_owned());
        }
        if metadata.catalog_patch.weights_bytes != metadata.total_bytes {
            entry_errors.push(format!(
                "report patch weights_bytes {} does not match total_bytes {}",
                metadata.catalog_patch.weights_bytes, metadata.total_bytes
            ));
        }
        if metadata.chunk_size == 0 || metadata.chunk_count == 0 {
            entry_errors.push("report chunk_size/chunk_count must be positive".to_owned());
        }

        let Some(binding) = metadata.catalog_binding.as_ref() else {
            errors.push(format!(
                "{}: artifact metadata report is not catalog-bound; rerun artifact-metadata with --model and --artifact",
                path.display()
            ));
            continue;
        };
        let key = (binding.model_id.clone(), binding.artifact.clone());
        if !seen.insert(key.clone()) {
            entry_errors.push(format!(
                "duplicate artifact metadata report for {} / {}",
                binding.model_id, binding.artifact
            ));
        }

        let Some(model) = catalog_doc
            .models
            .iter()
            .find(|model| model.model_id == binding.model_id)
        else {
            errors.push(format!(
                "{}: model {} is not present in current catalog",
                path.display(),
                binding.model_id
            ));
            continue;
        };
        if launch_only && model.tier != "launch" {
            entry_errors.push(format!(
                "model {} tier {} is outside launch-only scope",
                model.model_id, model.tier
            ));
        }
        let Some(artifact) = model.artifacts.get(&binding.artifact) else {
            errors.push(format!(
                "{}: artifact {} is not present for model {} in current catalog",
                path.display(),
                binding.artifact,
                model.model_id
            ));
            continue;
        };

        if binding.engine != artifact.engine {
            entry_errors.push(format!(
                "report engine {} does not match current catalog engine {}",
                binding.engine, artifact.engine
            ));
        }
        if binding.source_kind != artifact.source.kind
            || binding.source_repo != artifact.source.repo
            || binding.source_revision != artifact.source.revision
            || binding.source_path != artifact.path
        {
            entry_errors.push(
                "report source tuple does not match current catalog artifact source".to_owned(),
            );
        }
        if binding.current_artifact_root_kind != artifact.artifact_root_kind
            || binding.current_artifact_root != artifact.artifact_root
            || binding.current_source_sha256 != artifact.source_sha256
            || binding.current_weights_bytes != artifact.weights_bytes
        {
            entry_errors.push(
                "report current catalog fields are stale for this artifact; rerun artifact-metadata"
                    .to_owned(),
            );
        }

        let current_matches_patch = artifact.artifact_root_kind
            == metadata.catalog_patch.artifact_root_kind
            && artifact.artifact_root == metadata.catalog_patch.artifact_root
            && artifact.source_sha256.as_ref().is_some_and(|value| {
                value.eq_ignore_ascii_case(&metadata.catalog_patch.source_sha256)
            })
            && metadata
                .catalog_patch
                .source_revision
                .as_ref()
                .map_or(true, |target| {
                    artifact.source.revision.eq_ignore_ascii_case(target)
                })
            && artifact.weights_bytes == metadata.catalog_patch.weights_bytes;
        let update_needed = !current_matches_patch;
        let ok = entry_errors.is_empty();
        if !ok {
            errors.extend(
                entry_errors
                    .iter()
                    .map(|error| format!("{} {}: {error}", binding.model_id, binding.artifact)),
            );
        }
        entries.push(CatalogArtifactMetadataApplyEntry {
            report_path: path.clone(),
            model_id: binding.model_id.clone(),
            tier: model.tier.clone(),
            artifact: binding.artifact.clone(),
            engine: artifact.engine.clone(),
            source_kind: artifact.source.kind.clone(),
            source_repo: artifact.source.repo.clone(),
            source_revision: artifact.source.revision.clone(),
            target_source_revision: metadata.catalog_patch.source_revision.clone(),
            source_path: artifact.path.clone(),
            artifact_root_kind: metadata.catalog_patch.artifact_root_kind.clone(),
            artifact_root: metadata.catalog_patch.artifact_root.clone(),
            source_sha256: metadata.catalog_patch.source_sha256.to_ascii_lowercase(),
            weights_bytes: metadata.catalog_patch.weights_bytes,
            update_needed,
            ok,
            errors: entry_errors,
        });
    }

    if entries.is_empty() {
        errors.push("no artifact metadata reports were accepted".to_owned());
    }
    CatalogArtifactMetadataApplyReport {
        ok: errors.is_empty(),
        catalog_path,
        output_path: None,
        launch_only,
        report_count: entries.len(),
        applied_count: None,
        entries,
        errors,
    }
}

fn apply_artifact_metadata_reports(
    catalog_value: &mut Value,
    report: &CatalogArtifactMetadataApplyReport,
) -> Result<usize> {
    let models = catalog_value
        .get_mut("models")
        .and_then(Value::as_array_mut)
        .context("catalog JSON must contain models array")?;
    let mut applied = 0usize;
    for entry in &report.entries {
        if !entry.ok || !entry.update_needed {
            continue;
        }
        let model = models
            .iter_mut()
            .find(|model| model.get("model_id").and_then(Value::as_str) == Some(&entry.model_id))
            .with_context(|| format!("model {} disappeared from catalog JSON", entry.model_id))?;
        let artifacts = model
            .get_mut("artifacts")
            .and_then(Value::as_object_mut)
            .with_context(|| format!("model {} has no artifacts object", entry.model_id))?;
        let artifact = artifacts
            .get_mut(&entry.artifact)
            .and_then(Value::as_object_mut)
            .with_context(|| {
                format!(
                    "artifact {} disappeared from catalog JSON for model {}",
                    entry.artifact, entry.model_id
                )
            })?;
        artifact.insert(
            "artifact_root_kind".to_owned(),
            json!(entry.artifact_root_kind),
        );
        artifact.insert("artifact_root".to_owned(), json!(entry.artifact_root));
        artifact.insert("source_sha256".to_owned(), json!(entry.source_sha256));
        if let Some(target_source_revision) = &entry.target_source_revision {
            let source = artifact
                .get_mut("source")
                .and_then(Value::as_object_mut)
                .with_context(|| {
                    format!(
                        "artifact {} for model {} has no source object",
                        entry.artifact, entry.model_id
                    )
                })?;
            source.insert("revision".to_owned(), json!(target_source_revision));
        }
        artifact.insert("weights_bytes".to_owned(), json!(entry.weights_bytes));
        if artifact
            .get("notes")
            .and_then(Value::as_str)
            .is_some_and(|notes| {
                notes.contains("planned launch artifact") || notes.contains("until_p2_4")
            })
        {
            artifact.remove("notes");
        }
        applied += 1;
    }
    Ok(applied)
}

fn catalog_artifact_plan(args: CatalogArtifactPlanArgs) -> Result<()> {
    let catalog_path = args
        .catalog_path
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/models.json"))?;
    let catalog_path = absolutize(catalog_path)?;
    let artifact_base = absolutize(args.artifact_base.clone())?;
    let report_dir = absolutize(args.report_dir.clone())?;
    let catalog_output = args
        .catalog_output
        .clone()
        .unwrap_or_else(|| report_dir.join("catalog.with-artifacts.json"));
    let catalog_output = absolutize(catalog_output)?;
    let catalog_sign = catalog_artifact_plan_sign_options(&args)?;
    let hf_token_file = args.hf_token_file.clone().map(absolutize).transpose()?;
    let catalog_doc = catalog::load_document(&catalog_path)?;

    let report = catalog_artifact_plan_report(CatalogArtifactPlanInput {
        catalog_doc: &catalog_doc,
        catalog_path,
        artifact_base,
        report_dir,
        catalog_output,
        catalog_sign,
        hf_token_file,
        launch_only: !args.include_dev,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!("Catalog artifact metadata command plan.");
        println!("Catalog: {}", report.catalog_path.display());
        println!("Artifact base: {}", report.artifact_base.display());
        println!("Report dir: {}", report.report_dir.display());
        println!(
            "Scope: {}",
            if report.launch_only {
                "launch models"
            } else {
                "launch + dev models"
            }
        );
        println!(
            "Coverage: {} models, {} artifacts, ok={}",
            report.model_count, report.artifact_count, report.ok
        );
        for entry in &report.metadata_commands {
            println!(
                "- {} / {} ({}) [{}]: {}",
                entry.model_id,
                entry.artifact,
                entry.engine,
                entry.source_repo,
                if entry.ok { "ready" } else { "error" }
            );
            println!("  artifact: {}", entry.artifact_path.display());
            println!("  report: {}", entry.report_path.display());
            println!("  command: {}", entry.command.shell);
            for error in &entry.errors {
                println!("  error: {error}");
            }
        }
        println!("Apply artifact metadata:");
        println!("{}", report.apply_command.shell);
        if let Some(signature_command) = &report.signature_command {
            println!("Sign catalog draft:");
            println!("{}", signature_command.shell);
        }
        if let Some(verify_command) = &report.verify_command {
            println!("Verify signed launch sources:");
            println!("{}", verify_command.shell);
        } else {
            println!(
                "Verify signed launch sources: pass catalog signing args to emit this command."
            );
        }
        for error in &report.errors {
            println!("Global error: {error}");
        }
    }

    if !report.ok {
        bail!(
            "artifact metadata command plan has {} error(s)",
            report.errors.len()
        );
    }
    Ok(())
}

fn catalog_artifact_stage_plan(args: CatalogArtifactStagePlanArgs) -> Result<()> {
    let catalog_path = args
        .catalog_path
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/models.json"))?;
    let catalog_path = absolutize(catalog_path)?;
    let catalog_doc = catalog::load_document(&catalog_path)?;
    let artifact_base = absolutize(args.artifact_base.clone())?;
    let source_cache_dir = args
        .source_cache_dir
        .clone()
        .unwrap_or_else(|| artifact_base.join(".source-cache"));
    let source_cache_dir = absolutize(source_cache_dir)?;
    let hf_token_file = args.hf_token_file.clone().map(absolutize).transpose()?;
    let report = catalog_artifact_stage_plan_report(CatalogArtifactStagePlanInput {
        catalog_doc: &catalog_doc,
        catalog_path,
        artifact_base,
        source_cache_dir,
        hf_token_file,
        launch_only: !args.include_dev,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!("Catalog artifact staging command plan.");
        println!("Catalog: {}", report.catalog_path.display());
        println!("Artifact base: {}", report.artifact_base.display());
        println!("Source cache: {}", report.source_cache_dir.display());
        println!(
            "Scope: {}",
            if report.launch_only {
                "launch models"
            } else {
                "launch + dev models"
            }
        );
        println!(
            "Coverage: {} models, {} artifacts, {} source snapshots, ok={}",
            report.model_count, report.artifact_count, report.source_count, report.ok
        );
        println!(
            "Staging bytes: expected={}, staged={}, missing_estimate={}, available={}",
            report.catalog_expected_bytes,
            report.current_artifact_bytes,
            report.missing_artifact_bytes,
            report
                .artifact_base_available_bytes
                .map(|bytes| bytes.to_string())
                .unwrap_or_else(|| "unknown".to_owned())
        );
        println!("Preflight: {}", report.preflight_command.shell);
        println!("Source downloads:");
        for source in &report.source_commands {
            println!(
                "- {} [{}@{}]: {}",
                source.model_id,
                source.source_repo,
                source.source_revision,
                if source.ok { "ready" } else { "error" }
            );
            println!("  source dir: {}", source.source_dir.display());
            println!("  command: {}", source.command.shell);
            for error in &source.errors {
                println!("  error: {error}");
            }
        }
        println!("Artifact staging:");
        for entry in &report.stage_commands {
            println!(
                "- {} / {} ({}) [{}]: {}",
                entry.model_id,
                entry.artifact,
                entry.engine,
                entry.source_repo,
                if entry.ok { "ready" } else { "error" }
            );
            println!("  source dir: {}", entry.upstream_source_dir.display());
            println!("  artifact: {}", entry.artifact_path.display());
            println!("  catalog weights_bytes: {}", entry.catalog_weights_bytes);
            println!(
                "  staged now: exists={}, file={}, bytes={}",
                entry.current_artifact_exists,
                entry.current_artifact_is_file,
                entry
                    .current_artifact_bytes
                    .map(|bytes| bytes.to_string())
                    .unwrap_or_else(|| "unknown".to_owned())
            );
            println!("  command: {}", entry.stage_command.shell);
            println!("  follow-up: {}", entry.follow_up_publish_plan.shell);
            for error in &entry.errors {
                println!("  error: {error}");
            }
        }
        for error in &report.errors {
            println!("Global error: {error}");
        }
    }

    if !report.ok {
        bail!(
            "artifact staging command plan has {} error(s)",
            report.errors.len()
        );
    }
    Ok(())
}

fn catalog_artifact_publish_plan(args: CatalogArtifactPublishPlanArgs) -> Result<()> {
    let catalog_path = args
        .catalog_path
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/models.json"))?;
    let catalog_path = absolutize(catalog_path)?;
    let catalog_doc = catalog::load_document(&catalog_path)?;
    let artifact_base = absolutize(args.artifact_base.clone())?;
    let report_dir = absolutize(args.report_dir.clone())?;
    let catalog_output = args
        .catalog_output
        .clone()
        .unwrap_or_else(|| report_dir.join("catalog.with-artifacts.json"));
    let catalog_output = absolutize(catalog_output)?;
    let hf_token_file = args.hf_token_file.clone().map(absolutize).transpose()?;
    let catalog_sign = catalog_artifact_publish_plan_sign_options(&args)?;
    let report = catalog_artifact_publish_plan_report(CatalogArtifactPublishPlanInput {
        catalog_doc: &catalog_doc,
        catalog_path,
        artifact_base,
        report_dir,
        catalog_output,
        catalog_sign,
        hf_token_file,
        launch_only: !args.include_dev,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!("Catalog artifact publish command plan.");
        println!("Catalog: {}", report.catalog_path.display());
        println!("Artifact base: {}", report.artifact_base.display());
        println!("Report dir: {}", report.report_dir.display());
        println!(
            "Scope: {}",
            if report.launch_only {
                "launch models"
            } else {
                "launch + dev models"
            }
        );
        println!(
            "Coverage: {} models, {} artifacts, ok={}",
            report.model_count, report.artifact_count, report.ok
        );
        println!(
            "Staging bytes: expected={}, staged={}, missing_estimate={}, available={}",
            report.catalog_expected_bytes,
            report.current_artifact_bytes,
            report.missing_artifact_bytes,
            report
                .artifact_base_available_bytes
                .map(|bytes| bytes.to_string())
                .unwrap_or_else(|| "unknown".to_owned())
        );
        println!("Preflight: {}", report.preflight_command.shell);
        for entry in &report.publish_commands {
            println!(
                "- {} / {} ({}) [{}]: {}",
                entry.model_id,
                entry.artifact,
                entry.engine,
                entry.source_repo,
                if entry.ok { "ready" } else { "error" }
            );
            println!(
                "  local artifact: {}",
                entry.current_artifact_path.display()
            );
            println!("  catalog weights_bytes: {}", entry.catalog_weights_bytes);
            println!(
                "  local artifact ready: exists={}, file={}, bytes={}",
                entry.current_artifact_exists,
                entry.current_artifact_is_file,
                entry
                    .current_artifact_bytes
                    .map(|bytes| bytes.to_string())
                    .unwrap_or_else(|| "unknown".to_owned())
            );
            println!(
                "  published artifact: {}",
                entry.published_artifact_path_template.display()
            );
            println!("  upload: {}", entry.upload_command.shell);
            println!("  revision: {}", entry.revision_command.shell);
            println!(
                "  metadata template: {}",
                entry.metadata_command_template.shell
            );
            println!(
                "  metadata after publish: {}",
                entry.metadata_after_publish_shell
            );
            for error in &entry.errors {
                println!("  error: {error}");
            }
        }
        println!("Apply artifact metadata:");
        println!("{}", report.apply_command.shell);
        if let Some(signature_command) = &report.signature_command {
            println!("Sign catalog draft:");
            println!("{}", signature_command.shell);
        }
        if let Some(verify_command) = &report.verify_command {
            println!("Verify signed launch sources:");
            println!("{}", verify_command.shell);
        } else {
            println!(
                "Verify signed launch sources: pass catalog signing args to emit this command."
            );
        }
        for error in &report.errors {
            println!("Global error: {error}");
        }
    }

    if !report.ok {
        bail!(
            "artifact publish command plan has {} error(s)",
            report.errors.len()
        );
    }
    Ok(())
}

fn catalog_artifact_plan_sign_options(
    args: &CatalogArtifactPlanArgs,
) -> Result<Option<CatalogCanaryPlanSignOptions>> {
    let requested = args.catalog_signature_output.is_some()
        || args.catalog_key_id.is_some()
        || args.catalog_seed_file.is_some()
        || args.catalog_keys_dir.is_some()
        || args.catalog_write_key
        || args.catalog_created_at.is_some();
    if !requested {
        return Ok(None);
    }
    let signature_output = args
        .catalog_signature_output
        .clone()
        .context("--catalog-signature-output is required when emitting a catalog sign command")?;
    let signature_output = absolutize(signature_output)?;
    let key_id = args
        .catalog_key_id
        .clone()
        .context("--catalog-key-id is required when emitting a catalog sign command")?;
    validate_catalog_key_id(&key_id)?;
    let seed_file = args
        .catalog_seed_file
        .clone()
        .context("--catalog-seed-file is required when emitting a catalog sign command")?;
    let seed_file = absolutize(seed_file)?;
    let keys_dir = args
        .catalog_keys_dir
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/keys"))?;
    let keys_dir = absolutize(keys_dir)?;
    Ok(Some(CatalogCanaryPlanSignOptions {
        signature_output,
        key_id,
        seed_file,
        keys_dir,
        write_key: args.catalog_write_key,
        created_at: args.catalog_created_at.clone(),
    }))
}

