async fn run_admin_reputation_anchor(args: &AdminReputationAnchorArgs) -> Result<()> {
    if args.interval_seconds == 0 {
        bail!("--interval-seconds must be positive");
    }
    if !args.all && args.provider.is_none() {
        bail!("pass --provider <pubkey> or --all");
    }
    if args.watch && (!args.tx.submit || args.tx.sim) {
        bail!("--watch requires --submit without --sim so the oracle can actually anchor");
    }

    let home = args.tx.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let rpc_url = resolve_cli_rpc_url(Some(&home), args.tx.rpc_url.as_deref())?;
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let mut scans = Vec::new();

    loop {
        let at = args.at.unwrap_or(unix_epoch_seconds()?);
        let epoch = match args.epoch {
            Some(epoch) => epoch,
            None => active_billing_epoch(&rpc).await?,
        };
        let providers = reputation_anchor_target_providers(&rpc, args).await?;
        let mut anchors = Vec::new();
        let mut skipped = Vec::new();
        for provider in providers {
            match build_reputation_anchor_feature(&rpc, &rpc_url, &provider, epoch, at).await {
                Ok(anchor) => anchors.push(anchor),
                Err(err) if args.all => skipped.push(json!({
                    "provider": provider,
                    "reason": err.to_string(),
                })),
                Err(err) => return Err(err),
            }
        }

        let mut submitted = Vec::new();
        if args.tx.submit && !args.tx.sim {
            for anchor in &anchors {
                let response = rpc.submit_feature(&anchor.feature).await.with_context(|| {
                    format!("submitting reputation anchor for {}", anchor.provider)
                })?;
                if response.get("ok").and_then(Value::as_bool) != Some(true) {
                    bail!(
                        "reputation anchor for {} was not accepted: {}",
                        anchor.provider,
                        response
                    );
                }
                submitted.push(json!({
                    "provider": anchor.provider,
                    "result": response,
                }));
            }
        }

        let scan = json!({
            "at": at,
            "epoch": epoch,
            "providers_scanned": anchors.len() + skipped.len(),
            "anchors": anchors,
            "skipped": skipped,
            "submitted": submitted,
        });

        if args.watch && !args.tx.json {
            print_reputation_anchor_scan_report(&scan)?;
        }
        scans.push(scan);

        if !args.watch {
            break;
        }
        sleep(Duration::from_secs(args.interval_seconds)).await;
    }

    let report = json!({
        "ok": true,
        "rpc_url": rpc_url,
        "watch": args.watch,
        "sim": args.tx.sim,
        "submitted": args.tx.submit && !args.tx.sim,
        "scan_count": scans.len(),
        "scans": scans,
    });
    if args.tx.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_reputation_anchor_report(&report)?;
    }
    Ok(())
}

#[derive(Debug, Clone, Serialize)]
struct ReputationAnchorReport {
    provider: String,
    event_count: usize,
    events_head: String,
    previous: Option<Value>,
    snapshot: Value,
    feature: Value,
    copy_paste: Value,
}

async fn reputation_anchor_target_providers(
    rpc: &PeerRpcClient,
    args: &AdminReputationAnchorArgs,
) -> Result<Vec<String>> {
    if let Some(provider) = args.provider.as_deref() {
        return Ok(vec![provider.to_owned()]);
    }
    let mut providers = read_prefix_entries(rpc, "ev/rep/head/")
        .await?
        .into_iter()
        .filter_map(|entry| {
            entry
                .key
                .strip_prefix("ev/rep/head/")
                .filter(|tail| !tail.contains('/'))
                .map(str::to_owned)
        })
        .collect::<Vec<_>>();
    providers.sort();
    providers.dedup();
    Ok(providers)
}

async fn build_reputation_anchor_feature(
    rpc: &PeerRpcClient,
    rpc_url: &str,
    provider: &str,
    epoch: u64,
    at: u64,
) -> Result<ReputationAnchorReport> {
    let provider_record = read_state_value(rpc, &format!("prov/{provider}"))
        .await?
        .with_context(|| format!("provider {provider} is not registered"))?;
    let head_record = read_state_value(rpc, &format!("ev/rep/head/{provider}"))
        .await?
        .with_context(|| format!("provider {provider} has no reputation event head"))?;
    let events_head = head_record
        .get("head")
        .and_then(Value::as_str)
        .filter(|head| is_hex_len(head, 64))
        .with_context(|| format!("provider {provider} reputation head is invalid"))?
        .to_owned();
    let mut event_entries = read_prefix_entries(rpc, &format!("ev/rep/{provider}/"))
        .await?
        .into_iter()
        .filter(|entry| entry.key != format!("ev/rep/head/{provider}"))
        .collect::<Vec<_>>();
    event_entries.sort_by(|left, right| {
        reputation_event_sort_key(left)
            .cmp(&reputation_event_sort_key(right))
            .then_with(|| left.key.cmp(&right.key))
    });
    let events = event_entries
        .iter()
        .map(contract_reputation_event_to_fold_event)
        .collect::<Result<Vec<_>>>()?;
    if events.is_empty() {
        bail!("provider {provider} has no reputation events to fold");
    }

    let policy = read_reputation_probation_policy(rpc, at).await?;
    let probation_since = provider_record
        .get("probation")
        .and_then(|probation| probation.get("since_seconds"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let folded = fold_reputation(provider, &events, at, epoch, probation_since, 0, &policy)
        .context("folding reputation events")?;
    let value = reputation_anchor_payload(
        provider,
        epoch,
        at,
        &events_head,
        folded.r_bps,
        folded.raw_milli,
        folded.probation.successful_sessions,
        folded.provenance_violation,
    );
    let key = reputation_anchor_feature_key(&value)?;
    let feature = json!({
        "feature": "mayhem",
        "key": key,
        "value": value,
    });
    let feature_json = serde_json::to_string(&feature)?;
    let previous = read_state_value(rpc, &format!("rep/{provider}")).await?;
    Ok(ReputationAnchorReport {
        provider: provider.to_owned(),
        event_count: events.len(),
        events_head,
        previous,
        snapshot: json!({
            "r_bps": folded.r_bps,
            "raw_milli": folded.raw_milli,
            "successful_sessions": folded.probation.successful_sessions,
            "provenance_violation": folded.provenance_violation,
            "folded_at": at,
            "epoch": epoch,
        }),
        feature,
        copy_paste: json!({
            "peer_rpc": format!(
                "curl -sS -X POST {}/contract/feature -H 'content-type: application/json' --data {}",
                shell_single_quote(rpc_url.trim_end_matches('/')),
                shell_single_quote(&feature_json)
            ),
        }),
    })
}

fn reputation_anchor_payload(
    provider: &str,
    epoch: u64,
    folded_at: u64,
    events_head: &str,
    r_bps: u32,
    raw_milli: i64,
    successful_sessions: u64,
    provenance_violation: bool,
) -> Value {
    let mut value = json!({
        "op": "anchor_reputation",
        "provider": provider,
        "epoch": epoch,
        "folded_at": folded_at,
        "events_head": events_head,
        "r_bps": r_bps,
        "raw_milli": raw_milli,
        "successful_sessions": successful_sessions,
    });
    if provenance_violation {
        value["provenance_violation"] = json!(true);
    }
    value
}

fn reputation_anchor_feature_key(value: &Value) -> Result<String> {
    if value.get("op").and_then(Value::as_str) != Some("anchor_reputation") {
        bail!("reputation anchor payload must have op=anchor_reputation");
    }
    let provider = value
        .get("provider")
        .and_then(Value::as_str)
        .context("reputation anchor payload missing provider")?;
    if !is_safe_key_part(provider) {
        bail!("reputation anchor provider is not contract-safe");
    }
    let epoch = value
        .get("epoch")
        .and_then(Value::as_u64)
        .context("reputation anchor payload missing epoch")?;
    let digest = stable_value_hash(&json!({
        "domain": "mayhem-reputation-anchor-feature-v1",
        "value": value,
    }));
    Ok(format!("rep/{provider}/{epoch}/{digest}"))
}

fn contract_reputation_event_to_fold_event(entry: &PrefixStateEntry) -> Result<ReputationEvent> {
    let value = &entry.value;
    let provider = value
        .get("provider")
        .and_then(Value::as_str)
        .with_context(|| format!("{} missing provider", entry.key))?
        .to_owned();
    let event_id = value
        .get("event_id")
        .and_then(Value::as_str)
        .with_context(|| format!("{} missing event_id", entry.key))?
        .to_owned();
    let epoch = value
        .get("epoch")
        .and_then(Value::as_u64)
        .with_context(|| format!("{} missing epoch", entry.key))?;
    let at_seconds = value
        .get("at")
        .and_then(Value::as_u64)
        .with_context(|| format!("{} missing at", entry.key))?;
    let evidence_hash = value
        .get("evidence_hash")
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_owned();
    let kind = match value
        .get("kind")
        .and_then(Value::as_str)
        .with_context(|| format!("{} missing kind", entry.key))?
    {
        "session_ok" => ReputationEventKind::SessionOk {
            paid_au: value
                .get("paid_au")
                .and_then(value_money_au)
                .with_context(|| format!("{} session_ok missing paid_au", entry.key))?,
        },
        "session_partial" => ReputationEventKind::SessionPartial {
            paid_au: value
                .get("paid_au")
                .and_then(value_money_au)
                .with_context(|| format!("{} session_partial missing paid_au", entry.key))?,
        },
        "session_fail" => ReputationEventKind::SessionFail {
            max_spend_au: value
                .get("max_spend_au")
                .and_then(value_money_au)
                .with_context(|| format!("{} session_fail missing max_spend_au", entry.key))?,
        },
        "probe_ok" => ReputationEventKind::ProbeOk,
        "probe_fail" => ReputationEventKind::ProbeFail,
        "uptime_tick" => ReputationEventKind::UptimeTick,
        "underdelivery" => ReputationEventKind::Underdelivery,
        "dispute_lost" => ReputationEventKind::DisputeLost,
        "provenance_violation" => ReputationEventKind::ProvenanceViolation,
        other => bail!(
            "{} has unsupported reputation event kind {other}",
            entry.key
        ),
    };
    Ok(ReputationEvent {
        provider,
        event_id,
        epoch,
        at_seconds,
        evidence_hash,
        kind,
    })
}

fn reputation_event_sort_key(entry: &PrefixStateEntry) -> (u64, u64, String) {
    (
        entry
            .value
            .get("epoch")
            .and_then(Value::as_u64)
            .unwrap_or(u64::MAX),
        entry
            .value
            .get("at")
            .and_then(Value::as_u64)
            .unwrap_or(u64::MAX),
        entry
            .value
            .get("event_id")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_owned(),
    )
}

async fn read_reputation_probation_policy(rpc: &PeerRpcClient, at: u64) -> Result<ProbationPolicy> {
    let default = ProbationPolicy::default();
    let default_caps = ProbationCaps::default();
    Ok(ProbationPolicy {
        required_successful_sessions: read_param_u64_at(
            rpc,
            "probation_successful_sessions",
            default.required_successful_sessions,
            at,
        )
        .await?,
        required_seconds: read_param_u64_at(rpc, "probation_seconds", default.required_seconds, at)
            .await?,
        caps: ProbationCaps {
            max_concurrent_sessions_per_user: read_param_u64_at(
                rpc,
                "probation_max_concurrent_sessions_per_user",
                u64::from(default_caps.max_concurrent_sessions_per_user),
                at,
            )
            .await?
            .try_into()
            .context("probation_max_concurrent_sessions_per_user exceeds u32")?,
            price_max_bps: read_param_u64_at(
                rpc,
                "probation_price_max_bps",
                u64::from(default_caps.price_max_bps),
                at,
            )
            .await?
            .try_into()
            .context("probation_price_max_bps exceeds u32")?,
            weight_bps: read_param_u64_at(
                rpc,
                "probation_weight_bps",
                u64::from(default_caps.weight_bps),
                at,
            )
            .await?
            .try_into()
            .context("probation_weight_bps exceeds u32")?,
        },
    })
}

fn admin_tx_args(command: &AdminCommands) -> &AdminTxArgs {
    match command {
        AdminCommands::SetRules(args) => &args.tx,
        AdminCommands::SetParams(args) => &args.tx,
        AdminCommands::SetModelRef(args) => &args.tx,
        AdminCommands::PublishCatalog(args) => &args.tx,
        AdminCommands::RegisterEnclave(args) => &args.tx,
        AdminCommands::UpdateEnclave(args) => &args.tx,
        AdminCommands::SetEnclaveMinTier(args) => &args.tx,
        AdminCommands::RetireEnclave(args) => &args.tx,
        AdminCommands::OpenRoom(args) => &args.tx,
        AdminCommands::CloseRoom(args) => &args.tx,
        AdminCommands::SetPrice(args) => &args.tx,
        AdminCommands::Price { command } => match command {
            AdminPriceCommands::Seed(args) => &args.tx,
        },
        AdminCommands::Fee { command } => match command {
            AdminFeeCommands::Set(args) => &args.tx,
        },
        AdminCommands::Disputes { .. } => {
            unreachable!("admin disputes are handled before admin_tx_args")
        }
        AdminCommands::SetProviderPayout(args) => &args.tx,
        AdminCommands::SetProviderKyb(args) => &args.tx,
        AdminCommands::RevokeProviderKyb(args) => &args.tx,
        AdminCommands::BanProvider(args) => &args.tx,
        AdminCommands::Ban { .. } => {
            unreachable!("admin ban list is handled before admin_tx_args")
        }
        AdminCommands::Unban(args) => &args.tx,
        AdminCommands::Device { command } => match command {
            AdminDeviceCommands::Rebind(args) => &args.tx,
        },
        AdminCommands::Tier3 { .. } => {
            unreachable!("admin tier3 commands are handled before admin_tx_args")
        }
        AdminCommands::AuditorRegister(args) => &args.tx,
        AdminCommands::ReputationAnchor(args) => &args.tx,
        AdminCommands::RateOracle(args) => &args.tx,
        AdminCommands::TapRateOracle(args) => &args.tx,
        AdminCommands::TnkSettlement(args) => &args.tx,
        AdminCommands::FiatSettlement(args) => &args.tx,
        AdminCommands::TnkDeposit(args) => &args.tx,
        AdminCommands::TapDeposit(args) => &args.tx,
        AdminCommands::FiatDeposit(args) => &args.tx,
        AdminCommands::FiatChargeback(args) => &args.tx,
        AdminCommands::PayoutConfirm(args) => &args.tx,
        AdminCommands::EpochCommit(args) => &args.tx,
        AdminCommands::EpochApply(args) => &args.tx,
    }
}

fn admin_command_payload(command: &AdminCommands) -> Result<(&'static str, Value)> {
    match command {
        AdminCommands::SetRules(args) => Ok(("setRules", admin_set_rules_payload(args))),
        AdminCommands::SetParams(args) => Ok(("setParams", admin_set_params_payload(args)?)),
        AdminCommands::SetModelRef(args) => Ok(("setModelRef", admin_set_model_ref_payload(args)?)),
        AdminCommands::PublishCatalog(args) => {
            Ok(("publishCatalog", admin_publish_catalog_payload(args)?))
        }
        AdminCommands::RegisterEnclave(args) => {
            Ok(("registerEnclave", admin_register_enclave_payload(args)?))
        }
        AdminCommands::UpdateEnclave(args) => {
            Ok(("updateEnclave", admin_update_enclave_payload(args)?))
        }
        AdminCommands::SetEnclaveMinTier(args) => Ok((
            "setEnclaveMinTier",
            admin_set_enclave_min_tier_payload(args)?,
        )),
        AdminCommands::RetireEnclave(args) => Ok((
            "retireEnclave",
            json!({
                "op": "retire_enclave",
                "enclave_id": &args.enclave_id,
            }),
        )),
        AdminCommands::OpenRoom(args) => Ok(("openRoom", admin_open_room_payload(args)?)),
        AdminCommands::CloseRoom(args) => Ok((
            "closeRoom",
            json!({
                "op": "close_room",
                "room_id": &args.room_id,
            }),
        )),
        AdminCommands::SetPrice(args) => Ok(("setPrice", admin_set_price_payload(args)?)),
        AdminCommands::Price { command } => match command {
            AdminPriceCommands::Seed(args) => Ok(("setPrice", admin_price_seed_payload(args)?)),
        },
        AdminCommands::Fee { command } => match command {
            AdminFeeCommands::Set(args) => Ok(("setParams", admin_fee_set_payload(args)?)),
        },
        AdminCommands::Disputes { .. } => {
            bail!("admin disputes are handled outside generic paid admin commands")
        }
        AdminCommands::SetProviderPayout(args) => Ok((
            "setProviderPayout",
            admin_set_provider_payout_payload(args)?,
        )),
        AdminCommands::SetProviderKyb(args) => {
            Ok(("setProviderKyb", admin_set_provider_kyb_payload(args)?))
        }
        AdminCommands::RevokeProviderKyb(args) => Ok((
            "revokeProviderKyb",
            admin_revoke_provider_kyb_payload(args)?,
        )),
        AdminCommands::BanProvider(args) => Ok(("banProvider", admin_ban_provider_payload(args)?)),
        AdminCommands::Ban { .. } => {
            bail!("admin ban list is read-only and handled outside generic paid admin commands")
        }
        AdminCommands::Unban(args) => Ok(("unban", admin_unban_payload(args)?)),
        AdminCommands::Device { command } => match command {
            AdminDeviceCommands::Rebind(args) => {
                Ok(("deviceRebind", admin_device_rebind_payload(args)?))
            }
        },
        AdminCommands::Tier3 { .. } => {
            bail!("admin tier3 commands are handled outside generic paid admin commands")
        }
        AdminCommands::AuditorRegister(args) => {
            Ok(("auditorRegister", admin_auditor_register_payload(args)))
        }
        AdminCommands::ReputationAnchor(_) => {
            bail!("reputation anchors are free features, not paid admin txs")
        }
        AdminCommands::RateOracle(_) | AdminCommands::TapRateOracle(_) => {
            bail!("rate oracle updates are free features, not paid admin txs")
        }
        AdminCommands::TnkSettlement(_) => {
            bail!("TNK settlement updates are free features, not paid admin txs")
        }
        AdminCommands::FiatSettlement(_) => {
            bail!("fiat settlement updates are free features, not paid admin txs")
        }
        AdminCommands::TnkDeposit(args) => Ok(("tnkDeposit", admin_tnk_deposit_payload(args))),
        AdminCommands::TapDeposit(args) => Ok(("tapDeposit", admin_tap_deposit_payload(args))),
        AdminCommands::FiatDeposit(args) => Ok(("fiatDeposit", admin_fiat_deposit_payload(args)?)),
        AdminCommands::FiatChargeback(args) => {
            Ok(("fiatChargeback", admin_fiat_chargeback_payload(args)?))
        }
        AdminCommands::PayoutConfirm(args) => {
            admin_payout_confirm_payload(args).map(|value| ("payoutConfirm", value))
        }
        AdminCommands::EpochCommit(args) => Ok(("epochCommit", admin_epoch_commit_payload(args)?)),
        AdminCommands::EpochApply(args) => Ok(("epochApply", admin_epoch_apply_payload(args)?)),
    }
}

async fn ensure_admin_command_signatures(args: &AdminTxArgs, value: &mut Value) -> Result<()> {
    if value.get("op").and_then(Value::as_str) != Some("set_provider_kyb")
        || value.get("admin_sig").is_some()
    {
        return Ok(());
    }
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let wallet_password = args.wallet_password.as_deref().unwrap_or("");
    let wallet = resolve_cli_wallet_with_keypair(
        &home,
        config.as_ref(),
        args.keypair.as_deref(),
        &args.peer_store_name,
        wallet_password,
    )
    .await?;
    let keypair_path = PathBuf::from(&wallet.keypair_path);
    let signature = sign_message(&keypair_path, wallet_password, &provider_kyb_message(value))
        .await
        .context("signing provider KYB record with admin wallet")?;
    value["admin_sig"] = json!(signature);
    Ok(())
}

fn admin_set_rules_payload(args: &AdminSetRulesArgs) -> Value {
    json!({
        "op": "set_rules",
        "ver": args.ver,
        "hash": &args.hash,
    })
}

fn admin_set_params_payload(args: &AdminSetParamsArgs) -> Result<Value> {
    let values = json_arg_or_file_object(
        args.values_json.as_deref(),
        args.values_file.as_ref(),
        None,
        "contract params",
    )?;
    Ok(json!({
        "op": "set_params",
        "submitted_at": args.submitted_at,
        "effective_at": args.effective_at,
        "values": values,
    }))
}

fn admin_set_model_ref_payload(args: &AdminSetModelRefArgs) -> Result<Value> {
    let rate_map = rate_map_arg_or_file(
        args.rate_map_json.as_deref(),
        args.rate_map_file.as_ref(),
        false,
        "model reference rate_map",
    )?;
    let mut payload = json!({
        "op": "set_model_ref",
        "model_id": &args.model,
        "model_class": &args.model_class,
        "rate_map": rate_map,
    });
    if let Some(source_hash) = &args.source_hash {
        payload["source_hash"] = json!(source_hash);
    }
    Ok(payload)
}

fn admin_publish_catalog_payload(args: &AdminPublishCatalogArgs) -> Result<Value> {
    validate_catalog_source_url(&args.source_kind, &args.catalog_url, "--catalog-url")?;
    validate_catalog_source_url(&args.source_kind, &args.signature_url, "--signature-url")?;
    validate_catalog_source_url(
        &args.source_kind,
        &args.canaries_base_url,
        "--canaries-base-url",
    )?;

    let catalog_path = args
        .catalog_path
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/models.json"))?;
    let catalog_path = absolutize(catalog_path)?;
    let signature_path = args
        .signature_path
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/signatures/models.json.sig"))?;
    let signature_path = absolutize(signature_path)?;
    let keys_dir = args
        .keys_dir
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/keys"))?;
    let keys_dir = absolutize(keys_dir)?;
    let canaries_dir = args
        .canaries_dir
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/canaries"))?;
    let canaries_dir = absolutize(canaries_dir)?;

    let report = catalog::verify(catalog::VerifyOptions {
        catalog_path: catalog_path.clone(),
        signature_path: signature_path.clone(),
        keys_dir,
        canaries_dir: canaries_dir.clone(),
        check_dev_downloads: false,
        check_launch_sources: false,
        hf_token_file: None,
    })?;
    if !report.ok {
        bail!("catalog verification failed; refusing to publish catalog anchor");
    }

    let catalog_doc = catalog::load_document(&catalog_path)?;
    let signature = read_json_file(&signature_path)
        .with_context(|| format!("reading {}", signature_path.display()))?;
    let key_id = required_json_string_for(&signature, "key_id", "catalog signature")?;
    let public_key = required_json_string_for(&signature, "public_key", "catalog signature")?;
    let signature_hash = blake3_file_hex(&signature_path)?;
    let canaries = report
        .canary_sets
        .iter()
        .map(|set_id| {
            let path = canaries_dir.join(format!("{set_id}.json"));
            Ok(json!({
                "set_id": set_id,
                "url": catalog_release_url_join(&args.canaries_base_url, &format!("{set_id}.json"))?,
                "hash": blake3_file_hex(&path)?,
            }))
        })
        .collect::<Result<Vec<_>>>()?;

    Ok(json!({
        "op": "publish_catalog",
        "catalog_id": catalog_doc.catalog_id,
        "source_kind": args.source_kind,
        "catalog_url": args.catalog_url,
        "signature_url": args.signature_url,
        "catalog_hash": report.catalog_hash,
        "signature_hash": signature_hash,
        "key_id": key_id,
        "public_key": public_key,
        "model_count": report.model_count,
        "artifact_count": report.artifact_count,
        "canaries": canaries,
    }))
}

fn admin_register_enclave_payload(args: &AdminRegisterEnclaveArgs) -> Result<Value> {
    validate_launch_enclave_attestation_tier(args.att_tier)?;
    let binding = validate_admin_enclave_catalog_binding(args)?;
    let mut caps = json_arg_or_file_object(
        args.caps_json.as_deref(),
        args.caps_file.as_ref(),
        None,
        "enclave caps",
    )?;
    enforce_backend_caps(&args.backend, &mut caps)?;
    let launch_measurements = optional_json_arg_or_file(
        args.launch_measurements_json.as_deref(),
        args.launch_measurements_file.as_ref(),
        "launch measurements",
    )?;
    if args.att_tier >= 3 && launch_measurements.is_none() {
        bail!("Tier-3 enclave registration requires --launch-measurements-json or --launch-measurements-file");
    }
    let mut payload = json!({
        "op": "register_enclave",
        "enclave_id": &args.enclave_id,
        "model_id": &args.model,
        "model_class": binding.model_class,
        "backend": &args.backend,
        "artifact_root": &args.artifact_root,
        "artifact_root_kind": &args.artifact_root_kind,
        "artifact_source": {
            "kind": "huggingface",
            "repo": &args.artifact_repo,
            "revision": args.artifact_revision.to_ascii_lowercase(),
            "path": &args.artifact_path,
        },
        "manifest_hash": &args.manifest_hash,
        "att_tier": args.att_tier,
        "quant": binding.quant,
        "binary_hash": &args.binary_hash,
        "caps": caps,
    });
    if let Some(launch_measurements) = launch_measurements {
        if !launch_measurements.is_object() {
            bail!("launch measurements JSON must be an object");
        }
        validate_admin_launch_measurements_json(&launch_measurements, args.att_tier >= 3)?;
        payload["launch_measurements"] = launch_measurements;
    }
    if let Some(source_sha256) = &args.source_sha256 {
        payload["source_sha256"] = json!(source_sha256.to_ascii_lowercase());
    }
    if !binding.artifact_sidecars.is_empty() {
        payload["artifact_sidecars"] = json!(binding.artifact_sidecars);
    }
    Ok(payload)
}

fn admin_update_enclave_payload(args: &AdminUpdateEnclaveArgs) -> Result<Value> {
    if let Some(att_tier) = args.att_tier {
        validate_launch_enclave_attestation_tier(att_tier)?;
    }

    let mut payload = json!({
        "op": "update_enclave",
        "enclave_id": &args.enclave_id,
    });
    let mut changed = false;

    changed |=
        insert_optional_payload_string(&mut payload, "model_class", &args.model_class, false);
    changed |= insert_optional_payload_string(&mut payload, "backend", &args.backend, false);
    changed |=
        insert_optional_payload_string(&mut payload, "artifact_root", &args.artifact_root, true);
    changed |= insert_optional_payload_string(
        &mut payload,
        "artifact_root_kind",
        &args.artifact_root_kind,
        false,
    );
    changed |=
        insert_optional_payload_string(&mut payload, "source_sha256", &args.source_sha256, true);
    changed |=
        insert_optional_payload_string(&mut payload, "manifest_hash", &args.manifest_hash, true);
    changed |= insert_optional_payload_string(&mut payload, "quant", &args.quant, false);
    changed |= insert_optional_payload_string(&mut payload, "binary_hash", &args.binary_hash, true);

    if let Some(att_tier) = args.att_tier {
        payload["att_tier"] = json!(att_tier);
        changed = true;
    }

    match (
        args.artifact_repo.as_ref(),
        args.artifact_revision.as_ref(),
        args.artifact_path.as_ref(),
    ) {
        (None, None, None) => {}
        (Some(repo), Some(revision), Some(path)) => {
            payload["artifact_source"] = json!({
                "kind": "huggingface",
                "repo": repo,
                "revision": revision.to_ascii_lowercase(),
                "path": path,
            });
            changed = true;
        }
        _ => bail!(
            "pass all of --artifact-repo, --artifact-revision, and --artifact-path when updating artifact_source"
        ),
    }

    if let Some(sidecars) = optional_json_arg_or_file(
        args.artifact_sidecars_json.as_deref(),
        args.artifact_sidecars_file.as_ref(),
        "artifact sidecars",
    )? {
        if !sidecars.is_object() {
            bail!("artifact sidecars JSON must be an object");
        }
        payload["artifact_sidecars"] = sidecars;
        changed = true;
    }

    if let Some(launch_measurements) = optional_json_arg_or_file(
        args.launch_measurements_json.as_deref(),
        args.launch_measurements_file.as_ref(),
        "launch measurements",
    )? {
        if !launch_measurements.is_object() {
            bail!("launch measurements JSON must be an object");
        }
        validate_admin_launch_measurements_json(
            &launch_measurements,
            args.att_tier.unwrap_or(3) >= 3,
        )?;
        payload["launch_measurements"] = launch_measurements;
        changed = true;
    }

    if let Some(mut caps) = optional_json_arg_or_file(
        args.caps_json.as_deref(),
        args.caps_file.as_ref(),
        "enclave caps",
    )? {
        if !caps.is_object() {
            bail!("enclave caps JSON must be an object");
        }
        if let Some(backend) = args.backend.as_deref() {
            enforce_backend_caps(backend, &mut caps)?;
        }
        payload["caps"] = caps;
        changed = true;
    }

    if !changed {
        bail!("pass at least one enclave field to update");
    }

    Ok(payload)
}

fn validate_admin_launch_measurements_json(value: &Value, tier3_required: bool) -> Result<()> {
    let Some(object) = value.as_object() else {
        bail!("launch measurements JSON must be an object");
    };
    if tier3_required {
        let platform = object
            .get("platform")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .context("Tier-3 launch measurements JSON must include platform")?;
        validate_tier3_platform(platform)?;
    }
    let mut total = 0usize;
    let mut workload_total = 0usize;
    if let Some(layers) = object.get("layers").and_then(Value::as_object) {
        for (layer, measurements) in layers {
            validate_tier3_measurement_layer(layer)?;
            let count = validate_admin_launch_measurement_map(layer, measurements)?;
            total += count;
            if layer == "workload" {
                workload_total += count;
            }
        }
    } else if let Some(measurements) = object.get("measurements") {
        let count = validate_admin_launch_measurement_map("workload", measurements)?;
        total += count;
        workload_total += count;
    } else {
        let count = validate_admin_launch_measurement_map("workload", value)?;
        total += count;
        workload_total += count;
    }
    if tier3_required && total == 0 {
        bail!("Tier-3 launch measurements JSON must include at least one measurement");
    }
    if tier3_required && workload_total == 0 {
        bail!("Tier-3 launch measurements JSON must include layers.workload for Mayhem PCR/stack identity");
    }
    Ok(())
}

fn validate_admin_launch_measurement_map(layer: &str, value: &Value) -> Result<usize> {
    validate_tier3_measurement_layer(layer)?;
    let Some(measurements) = value.as_object() else {
        bail!("launch measurements JSON {layer} layer must be an object");
    };
    let mut count = 0usize;
    for (name, value) in measurements {
        if matches!(
            name.as_str(),
            "schema_version" | "effective_epoch" | "platform" | "entries" | "layers"
        ) {
            continue;
        }
        validate_tier3_measurement_name(name)?;
        let mut values = BTreeSet::new();
        collect_launch_measurement_strings(value, &mut values);
        if values.is_empty() {
            bail!("launch measurements {layer}.{name} must contain at least one hex measurement");
        }
        count += values.len();
        for measurement in values {
            normalize_tier3_measurement(&measurement)?;
        }
    }
    Ok(count)
}

fn admin_set_enclave_min_tier_payload(args: &AdminSetEnclaveMinTierArgs) -> Result<Value> {
    validate_launch_enclave_attestation_tier(args.min_att_tier)?;
    if args.effective_epoch <= args.submitted_epoch {
        bail!("--effective-epoch must be after --submitted-epoch");
    }
    let reason_hash =
        admin_required_reason_hash(args.reason_hash.as_deref(), args.reason.as_deref())?;
    Ok(json!({
        "op": "set_enclave_min_tier",
        "enclave_id": &args.enclave_id,
        "min_att_tier": args.min_att_tier,
        "submitted_epoch": args.submitted_epoch,
        "effective_epoch": args.effective_epoch,
        "submitted_at": args.submitted_at,
        "reason_hash": reason_hash,
    }))
}

fn insert_optional_payload_string(
    payload: &mut Value,
    key: &str,
    value: &Option<String>,
    lowercase: bool,
) -> bool {
    let Some(value) = value else {
        return false;
    };
    let stored = if lowercase {
        value.to_ascii_lowercase()
    } else {
        value.clone()
    };
    payload[key] = json!(stored);
    true
}

fn validate_launch_enclave_attestation_tier(att_tier: u8) -> Result<()> {
    if att_tier <= mayhem_proto::TIER3_CONFIDENTIAL_COMPUTE_TIER {
        return Ok(());
    }
    bail!(
        "enclave attestation tiers above {} are not launch-advertisable; Tier 4 is provider KYB, not enclave hardware",
        mayhem_proto::TIER3_CONFIDENTIAL_COMPUTE_TIER
    )
}

fn enforce_backend_caps(backend: &str, caps: &mut Value) -> Result<()> {
    if !backend_supports_tool_calls(backend) {
        if caps.get("tools").and_then(Value::as_bool) == Some(true) {
            bail!(
                "backend {backend} cannot advertise caps.tools=true; register this enclave with caps.tools=false until real constrained decoding is wired"
            );
        }
        caps.as_object_mut()
            .context("enclave caps must be a JSON object")?
            .insert("tools".to_owned(), json!(false));
    }
    Ok(())
}

fn backend_supports_tool_calls(backend: &str) -> bool {
    !matches!(backend, "mlx" | "trt-llm")
}

#[derive(Debug)]
struct AdminEnclaveCatalogBinding {
    model_class: String,
    quant: String,
    artifact_sidecars: BTreeMap<String, CatalogSidecarPayload>,
}

#[derive(Debug, Serialize)]
struct CatalogSidecarPayload {
    source: LedgerArtifactSource,
    path: String,
    artifact_root: String,
    artifact_root_kind: String,
    weights_bytes: u64,
    source_sha256: String,
}

fn validate_admin_enclave_catalog_binding(
    args: &AdminRegisterEnclaveArgs,
) -> Result<AdminEnclaveCatalogBinding> {
    let catalog_path = args
        .catalog_path
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/models.json"))?;
    let catalog_path = absolutize(catalog_path)?;
    if args.dev_skip_catalog_verify {
        if !cfg!(debug_assertions) {
            bail!(
                "--dev-skip-catalog-verify is only available in debug builds for local smoke fixtures"
            );
        }
    } else {
        let signature_path = args
            .signature_path
            .clone()
            .map(Ok)
            .unwrap_or_else(|| repo_path("catalog/signatures/models.json.sig"))?;
        let keys_dir = args
            .keys_dir
            .clone()
            .map(Ok)
            .unwrap_or_else(|| repo_path("catalog/keys"))?;
        let canaries_dir = args
            .canaries_dir
            .clone()
            .map(Ok)
            .unwrap_or_else(|| repo_path("catalog/canaries"))?;
        let report = catalog::verify(catalog::VerifyOptions {
            catalog_path: catalog_path.clone(),
            signature_path: absolutize(signature_path)?,
            keys_dir: absolutize(keys_dir)?,
            canaries_dir: absolutize(canaries_dir)?,
            check_dev_downloads: false,
            check_launch_sources: false,
            hf_token_file: None,
        })?;
        if !report.ok {
            bail!(
                "signed admin catalog verification failed for register-enclave: {}",
                report.errors.join("; ")
            );
        }
    }

    let catalog_doc = catalog::load_document(&catalog_path)?;
    let model = catalog_doc
        .models
        .iter()
        .find(|model| model.model_id == args.model)
        .with_context(|| {
            format!(
                "--model {} is not present in admin catalog {}",
                args.model,
                catalog_path.display()
            )
        })?;
    let Some((artifact_name, artifact)) = model.artifacts.iter().find(|(_, artifact)| {
        artifact.engine == args.backend
            && artifact.source.kind == "huggingface"
            && artifact.source.repo == args.artifact_repo
            && artifact
                .source
                .revision
                .eq_ignore_ascii_case(&args.artifact_revision)
            && artifact.path == args.artifact_path
    }) else {
        bail!(
            "register-enclave source is not greenlit: no admin catalog artifact for model {}, backend {}, Hugging Face {}/resolve/{}/{}",
            args.model,
            args.backend,
            args.artifact_repo,
            args.artifact_revision,
            args.artifact_path
        );
    };
    ensure_catalog_text_match(
        "artifact_root_kind",
        &args.artifact_root_kind,
        &artifact.artifact_root_kind,
    )?;
    ensure_catalog_hex_match(
        "artifact_root",
        &args.artifact_root,
        &artifact.artifact_root,
    )?;
    ensure_catalog_optional_hex_match(
        "source_sha256",
        args.source_sha256.as_deref(),
        artifact.source_sha256.as_deref(),
    )?;
    let catalog_quant = quant_bucket_from_catalog_artifact(artifact_name, artifact);
    let quant = match args.quant.as_deref() {
        Some(requested) => {
            let requested = normalize_quant_bucket(requested)?;
            if catalog_quant != DEFAULT_QUANT_BUCKET && requested != catalog_quant {
                bail!(
                    "register-enclave quant mismatch: requested {requested}, signed catalog artifact {artifact_name} implies {catalog_quant}"
                );
            }
            requested
        }
        None => catalog_quant,
    };
    Ok(AdminEnclaveCatalogBinding {
        model_class: model.model_class.clone(),
        quant,
        artifact_sidecars: artifact
            .sidecars
            .iter()
            .map(|(name, sidecar)| {
                (
                    name.clone(),
                    CatalogSidecarPayload {
                        source: LedgerArtifactSource {
                            kind: sidecar.source.kind.clone(),
                            repo: sidecar.source.repo.clone(),
                            revision: sidecar.source.revision.to_ascii_lowercase(),
                            path: sidecar.path.clone(),
                        },
                        path: sidecar.path.clone(),
                        artifact_root: sidecar.artifact_root.clone(),
                        artifact_root_kind: sidecar.artifact_root_kind.clone(),
                        weights_bytes: sidecar.weights_bytes,
                        source_sha256: sidecar.source_sha256.to_ascii_lowercase(),
                    },
                )
            })
            .collect(),
    })
}

fn ensure_catalog_text_match(label: &str, requested: &str, catalog: &str) -> Result<()> {
    if requested == catalog {
        return Ok(());
    }
    bail!("register-enclave {label} mismatch: requested {requested}, signed catalog has {catalog}")
}

fn ensure_catalog_hex_match(label: &str, requested: &str, catalog: &str) -> Result<()> {
    if requested.eq_ignore_ascii_case(catalog) {
        return Ok(());
    }
    bail!("register-enclave {label} mismatch: requested {requested}, signed catalog has {catalog}")
}

fn ensure_catalog_optional_hex_match(
    label: &str,
    requested: Option<&str>,
    catalog: Option<&str>,
) -> Result<()> {
    match (requested, catalog) {
        (Some(left), Some(right)) if left.eq_ignore_ascii_case(right) => Ok(()),
        (None, None) => Ok(()),
        (Some(left), Some(right)) => {
            bail!("register-enclave {label} mismatch: requested {left}, signed catalog has {right}")
        }
        (None, Some(right)) => bail!(
            "register-enclave {label} mismatch: requested <missing>, signed catalog has {right}"
        ),
        (Some(left), None) => bail!(
            "register-enclave {label} mismatch: requested {left}, signed catalog has <missing>"
        ),
    }
}

fn normalize_quant_bucket(value: &str) -> Result<String> {
    let normalized = value.trim().to_ascii_lowercase().replace('_', "-");
    if normalized.is_empty() {
        bail!("quant bucket must not be empty");
    }
    if matches!(
        normalized.as_str(),
        "unknown" | "fp32" | "fp16" | "bf16" | "fp8" | "nvfp4" | "int8" | "int4"
    ) {
        return Ok(normalized);
    }
    let inferred = quant_bucket_from_descriptor(&normalized);
    if inferred != DEFAULT_QUANT_BUCKET {
        return Ok(inferred);
    }
    bail!("quant bucket must be one of fp32, fp16, bf16, fp8, nvfp4, int8, int4, unknown")
}

fn default_quant_bucket() -> String {
    DEFAULT_QUANT_BUCKET.to_owned()
}

fn quant_bucket_from_catalog_artifact(name: &str, artifact: &catalog::CatalogArtifact) -> String {
    let descriptor = format!(
        "{} {} {}",
        name.to_ascii_lowercase(),
        artifact.engine.to_ascii_lowercase(),
        artifact.path.to_ascii_lowercase()
    );
    quant_bucket_from_descriptor(&descriptor)
}

fn quant_bucket_from_descriptor(descriptor: &str) -> String {
    let descriptor = descriptor.replace('_', "-");
    if descriptor.contains("nvfp4") {
        "nvfp4".to_owned()
    } else if descriptor.contains("fp8") {
        "fp8".to_owned()
    } else if descriptor.contains("bf16") {
        "bf16".to_owned()
    } else if descriptor.contains("fp16") || descriptor.contains("f16") {
        "fp16".to_owned()
    } else if descriptor.contains("int8")
        || descriptor.contains("8bit")
        || descriptor.contains("q8")
    {
        "int8".to_owned()
    } else if descriptor.contains("int4")
        || descriptor.contains("4bit")
        || descriptor.contains("q4")
    {
        "int4".to_owned()
    } else {
        DEFAULT_QUANT_BUCKET.to_owned()
    }
}

fn admin_open_room_payload(args: &AdminOpenRoomArgs) -> Result<Value> {
    let policy = json_arg_or_file_object(
        args.policy_json.as_deref(),
        args.policy_file.as_ref(),
        Some(json!({})),
        "room policy",
    )?;
    let mut payload = json!({
        "op": "open_room",
        "enclave_id": &args.enclave_id,
        "nonce": &args.nonce,
        "label": &args.label,
        "policy": policy,
    });
    if let Some(model) = &args.model {
        payload["model_id"] = json!(model);
    }
    Ok(payload)
}

fn admin_set_price_payload(args: &AdminSetPriceArgs) -> Result<Value> {
    let rate_map = rate_map_arg_or_file(
        args.rate_map_json.as_deref(),
        args.rate_map_file.as_ref(),
        true,
        "price rate_map",
    )?;
    let mut payload = json!({
        "op": "set_price",
        "enclave_id": &args.enclave_id,
        "rate_map": rate_map,
        "per_req_au": money_au_json(args.per_req_au),
        "min_session_au": money_au_json(args.min_session_au),
        "effective_at": args.effective_at,
    });
    if let Some(ctx_bracket) = &args.ctx_bracket {
        payload["ctx_bracket"] = json!(ctx_bracket);
    }
    Ok(payload)
}

