fn admin_epoch_commit_payload(args: &AdminEpochCommitArgs) -> Result<Value> {
    let recomputed = read_optional_json_file(args.recomputed_file.as_ref(), "recomputed epoch")?;
    let epoch = epoch_arg_or_recomputed(args.epoch, recomputed.as_ref())?;
    let roots = json_arg_or_file_object(
        args.roots_json.as_deref(),
        args.roots_file.as_ref(),
        recomputed_field(recomputed.as_ref(), "roots"),
        "epoch roots",
    )?;
    let totals = json_arg_or_file_object(
        args.totals_json.as_deref(),
        args.totals_file.as_ref(),
        recomputed_field(recomputed.as_ref(), "totals"),
        "epoch totals",
    )?;

    Ok(json!({
        "op": "epoch_commit",
        "epoch": epoch,
        "at": args.at,
        "roots": roots,
        "totals": totals,
    }))
}

fn admin_epoch_apply_payload(args: &AdminEpochApplyArgs) -> Result<Value> {
    let recomputed = read_optional_json_file(args.recomputed_file.as_ref(), "recomputed epoch")?;
    let epoch = epoch_arg_or_recomputed(args.epoch, recomputed.as_ref())?;
    let paged = args.page.is_some() || args.last_page;
    let debits = json_arg_or_file_array(
        args.debits_json.as_deref(),
        args.debits_file.as_ref(),
        recomputed_field(recomputed.as_ref(), "debits").or_else(|| Some(json!([]))),
        "epoch debits",
    )?;
    let earnings = json_arg_or_file_array(
        args.earnings_json.as_deref(),
        args.earnings_file.as_ref(),
        recomputed_field(recomputed.as_ref(), "earnings").or_else(|| Some(json!([]))),
        "epoch earnings",
    )?;
    let explicit_market_usage = optional_json_arg_or_file(
        args.market_usage_json.as_deref(),
        args.market_usage_file.as_ref(),
        "epoch market usage",
    )?;
    let market_usage =
        explicit_market_usage.or_else(|| recomputed_market_usage_for_apply(recomputed.as_ref()));
    if let Some(value) = market_usage.as_ref() {
        ensure_json_array(value, "epoch market usage")?;
    }
    let mut payload = json!({
        "op": "epoch_apply",
        "epoch": epoch,
        "at": args.at,
        "debits": debits,
        "earnings": earnings,
    });
    if paged {
        if args.roots_json.is_some()
            || args.roots_file.is_some()
            || args.totals_json.is_some()
            || args.totals_file.is_some()
        {
            bail!("paged epoch apply pages must omit aggregate roots and totals");
        }
        payload["page"] = json!(args.page.unwrap_or(0));
        payload["last_page"] = json!(args.last_page);
    } else {
        let roots = json_arg_or_file_object(
            args.roots_json.as_deref(),
            args.roots_file.as_ref(),
            recomputed_field(recomputed.as_ref(), "roots"),
            "epoch roots",
        )?;
        let totals = json_arg_or_file_object(
            args.totals_json.as_deref(),
            args.totals_file.as_ref(),
            recomputed_field(recomputed.as_ref(), "totals"),
            "epoch totals",
        )?;
        payload["roots"] = roots;
        payload["totals"] = totals;
    }
    if let Some(market_usage) = market_usage {
        payload["market_usage"] = market_usage;
    }
    Ok(payload)
}

fn epoch_apply_feature_key(value: &Value) -> Result<String> {
    let epoch = value
        .get("epoch")
        .and_then(Value::as_u64)
        .context("epoch apply payload missing epoch")?;
    let digest = stable_value_hash(&json!({
        "domain": "mayhem-epoch-apply-feature-v1",
        "value": value,
    }));
    Ok(format!("epoch/apply/{epoch}/{digest}"))
}

fn deposit_feature_key(value: &Value) -> Result<String> {
    let op = value
        .get("op")
        .and_then(Value::as_str)
        .context("deposit feature payload missing op")?;
    let digest = stable_value_hash(&json!({
        "domain": "mayhem-deposit-feature-v1",
        "value": value,
    }));
    match op {
        "deposit_tnk" => {
            let memo_hash = value
                .get("intent")
                .and_then(|intent| intent.get("memo_hash"))
                .and_then(Value::as_str)
                .context("deposit_tnk feature missing intent.memo_hash")?;
            Ok(format!("dep/tnk-intent/{memo_hash}/{digest}"))
        }
        "tnk_deposit" => {
            let memo_hash = value
                .get("memo_hash")
                .and_then(Value::as_str)
                .context("tnk_deposit feature missing memo_hash")?;
            Ok(format!("dep/tnk/{memo_hash}/{digest}"))
        }
        "tap_deposit" => {
            let eth_tx_hash = value
                .get("eth_tx_hash")
                .and_then(Value::as_str)
                .context("tap_deposit feature missing eth_tx_hash")?
                .to_ascii_lowercase();
            let log_index = value
                .get("log_index")
                .and_then(Value::as_u64)
                .context("tap_deposit feature missing log_index")?;
            Ok(format!("dep/tap/{eth_tx_hash}/{log_index}/{digest}"))
        }
        "fiat_deposit" => {
            let ext_ref_hash = value
                .get("ext_ref_hash")
                .and_then(Value::as_str)
                .context("fiat_deposit feature missing ext_ref_hash")?;
            Ok(format!("dep/fiat/{ext_ref_hash}"))
        }
        _ => bail!("unsupported deposit feature op {op}"),
    }
}

fn rate_feature_key(value: &Value) -> Result<String> {
    let op = value
        .get("op")
        .and_then(Value::as_str)
        .context("rate feature payload missing op")?;
    let ts = value
        .get("ts")
        .and_then(Value::as_u64)
        .context("rate feature payload missing ts")?;
    let kind = match op {
        "rate_oracle" => "tnk",
        "tap_rate_oracle" => "tap",
        _ => bail!("unsupported rate feature op {op}"),
    };
    let digest = stable_value_hash(&json!({
        "domain": "mayhem-rate-feature-v1",
        "value": value,
    }));
    Ok(format!("rate/{kind}/{ts}/{digest}"))
}

fn tnk_settlement_feature_key(value: &Value) -> Result<String> {
    let epoch = value
        .get("epoch")
        .and_then(Value::as_u64)
        .context("TNK settlement feature payload missing epoch")?;
    let digest = stable_value_hash(&json!({
        "domain": "mayhem-tnk-settlement-feature-v1",
        "value": value,
    }));
    Ok(format!("settle/tnk/{epoch}/{digest}"))
}

fn fiat_settlement_feature_key(value: &Value) -> Result<String> {
    let epoch = value
        .get("epoch")
        .and_then(Value::as_u64)
        .context("fiat settlement feature payload missing epoch")?;
    let digest = stable_value_hash(&json!({
        "domain": "mayhem-fiat-settlement-feature-v1",
        "value": value,
    }));
    Ok(format!("settle/fiat/{epoch}/{digest}"))
}

fn read_optional_json_file(path: Option<&PathBuf>, label: &str) -> Result<Option<Value>> {
    path.map(|path| {
        read_json_file(path)
            .with_context(|| format!("reading {label} JSON from {}", path.display()))
    })
    .transpose()
}

fn optional_json_arg_or_file(
    inline: Option<&str>,
    file: Option<&PathBuf>,
    label: &str,
) -> Result<Option<Value>> {
    match (inline, file) {
        (Some(_), Some(_)) => bail!("pass only one inline {label} JSON value or {label} JSON file"),
        (Some(inline), None) => serde_json::from_str::<Value>(inline)
            .with_context(|| format!("parsing {label} JSON"))
            .map(Some),
        (None, Some(path)) => read_json_file(path)
            .with_context(|| format!("reading {label} JSON from {}", path.display()))
            .map(Some),
        (None, None) => Ok(None),
    }
}

fn recomputed_field(recomputed: Option<&Value>, field: &str) -> Option<Value> {
    recomputed.and_then(|value| value.get(field).cloned())
}

fn recomputed_market_usage_for_apply(recomputed: Option<&Value>) -> Option<Value> {
    let recomputed = recomputed?;
    let price_count = recomputed
        .get("totals")
        .and_then(|totals| totals.get("price_count"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    if price_count == 0 {
        return None;
    }
    recomputed.get("market_usage").cloned()
}

fn ensure_json_array(value: &Value, label: &str) -> Result<()> {
    if !value.is_array() {
        bail!("{label} JSON must be an array");
    }
    Ok(())
}

fn epoch_arg_or_recomputed(epoch: Option<u64>, recomputed: Option<&Value>) -> Result<u64> {
    let epoch = epoch
        .or_else(|| recomputed.and_then(|value| value.get("epoch").and_then(Value::as_u64)))
        .context("--epoch is required when --recomputed-file does not contain epoch")?;
    if epoch == 0 {
        bail!("--epoch must be positive");
    }
    Ok(epoch)
}

fn json_arg_or_file_object(
    inline: Option<&str>,
    file: Option<&PathBuf>,
    default: Option<Value>,
    label: &str,
) -> Result<Value> {
    let value = match (inline, file) {
        (Some(_), Some(_)) => {
            bail!("pass only one inline {label} JSON value or {label} JSON file")
        }
        (Some(inline), None) => serde_json::from_str::<Value>(inline)
            .with_context(|| format!("parsing {label} JSON"))?,
        (None, Some(path)) => read_json_file(path)
            .with_context(|| format!("reading {label} JSON from {}", path.display()))?,
        (None, None) => default.with_context(|| format!("{label} JSON is required"))?,
    };
    if !value.is_object() {
        bail!("{label} JSON must be an object");
    }
    Ok(value)
}

fn json_arg_or_file_array(
    inline: Option<&str>,
    file: Option<&PathBuf>,
    default: Option<Value>,
    label: &str,
) -> Result<Value> {
    let value = match (inline, file) {
        (Some(_), Some(_)) => {
            bail!("pass only one inline {label} JSON value or {label} JSON file")
        }
        (Some(inline), None) => serde_json::from_str::<Value>(inline)
            .with_context(|| format!("parsing {label} JSON"))?,
        (None, Some(path)) => read_json_file(path)
            .with_context(|| format!("reading {label} JSON from {}", path.display()))?,
        (None, None) => default.with_context(|| format!("{label} JSON is required"))?,
    };
    if !value.is_array() {
        bail!("{label} JSON must be an array");
    }
    Ok(value)
}

async fn run_admin_command(
    args: &AdminTxArgs,
    tx_type: &'static str,
    value: Value,
    schedule_meta: Option<Value>,
) -> Result<()> {
    let compact_command = serde_json::to_string(&value)?;
    let copy_paste = format!(
        "/tx --command {} --sim 1",
        shell_single_quote(&compact_command)
    );
    let mut report = json!({
        "ok": true,
        "submitted": false,
        "tx_type": tx_type,
        "command": value,
        "copy_paste": {
            "intercom_sim": copy_paste,
        },
    });
    if let Some(schedule_meta) = schedule_meta {
        report["schedule"] = schedule_meta;
    }

    if args.submit {
        let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
        let home = absolutize(home)?;
        let config = read_mayhem_config(&home)?;
        let rpc_url = resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?;
        let wallet_password = args.wallet_password.as_deref().unwrap_or("");
        let wallet = resolve_cli_wallet_with_keypair(
            &home,
            config.as_ref(),
            args.keypair.as_deref(),
            &args.peer_store_name,
            wallet_password,
        )
        .await?;
        let keypair_path = PathBuf::from(&wallet.keypair_path);
        let rpc = PeerRpcClient::new(&rpc_url)?;
        let submitted = submit_contract_command(
            &rpc,
            &keypair_path,
            wallet_password,
            &wallet,
            tx_type,
            report["command"].clone(),
            args.sim,
        )
        .await?;
        report["submitted"] = json!(true);
        report["sim"] = json!(args.sim);
        report["rpc_url"] = json!(rpc_url);
        report["wallet"] = json!({
            "public_key": wallet.public_key,
            "keypair_path": wallet.keypair_path,
        });
        report["tx"] = submitted;
        if tx_type == "epochCommit" && !args.sim {
            let epoch = report["command"]
                .get("epoch")
                .and_then(Value::as_u64)
                .context("epochCommit command missing epoch")?;
            let key = format!("epoch/commit/{epoch}");
            report["commit_state"] = wait_for_state(&rpc, &key, |value| {
                value
                    .get("epoch")
                    .and_then(Value::as_u64)
                    .is_some_and(|updated| updated == epoch)
            })
            .await?;
        }
    }

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_admin_report(&report)?;
    }
    Ok(())
}

async fn run_admin_feature_command(
    args: &AdminTxArgs,
    feature_type: &'static str,
    key: String,
    value: Value,
) -> Result<()> {
    let feature = json!({
        "feature": "mayhem",
        "key": key,
        "value": value,
    });
    let feature_json = serde_json::to_string(&feature)?;
    let rpc_hint = args.rpc_url.as_deref().unwrap_or(DEFAULT_RPC_URL);
    let rpc_endpoint = format!("{}/contract/feature", rpc_hint.trim_end_matches('/'));
    let copy_paste = format!(
        "curl -sS -X POST {} -H 'content-type: application/json' --data {}",
        shell_single_quote(&rpc_endpoint),
        shell_single_quote(&feature_json)
    );
    let mut report = json!({
        "ok": true,
        "submitted": false,
        "feature_type": feature_type,
        "feature": feature,
        "copy_paste": {
            "peer_rpc": copy_paste,
        },
    });

    if args.submit && !args.sim {
        let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
        let home = absolutize(home)?;
        let rpc_url = resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?;
        let rpc = PeerRpcClient::new(&rpc_url)?;
        let submitted = rpc
            .submit_feature(&report["feature"])
            .await
            .with_context(|| format!("submitting free {feature_type} feature"))?;
        if submitted.get("ok").and_then(Value::as_bool) != Some(true) {
            bail!("{feature_type} feature was not accepted: {submitted}");
        }
        report["submitted"] = json!(true);
        report["rpc_url"] = json!(rpc_url);
        report["result"] = submitted;
        if feature_type == "epochApply" {
            let epoch = value
                .get("epoch")
                .and_then(Value::as_u64)
                .context("epochApply feature value missing epoch")?;
            let page = value.get("page").and_then(Value::as_u64);
            let last_page = value
                .get("last_page")
                .and_then(Value::as_bool)
                .unwrap_or(page.is_none());
            report["apply_state"] =
                wait_for_epoch_apply_state(&rpc, epoch, page, last_page).await?;
        }
    } else if args.submit && args.sim {
        report["sim"] = json!(true);
    }

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_admin_feature_report(&report)?;
    }
    Ok(())
}

async fn wait_for_epoch_apply_state(
    rpc: &PeerRpcClient,
    epoch: u64,
    page: Option<u64>,
    last_page: bool,
) -> Result<Value> {
    let mut last = Value::Null;
    for _ in 0..120 {
        last = read_state_value(rpc, "epoch/apply/state")
            .await?
            .unwrap_or(Value::Null);
        if page.is_some() && !last_page {
            if last
                .get("pending_epoch")
                .and_then(Value::as_u64)
                .is_some_and(|pending| pending == epoch)
                && last
                    .get("pending_next_page")
                    .and_then(Value::as_u64)
                    .is_some_and(|next| next == page.unwrap_or(0).saturating_add(1))
            {
                return Ok(last);
            }
        } else if last
            .get("updated_epoch")
            .and_then(Value::as_u64)
            .is_some_and(|updated| updated >= epoch)
        {
            return Ok(last);
        }
        sleep(Duration::from_millis(500)).await;
    }
    bail!("timed out waiting for epoch/apply/state to reach epoch {epoch}; last value: {last}")
}

fn print_admin_report(report: &Value) -> Result<()> {
    println!("Admin contract command ready.");
    println!("Tx type: {}", report["tx_type"].as_str().unwrap_or(""));
    println!("Command JSON:");
    println!("{}", serde_json::to_string_pretty(&report["command"])?);
    if let Some(schedule) = report.get("schedule").filter(|value| !value.is_null()) {
        println!(
            "Schedule: {}={} source={}",
            schedule["param"].as_str().unwrap_or(""),
            schedule["value"].as_u64().unwrap_or(0),
            schedule["source"].as_str().unwrap_or("")
        );
        if let Some(reason) = schedule["fallback_reason"].as_str() {
            println!("Schedule fallback reason: {reason}");
        }
    }
    println!("Copy/paste Intercom sim command:");
    println!(
        "{}",
        report["copy_paste"]["intercom_sim"].as_str().unwrap_or("")
    );
    if report["submitted"].as_bool() == Some(true) {
        println!("Submitted: true");
        if let Some(tx) = report["tx"]["tx"].as_str() {
            println!("Tx: {tx}");
        }
        if let Some(command_hash) = report["tx"]["command_hash"].as_str() {
            println!("Command hash: {command_hash}");
        }
    } else {
        println!("Submitted: false (pass --submit to sign and send through peer RPC)");
    }
    Ok(())
}

