fn component_error(error: impl std::fmt::Display) -> Value {
    json!({
        "ok": false,
        "error": error.to_string(),
    })
}

fn receipt_history_summary(entry: &Value) -> Value {
    let null = Value::Null;
    let body = receipt_body(entry).unwrap_or(&null);
    json!({
        "session_id": body.get("session_id").and_then(Value::as_str).unwrap_or(""),
        "seq": body.get("seq").and_then(Value::as_u64),
        "model_id": body.get("model_id").and_then(Value::as_str),
        "provider": body.get("provider").and_then(Value::as_str),
        "user": body.get("user").and_then(Value::as_str),
        "enclave_id": body.get("enclave_id").and_then(Value::as_str),
        "au_owed_cum": body.get("au_owed_cum").and_then(value_money_au).map(money_au_json),
        "usage": body.get("usage").cloned().unwrap_or(Value::Null),
        "ts": body.get("ts").and_then(Value::as_u64),
        "final": body.get("final").and_then(Value::as_bool),
        "receipt_hash": stable_value_hash(entry),
    })
}

fn receipt_history_matches(entry: &Value, args: &SessionHistoryArgs) -> bool {
    if let Some(session_id) = args.session_id.as_deref() {
        if entry.get("session_id").and_then(Value::as_str) != Some(session_id) {
            return false;
        }
    }
    if let Some(provider) = args.provider.as_deref() {
        if entry.get("provider").and_then(Value::as_str) != Some(provider) {
            return false;
        }
    }
    if let Some(model) = args.model.as_deref() {
        if entry.get("model_id").and_then(Value::as_str) != Some(model) {
            return false;
        }
    }
    true
}

fn group_session_summaries(entries_latest_first: &[Value]) -> Vec<Value> {
    let mut positions = BTreeMap::<String, usize>::new();
    let mut groups = Vec::<Value>::new();
    for entry in entries_latest_first {
        let session_id = entry
            .get("session_id")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_owned();
        let index = if let Some(index) = positions.get(&session_id) {
            *index
        } else {
            let index = groups.len();
            positions.insert(session_id.clone(), index);
            groups.push(json!({
                "session_id": session_id,
                "receipts": 0_u64,
                "latest": entry.clone(),
            }));
            index
        };
        if let Some(object) = groups[index].as_object_mut() {
            let receipts = object.get("receipts").and_then(Value::as_u64).unwrap_or(0) + 1;
            object.insert("receipts".to_owned(), Value::Number(receipts.into()));
        }
    }
    groups
}

fn print_status_report(report: &Value) {
    println!(
        "Mayhem status: {}",
        if report["ok"].as_bool() == Some(true) {
            "ok"
        } else {
            "degraded"
        }
    );
    println!("Home: {}", report["node"]["home"].as_str().unwrap_or(""));
    println!(
        "Wallet: {}",
        if report["wallet"]["ok"].as_bool() == Some(true) {
            report["wallet"]["public_key"].as_str().unwrap_or("")
        } else {
            report["wallet"]["error"].as_str().unwrap_or("unavailable")
        }
    );
    let supervisor = &report["supervisor"];
    if supervisor["expected"].as_bool() == Some(true) {
        if supervisor["ok"].as_bool() == Some(true) {
            let child_count = supervisor["status"]["children"]
                .as_object()
                .map(|children| children.len())
                .or_else(|| supervisor["children"].as_array().map(Vec::len))
                .unwrap_or(0);
            println!(
                "Mayhemd: ok pid={} children={}",
                supervisor["pid"].as_u64().unwrap_or(0),
                child_count
            );
        } else if supervisor["running"].as_bool() == Some(true) {
            println!(
                "Mayhemd: running but unhealthy ({})",
                supervisor["status"]["error"]
                    .as_str()
                    .unwrap_or("status unavailable")
            );
        } else {
            println!("Mayhemd: stopped");
        }
    } else {
        println!("Mayhemd: not started");
    }
    println!(
        "Peer RPC: {}",
        if report["peer"]["ok"].as_bool() == Some(true) {
            "ok"
        } else {
            report["peer"]["error"].as_str().unwrap_or("degraded")
        }
    );
    println!(
        "Gateway: {}",
        if report["gateway"]["ok"].as_bool() == Some(true) {
            "ok"
        } else {
            report["gateway"]["status"]["error"]
                .as_str()
                .unwrap_or("degraded")
        }
    );
    let status = &report["gateway"]["status"];
    if status["ok"].as_bool() == Some(true) {
        if let Some(message) = status
            .get("update_notice")
            .and_then(|notice| notice.get("message"))
            .and_then(Value::as_str)
        {
            println!("{message}");
        }
        println!(
            "Sessions: active={} paused={} receipts={}",
            status["sessions_active"].as_u64().unwrap_or(0),
            status["sessions_paused"].as_u64().unwrap_or(0),
            status["receipts"].as_u64().unwrap_or(0)
        );
        if let Some(access) = status.get("access") {
            let require_auth = access
                .get("require_auth")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            let token_count = access
                .get("token_count")
                .and_then(Value::as_u64)
                .unwrap_or(0);
            let active_token_count = access
                .get("active_token_count")
                .and_then(Value::as_u64)
                .unwrap_or(0);
            println!(
                "Gateway access: {} tokens={}/{}",
                if require_auth { "required" } else { "optional" },
                active_token_count,
                token_count
            );
            for token in access
                .get("tokens")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .take(8)
            {
                let name = token.get("name").and_then(Value::as_str).unwrap_or("token");
                let token_id = token
                    .get("token_id")
                    .and_then(Value::as_str)
                    .unwrap_or("tok_unknown");
                let spent = token
                    .get("spent_total_au")
                    .and_then(value_money_au)
                    .map(au_to_usd_amount)
                    .unwrap_or_else(|| "0.00".to_owned());
                let last_used = token
                    .get("last_used_at")
                    .and_then(Value::as_u64)
                    .map(|value| value.to_string())
                    .unwrap_or_else(|| "never".to_owned());
                println!("  {name} ({token_id}) spent=${spent} last={last_used}");
            }
        }
    }
}

fn print_session_history_report(report: &Value) -> Result<()> {
    if report["mode"].as_str() == Some("sessions") {
        println!("Recent sessions");
        for entry in report["sessions"].as_array().into_iter().flatten() {
            let latest = &entry["latest"];
            println!(
                "{} receipts={} provider={} model={} au={}",
                entry["session_id"].as_str().unwrap_or(""),
                entry["receipts"].as_u64().unwrap_or(0),
                latest["provider"].as_str().unwrap_or(""),
                latest["model_id"].as_str().unwrap_or(""),
                latest
                    .get("au_owed_cum")
                    .and_then(value_money_au)
                    .unwrap_or(0),
            );
        }
    } else {
        println!("Recent receipts");
        for entry in report["receipts"].as_array().into_iter().flatten() {
            println!(
                "{} seq={} provider={} model={} au={}",
                entry["session_id"].as_str().unwrap_or(""),
                entry["seq"].as_u64().unwrap_or(0),
                entry["provider"].as_str().unwrap_or(""),
                entry["model_id"].as_str().unwrap_or(""),
                entry
                    .get("au_owed_cum")
                    .and_then(value_money_au)
                    .unwrap_or(0),
            );
        }
    }
    if let Some(paused) = report["paused"]
        .as_array()
        .filter(|paused| !paused.is_empty())
    {
        println!("Paused sessions:");
        println!("{}", serde_json::to_string(paused)?);
    }
    Ok(())
}

fn print_reputation_report(report: &Value) {
    println!("Provider: {}", report["provider"].as_str().unwrap_or(""));
    if report["reputation"].is_null() {
        println!("Reputation: not anchored yet");
    } else {
        println!(
            "Reputation: {} bps (raw {} milli)",
            report["reputation"]["r_bps"].as_u64().unwrap_or(0),
            report["reputation"]["raw_milli"].as_u64().unwrap_or(0)
        );
        println!(
            "Probation active: {}",
            report["reputation"]["probation"]["active"]
                .as_bool()
                .unwrap_or(false)
        );
    }
    println!(
        "Earnings: total={} held={} paid={} claimable={} au_usd",
        report["earnings"]
            .get("total_au")
            .and_then(value_money_au)
            .unwrap_or(0),
        report["earnings"]
            .get("held_au")
            .and_then(value_money_au)
            .unwrap_or(0),
        report["earnings"]
            .get("paid_cum_au")
            .and_then(value_money_au)
            .unwrap_or(0),
        report["earnings"]
            .get("claimable_au")
            .and_then(value_money_au)
            .unwrap_or(0),
    );
}

fn config_get(args: ConfigGetArgs) -> Result<()> {
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let path = config_path_for_home(&home);
    let config = read_config_toml_value(&path)?;
    let key = args.key.as_deref().map(canonical_config_key).transpose()?;
    let value = key.and_then(|key| toml_get_path(&config, key));
    let value_json = value
        .map(serde_json::to_value)
        .transpose()?
        .unwrap_or(Value::Null);
    let report = json!({
        "ok": true,
        "home": home,
        "path": path,
        "key": key,
        "value": value_json,
        "config": serde_json::to_value(&config)?,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_config_get_report(&report, &config)?;
    }
    Ok(())
}

fn config_set(args: ConfigSetArgs) -> Result<()> {
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let path = config_path_for_home(&home);
    let key = canonical_config_key(&args.key)?;
    let mut config = read_config_toml_value(&path)?;
    if key == "user.max_price_au" {
        let value = args
            .value
            .trim()
            .parse::<MoneyAu>()
            .with_context(|| format!("{key} must be an integer value"))?;
        if value == 0 {
            bail!("{key} must be greater than zero");
        }
        toml_set_money_au(&mut config, key, value)?;
    } else if matches!(key, "user.min_ctx" | "user.max_wait_seconds") {
        let value = args
            .value
            .trim()
            .parse::<u64>()
            .with_context(|| format!("{key} must be an integer value"))?;
        if key == "user.min_ctx" && value == 0 {
            bail!("{key} must be greater than zero");
        }
        if key == "user.max_wait_seconds" && value > MAX_ROUTE_MAX_WAIT_MS / 1_000 {
            bail!(
                "user.max_wait_seconds must be <= {}",
                MAX_ROUTE_MAX_WAIT_MS / 1_000
            );
        }
        toml_set_u64(&mut config, key, value)?;
    } else {
        toml_set_string(&mut config, key, args.value.clone())?;
    }
    write_config_toml_value(&path, &config)?;
    let report = json!({
        "ok": true,
        "home": home,
        "path": path,
        "key": key,
        "value": args.value,
        "config": serde_json::to_value(&config)?,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!(
            "Set {} = {} in {}",
            report["key"].as_str().unwrap_or(""),
            report["value"].as_str().unwrap_or(""),
            report["path"].as_str().unwrap_or("")
        );
    }
    Ok(())
}

fn config_max_price(args: ConfigMaxPriceArgs) -> Result<()> {
    if args.clear && args.au.is_some() {
        bail!("pass either a max-price value or --clear, not both");
    }
    if args.au == Some(0) {
        bail!("max-price must be greater than 0; use --clear to remove the ceiling");
    }
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let path = config_path_for_home(&home);
    let mut config = read_config_toml_value(&path)?;
    let changed = args.clear || args.au.is_some();
    if args.clear {
        toml_remove_path(&mut config, "user.max_price_au")?;
    } else if let Some(au) = args.au {
        toml_set_money_au(&mut config, "user.max_price_au", au)?;
    }
    if changed {
        write_config_toml_value(&path, &config)?;
    }
    let value = toml_get_path(&config, "user.max_price_au").and_then(toml_value_money_au);
    let report = json!({
        "ok": true,
        "home": home,
        "path": path,
        "max_price_au": value.map(money_au_json),
        "cleared": args.clear,
        "changed": changed,
        "config": serde_json::to_value(&config)?,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else if let Some(au) = value {
        println!(
            "User max-price default: {au} au_usd in {}",
            report["path"].as_str().unwrap_or("")
        );
        println!("Per-request override header: X-Mayhem-Max-Price-Au");
    } else {
        println!(
            "User max-price default: off in {}",
            report["path"].as_str().unwrap_or("")
        );
    }
    Ok(())
}

async fn reset(args: ResetArgs, action: &'static str) -> Result<()> {
    if args.timeout_seconds == 0 {
        bail!("--timeout-seconds must be positive");
    }
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    if !args.yes {
        bail!(
            "refusing to {action} {}; pass --yes to remove local Mayhem state",
            home.display()
        );
    }
    let pid_file = mayhemd_pid_path(&home);
    let pid = read_pid_file(&pid_file)?;
    let running = pid.map(process_is_running).unwrap_or(false);
    if running && !args.force {
        let down_cmd = format!(
            "mayhem down --home {}",
            shell_single_quote(&home.display().to_string())
        );
        bail!(
            "refusing to {action} {} while mayhemd pid {} is running; run `{}` first or pass --force",
            home.display(),
            pid.unwrap_or_default(),
            down_cmd
        );
    }
    let down = if pid.is_some() {
        Some(down_home(&home, args.timeout_seconds, args.force).await?)
    } else {
        None
    };
    let removed = remove_local_state_path(&home)?;
    let report = json!({
        "ok": true,
        "action": action,
        "home": home,
        "down": down,
        "removed": removed,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else if removed {
        println!(
            "{} OK: removed {}",
            action,
            report["home"].as_str().unwrap_or("")
        );
    } else {
        println!(
            "{} OK: no local state existed at {}",
            action,
            report["home"].as_str().unwrap_or("")
        );
    }
    Ok(())
}

async fn opencode(args: OpencodeArgs) -> Result<()> {
    if args.timeout_seconds == 0 {
        bail!("--timeout-seconds must be positive");
    }

    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let gateway_root = resolve_cli_gateway_url(config.as_ref(), args.gateway_url.as_deref());
    let opencode_config_path = args
        .opencode_config
        .clone()
        .map(absolutize)
        .transpose()?
        .unwrap_or(default_opencode_config_path()?);

    let timeout = Duration::from_secs(args.timeout_seconds);
    let client = reqwest::Client::builder().timeout(timeout).build()?;
    let models = if args.sync_models || args.run_smoke {
        Some(fetch_gateway_models(&client, &gateway_root).await?)
    } else {
        None
    };
    let merge = merge_mayhem_opencode_config(
        &opencode_config_path,
        &gateway_root,
        models.as_deref(),
        args.sync_models,
    )?;
    let run = if args.run_smoke {
        let selected = select_test_model(
            models
                .as_deref()
                .context("gateway models must be fetched before opencode smoke")?,
            args.model.as_deref(),
        )?;
        let opencode_bin = resolve_opencode_bin(&home, args.opencode_bin.as_deref());
        serde_json::to_value(
            run_opencode_smoke(&opencode_bin, &opencode_config_path, &selected.id, timeout).await?,
        )?
    } else {
        json!({ "skipped": true })
    };
    let report = json!({
        "ok": true,
        "home": home,
        "gateway_url": gateway_root,
        "models_fetched": models.as_ref().map(Vec::len),
        "opencode": {
            "config": merge,
            "run": run,
        },
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_opencode_report(&report);
    }
    Ok(())
}

fn print_config_get_report(report: &Value, config: &toml::Value) -> Result<()> {
    println!("Config: {}", report["path"].as_str().unwrap_or(""));
    if let Some(key) = report["key"].as_str() {
        if report["value"].is_null() {
            println!("{key} is not set");
        } else {
            println!("{key} = {}", report["value"]);
        }
    } else {
        let text = toml::to_string_pretty(config)?;
        if text.trim().is_empty() {
            println!("(empty)");
        } else {
            print!("{text}");
        }
    }
    Ok(())
}

fn print_opencode_report(report: &Value) {
    println!("opencode wired.");
    println!("Gateway: {}", report["gateway_url"].as_str().unwrap_or(""));
    println!(
        "Config: {}",
        report["opencode"]["config"]["path"].as_str().unwrap_or("")
    );
    println!(
        "Provider: {} ({})",
        report["opencode"]["config"]["provider_id"]
            .as_str()
            .unwrap_or(""),
        report["opencode"]["config"]["base_url"]
            .as_str()
            .unwrap_or("")
    );
    if let Some(models) = report["models_fetched"].as_u64() {
        println!("Gateway models fetched: {models}");
    }
    if report["opencode"]["run"]["skipped"]
        .as_bool()
        .unwrap_or(false)
    {
        println!("Smoke: skipped");
    } else {
        println!(
            "Smoke: ok ({})",
            report["opencode"]["run"]["model"].as_str().unwrap_or("")
        );
    }
}

async fn mayhem_test(args: TestArgs) -> Result<()> {
    if args.timeout_seconds == 0 {
        bail!("--timeout-seconds must be positive");
    }

    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let gateway_url = resolve_cli_gateway_url(config.as_ref(), args.gateway_url.as_deref());
    let gateway_root = normalize_gateway_root(&gateway_url);
    let timeout = Duration::from_secs(args.timeout_seconds);
    let client = reqwest::Client::builder().timeout(timeout).build()?;

    let gateway_status =
        fetch_gateway_json(&client, &format!("{gateway_root}/mayhem/status")).await?;
    let models = fetch_gateway_models(&client, &gateway_root).await?;
    let selected_model = select_test_model(&models, args.model.as_deref())?;
    let direct_tool = if args.skip_direct_tool_smoke {
        json!({ "skipped": true })
    } else {
        run_gateway_tool_smoke(&client, &gateway_root, &selected_model.id).await?
    };

    let mut receipt_epoch_seconds = DEFAULT_EPOCH_SECONDS;
    let peer_health = if args.skip_peer_health {
        json!({ "skipped": true })
    } else {
        let rpc_url = resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?;
        let rpc = PeerRpcClient::new(&rpc_url)?;
        receipt_epoch_seconds = read_param_u64_at(
            &rpc,
            "epoch_seconds",
            DEFAULT_EPOCH_SECONDS,
            unix_epoch_seconds()?,
        )
        .await?;
        json!({
            "skipped": false,
            "rpc_url": rpc_url,
            "epoch_seconds": receipt_epoch_seconds,
            "health": rpc.health().await.context("checking peer RPC health")?,
        })
    };

    let opencode_config_path = args
        .opencode_config
        .clone()
        .map(absolutize)
        .transpose()?
        .unwrap_or(default_opencode_config_path()?);
    let existing_opencode_models =
        read_existing_mayhem_opencode_model_count(&opencode_config_path).unwrap_or(0);
    let should_write_models = args.sync_models
        || existing_opencode_models == 0
        || !opencode_model_exists(&opencode_config_path, &selected_model.id).unwrap_or(false);

    let opencode_merge = if args.skip_opencode {
        json!({ "skipped": true })
    } else {
        serde_json::to_value(merge_mayhem_opencode_config(
            &opencode_config_path,
            &gateway_root,
            if should_write_models {
                Some(&models)
            } else {
                None
            },
            should_write_models,
        )?)?
    };

    let opencode_run = if args.skip_opencode || args.no_opencode_run {
        json!({ "skipped": true })
    } else {
        let opencode_bin = resolve_opencode_bin(&home, args.opencode_bin.as_deref());
        serde_json::to_value(
            run_opencode_smoke(
                &opencode_bin,
                &opencode_config_path,
                &selected_model.id,
                timeout,
            )
            .await?,
        )?
    };

    let receipts = fetch_gateway_json(&client, &format!("{gateway_root}/mayhem/receipts")).await?;
    let receipt = latest_gateway_receipt(&receipts);
    let expected_evidence_key = receipt
        .as_ref()
        .and_then(|receipt| expected_usage_evidence_key(receipt, receipt_epoch_seconds))
        .unwrap_or_else(|| "ev/use/<epoch>".to_owned());

    let report = json!({
        "ok": true,
        "home": home,
        "role": config
            .as_ref()
            .and_then(|config| config.role.as_ref())
            .and_then(|role| role.mode.as_deref())
            .unwrap_or("unknown"),
        "gateway": {
            "url": gateway_root,
            "status": gateway_status,
            "models": models.len(),
            "selected_model": selected_model,
            "direct_tool_call": direct_tool,
        },
        "peer": peer_health,
        "opencode": {
            "config": opencode_merge,
            "run": opencode_run,
        },
        "receipt": receipt,
        "expected_epoch_evidence_key": expected_evidence_key,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_test_report(&report);
    }

    Ok(())
}

async fn price_show(args: PriceShowArgs) -> Result<()> {
    if args.timeout_seconds == 0 {
        bail!("--timeout-seconds must be positive");
    }
    if let Some(tier) = args.tier {
        if !(1..=4).contains(&tier) {
            bail!("--tier must be between 1 and 4");
        }
    }
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let gateway_root = resolve_cli_gateway_url(config.as_ref(), args.gateway_url.as_deref());
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(args.timeout_seconds))
        .build()?;
    let models = fetch_gateway_models(&client, &gateway_root).await?;
    let markets = price_show_markets_from_gateway_models(&models, &args.model, args.tier)?;
    let report = json!({
        "ok": true,
        "gateway_url": gateway_root,
        "target": args.model,
        "tier": args.tier,
        "markets": markets,
    });
    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_price_show_report(&report)?;
    }
    Ok(())
}

