fn attestation_summary_for_model(model: &Value) -> String {
    let tiers = model
        .get("attestation_tiers")
        .and_then(Value::as_object)
        .cloned()
        .unwrap_or_default();
    let labels = model
        .get("attestation_tier_labels")
        .and_then(Value::as_object)
        .cloned()
        .unwrap_or_default();
    let mut parts = tiers
        .iter()
        .filter_map(|(tier, count)| {
            let count = count.as_u64()?;
            let label = labels
                .get(tier)
                .and_then(Value::as_str)
                .unwrap_or("attestation tier");
            Some(format!("{tier}={count} {label}"))
        })
        .collect::<Vec<_>>();
    if parts.is_empty() {
        "T1=0 Tier 1 - software self-attestation; economic/trust only".to_owned()
    } else {
        parts.sort();
        let mut summary = parts.join("; ");
        if let Some(identity) = model
            .get("kyb_identities")
            .and_then(Value::as_array)
            .and_then(|identities| identities.first())
        {
            let legal_name = identity
                .get("legal_name")
                .and_then(Value::as_str)
                .unwrap_or("");
            let jurisdiction = identity
                .get("jurisdiction")
                .and_then(Value::as_str)
                .unwrap_or("");
            if !legal_name.is_empty() && !jurisdiction.is_empty() {
                summary.push_str(&format!(
                    "; Tier 4 - verified: {legal_name} ({jurisdiction})"
                ));
            }
        }
        summary
    }
}

