fn quant_summary_for_model(model: &Value) -> String {
    let buckets = model
        .get("quant_buckets")
        .and_then(Value::as_object)
        .cloned()
        .unwrap_or_default();
    let mut parts = buckets
        .iter()
        .filter_map(|(bucket, count)| count.as_u64().map(|count| format!("{bucket}:{count}")))
        .collect::<Vec<_>>();
    if parts.is_empty() {
        parts = model
            .get("route_candidates")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(|candidate| {
                candidate
                    .get("quant")
                    .and_then(Value::as_str)
                    .and_then(|quant| normalize_quant_bucket(quant).ok())
            })
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect();
    }
    if parts.is_empty() {
        DEFAULT_QUANT_BUCKET.to_owned()
    } else {
        parts.sort();
        parts.join(",")
    }
}

fn bool_mark(value: bool) -> &'static str {
    if value {
        "yes"
    } else {
        "no"
    }
}

fn truncate_for_table(value: &str, width: usize) -> String {
    let count = value.chars().count();
    if count <= width {
        return value.to_owned();
    }
    if width <= 1 {
        return ".".repeat(width);
    }
    let mut out = value.chars().take(width - 1).collect::<String>();
    out.push('.');
    out
}

async fn payouts(args: PayoutsArgs) -> Result<()> {
    let rpc_url = resolve_cli_rpc_url(args.home.as_ref(), args.rpc_url.as_deref())?;
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let report = if let Some(epoch) = args.epoch {
        json!({
            "rpc_url": rpc_url,
            "epoch": epoch,
            "claim_model": "tap_non_custodial_claim",
            "fee": read_state_value(&rpc, &format!("ev/fee/{epoch}")).await?,
        })
    } else {
        let mut fee_sweeps = read_prefix_entries(&rpc, "ev/fee/")
            .await?
            .into_iter()
            .filter(|entry| {
                entry
                    .value
                    .get("sweep_msb_tx_hash")
                    .and_then(Value::as_str)
                    .is_some()
            })
            .collect::<Vec<_>>();
        fee_sweeps.sort_by(|a, b| a.key.cmp(&b.key));
        json!({
            "rpc_url": rpc_url,
            "claim_model": "tap_non_custodial_claim",
            "fee_sweeps": fee_sweeps,
        })
    };

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_payouts_report(&report);
    }
    Ok(())
}

async fn earnings(args: EarningsArgs) -> Result<()> {
    let rpc_url = resolve_cli_rpc_url(args.home.as_ref(), args.rpc_url.as_deref())?;
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let records = if let Some(provider) = &args.provider {
        read_prefix_values::<LedgerEarningRecord>(&rpc, "earn/")
            .await?
            .into_iter()
            .filter(|record| record.provider == *provider)
            .collect::<Vec<_>>()
    } else {
        read_prefix_values(&rpc, "earn/").await?
    };
    let mut views = records
        .into_iter()
        .map(earning_view)
        .collect::<Result<Vec<_>>>()?;
    views.sort_by(|a, b| {
        a.provider
            .cmp(&b.provider)
            .then_with(|| a.rail.cmp(&b.rail))
    });
    let report = json!({
        "rpc_url": rpc_url,
        "earnings": views,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_earnings_report(&report);
    }
    Ok(())
}

async fn receipts_export(args: ReceiptsExportArgs) -> Result<()> {
    let deposits = read_optional_json_array(args.deposits_file.as_deref(), "deposits")?;
    let receipts = read_receipts_for_export(&args).await?;
    let payouts = read_optional_json_array(args.payouts_file.as_deref(), "payouts")?;
    let prior_earnings = read_prior_earnings(args.prior_earnings_file.as_deref())?;
    let bundle = EpochAuditBundle {
        epoch: args.epoch,
        params: EpochAuditParams {
            fee_bps: args.fee_bps,
        },
        deposits,
        receipts,
        payouts,
        prior_earnings,
        prior_fee_cum_au: args.prior_fee_cum_au,
    };

    let output_path = args
        .output
        .as_ref()
        .map(|path| absolutize(path.clone()))
        .transpose()?;
    if let Some(path) = &output_path {
        write_json_file(path, &bundle)?;
    }

    let mut cleanup_path = None;
    let verifier_input_path = if let Some(path) = &output_path {
        path.clone()
    } else if args.no_verify {
        PathBuf::new()
    } else {
        let path = temp_audit_bundle_path(args.epoch)?;
        write_json_file(&path, &bundle)?;
        cleanup_path = Some(path.clone());
        path
    };

    let mut report = ReceiptsExportReport {
        bundle,
        bundle_path: output_path.clone(),
        recomputed: None,
        evidence: None,
        checks: Vec::new(),
        verified: false,
    };

    if !args.no_verify {
        let verifier_script = args
            .verifier_script
            .clone()
            .map(Ok)
            .unwrap_or_else(|| repo_path("intercom/scripts/recompute-epoch-roots.mjs"))?;
        let verifier_script = absolutize(verifier_script)?;
        let recomputed = run_epoch_recompute_script(&verifier_script, &verifier_input_path).await?;
        let evidence = read_evidence_for_export(&args).await?;
        let checks = verify_epoch_evidence(args.epoch, &recomputed, &evidence);
        let verified = checks.iter().all(|check| check.ok);
        report.recomputed = Some(recomputed);
        report.evidence = Some(evidence);
        report.checks = checks;
        report.verified = verified;
        if !verified {
            bail!(
                "exported receipt bundle did not verify against ev/* records; rerun with --json for details"
            );
        }
    }

    if let Some(path) = cleanup_path {
        let _ = fs::remove_file(path);
    }

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else if output_path.is_none() {
        println!("{}", serde_json::to_string_pretty(&report.bundle)?);
    } else if report.verified {
        println!(
            "Receipt audit bundle verified for epoch {}: {} checks matched.",
            args.epoch,
            report.checks.len()
        );
    } else {
        println!("Receipt audit bundle written for epoch {}.", args.epoch);
    }
    Ok(())
}

async fn receipts_publish(args: ReceiptsPublishArgs) -> Result<()> {
    if args.poll_interval_ms == 0 {
        bail!("--poll-interval-ms must be positive");
    }
    let channel = epoch_sidechannel(args.epoch, args.channel.as_deref());
    let gateway_url = args
        .gateway_url
        .as_deref()
        .unwrap_or(DEFAULT_GATEWAY_URL)
        .trim_end_matches('/')
        .to_owned();
    let (sc_bridge_url, sc_bridge_token) = resolve_cli_sc_bridge(
        args.home.as_ref(),
        args.sc_bridge_url.as_deref(),
        args.sc_bridge_token.as_deref(),
    )?;
    let mut bridge = ScBridgeClient::connect(ScBridgeConfig::new(&sc_bridge_url, sc_bridge_token)?)
        .await
        .context("connecting to SC-Bridge for epoch receipt publish")?;
    bridge
        .join(&channel)
        .await
        .with_context(|| format!("joining sidechannel {channel}"))?;

    let deadline = (args.watch && args.timeout_seconds > 0)
        .then(|| Instant::now() + Duration::from_secs(args.timeout_seconds));
    let mut seen = BTreeSet::new();
    let mut published = 0usize;
    let mut messages_sent = 0usize;
    let max_message_bytes = epoch_receipt_max_message_bytes();

    loop {
        let receipts = fetch_gateway_receipts(&gateway_url).await?;
        for receipt in receipts {
            let receipt_id = receipt_id(&receipt);
            if !seen.insert(receipt_id.clone()) {
                continue;
            }
            let messages =
                epoch_receipt_messages(args.epoch, receipt_id, receipt, max_message_bytes)?;
            for message in messages {
                bridge
                    .send(&channel, &message)
                    .await
                    .with_context(|| format!("publishing receipt to {channel}"))?;
                messages_sent += 1;
            }
            published += 1;
            if args.max_receipts.is_some_and(|max| published >= max) {
                break;
            }
        }

        if !args.watch || args.max_receipts.is_some_and(|max| published >= max) {
            break;
        }
        if deadline.is_some_and(|deadline| Instant::now() >= deadline) {
            break;
        }
        sleep(Duration::from_millis(args.poll_interval_ms)).await;
    }

    let report = json!({
        "epoch": args.epoch,
        "channel": channel,
        "gateway_url": gateway_url,
        "published": published,
        "seen": seen.len(),
        "messages_sent": messages_sent,
        "max_message_bytes": max_message_bytes,
        "watch": args.watch,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!(
            "Published {} unique receipt(s) to {}.",
            report["published"].as_u64().unwrap_or_default(),
            report["channel"].as_str().unwrap_or("")
        );
    }
    Ok(())
}

async fn receipts_collect(args: ReceiptsCollectArgs) -> Result<()> {
    let channel = epoch_sidechannel(args.epoch, args.channel.as_deref());
    let (sc_bridge_url, sc_bridge_token) = resolve_cli_sc_bridge(
        args.home.as_ref(),
        args.sc_bridge_url.as_deref(),
        args.sc_bridge_token.as_deref(),
    )?;
    let mut bridge = ScBridgeClient::connect(ScBridgeConfig::new(&sc_bridge_url, sc_bridge_token)?)
        .await
        .context("connecting to SC-Bridge for epoch receipt collection")?;
    bridge
        .subscribe([channel.as_str()])
        .await
        .with_context(|| format!("subscribing to sidechannel {channel}"))?;
    bridge
        .join(&channel)
        .await
        .with_context(|| format!("joining sidechannel {channel}"))?;

    let deadline = Instant::now() + Duration::from_secs(args.timeout_seconds);
    let mut seen = BTreeSet::new();
    let mut receipts = Vec::new();
    let mut pending_payloads = PendingEpochReceiptPayloads::default();

    while Instant::now() < deadline {
        let remaining = deadline.saturating_duration_since(Instant::now());
        match bridge.next_sidechannel_message(remaining).await {
            Ok(event) => {
                let Some((receipt_id, receipt)) =
                    collect_epoch_receipt_from_sidechannel_event_with_pending(
                        &event,
                        args.epoch,
                        &channel,
                        &mut pending_payloads,
                    )?
                else {
                    continue;
                };
                if seen.insert(receipt_id) {
                    receipts.push(receipt);
                }
                if args.max_receipts.is_some_and(|max| receipts.len() >= max) {
                    break;
                }
            }
            Err(mayhem_bridge::BridgeError::Timeout) => break,
            Err(err) => return Err(err).context("collecting epoch receipt sidechannel message"),
        }
    }

    let output = json!({
        "schema_version": 1,
        "epoch": args.epoch,
        "channel": channel,
        "collected_at_ms": unix_epoch_millis()?,
        "data": receipts,
    });

    let output_path = args
        .output
        .as_ref()
        .map(|path| absolutize(path.clone()))
        .transpose()?;
    if let Some(path) = &output_path {
        write_json_file(path, &output)?;
    }

    let report = json!({
        "epoch": args.epoch,
        "channel": output["channel"],
        "receipts": output["data"].as_array().map(Vec::len).unwrap_or(0),
        "output": output_path,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else if let Some(path) = output_path {
        println!(
            "Collected {} unique receipt(s) from {}.",
            report["receipts"].as_u64().unwrap_or_default(),
            report["channel"].as_str().unwrap_or("")
        );
        println!("Copy/paste receipts file: {}", path.display());
    } else {
        println!("{}", serde_json::to_string_pretty(&output)?);
    }
    Ok(())
}

fn epoch_sidechannel(epoch: u64, requested: Option<&str>) -> String {
    requested
        .filter(|channel| !channel.trim().is_empty())
        .map(str::to_owned)
        .unwrap_or_else(|| format!("mx/epoch/{epoch}"))
}

fn receipt_id(receipt: &Value) -> String {
    if let Some(body) = receipt_body(receipt) {
        if let (Some(session_id), Some(seq)) = (
            body.get("session_id").and_then(Value::as_str),
            body.get("seq").and_then(Value::as_u64),
        ) {
            return format!("{session_id}:{seq}");
        }
    }
    blake3::hash(&serde_json::to_vec(receipt).unwrap_or_else(|_| Vec::new()))
        .to_hex()
        .to_string()
}

fn epoch_receipt_max_message_bytes() -> usize {
    std::env::var("MAYHEM_EPOCH_RECEIPT_MAX_MESSAGE_BYTES")
        .ok()
        .or_else(|| std::env::var("MAYHEM_SESSION_MAX_FRAME_BYTES").ok())
        .and_then(|value| value.trim().parse::<usize>().ok())
        .filter(|value| *value >= 8 * 1024)
        .unwrap_or(DEFAULT_SESSION_MAX_FRAME_BYTES)
}

fn epoch_receipt_payload_chunk_bytes(max_message_bytes: usize) -> usize {
    let safe_raw = max_message_bytes.saturating_sub(4096) / 3;
    DEFAULT_SESSION_PAYLOAD_CHUNK_BYTES.min(safe_raw.max(1024))
}

fn epoch_receipt_message_json_len(message: &Value) -> Result<usize> {
    serde_json::to_vec(message)
        .map(|bytes| bytes.len())
        .context("serializing epoch receipt sidechannel message")
}

fn epoch_receipt_messages(
    epoch: u64,
    receipt_id: String,
    receipt: Value,
    max_message_bytes: usize,
) -> Result<Vec<Value>> {
    let inline = epoch_receipt_message(epoch, receipt_id.clone(), receipt.clone())?;
    if epoch_receipt_message_json_len(&inline)? <= max_message_bytes {
        return Ok(vec![inline]);
    }

    let (manifest, chunks) = chunk_json_payload(
        &receipt,
        epoch_receipt_payload_chunk_bytes(max_message_bytes),
    )
    .context("chunking epoch receipt payload")?;
    let payload_id = manifest.blake3.clone();
    let mut messages = Vec::with_capacity(chunks.len().saturating_add(1));
    for chunk in chunks {
        let message = json!({
            "t": "epoch.receipt_chunk",
            "v": 1,
            "epoch": epoch,
            "receipt_id": receipt_id,
            "payload_id": payload_id,
            "chunk": chunk,
        });
        let len = epoch_receipt_message_json_len(&message)?;
        if len > max_message_bytes {
            bail!(
                "chunked epoch receipt message {len} bytes exceeds max {max_message_bytes} bytes"
            );
        }
        messages.push(message);
    }

    let ref_message = json!({
        "t": "epoch.receipt_ref",
        "v": 1,
        "epoch": epoch,
        "receipt_id": receipt_id,
        "payload_id": payload_id,
        "published_at_ms": unix_epoch_millis()?,
        "receipt_ref": manifest,
    });
    let ref_len = epoch_receipt_message_json_len(&ref_message)?;
    if ref_len > max_message_bytes {
        bail!(
            "epoch receipt manifest message {ref_len} bytes exceeds max {max_message_bytes} bytes"
        );
    }
    messages.push(ref_message);
    Ok(messages)
}

fn epoch_receipt_message(epoch: u64, receipt_id: String, receipt: Value) -> Result<Value> {
    Ok(json!({
        "t": "epoch.receipt",
        "v": 1,
        "epoch": epoch,
        "receipt_id": receipt_id,
        "published_at_ms": unix_epoch_millis()?,
        "receipt": receipt,
    }))
}

#[derive(Default)]
struct PendingEpochReceiptPayloads {
    chunks: BTreeMap<String, BTreeMap<u64, PayloadChunk>>,
    manifests: BTreeMap<String, PayloadChunkManifest>,
}

fn collect_epoch_receipt_from_sidechannel_event_with_pending(
    event: &Value,
    epoch: u64,
    channel: &str,
    pending: &mut PendingEpochReceiptPayloads,
) -> Result<Option<(String, Value)>> {
    if event.get("channel").and_then(Value::as_str) != Some(channel) {
        return Ok(None);
    }
    let Some(message) = event.get("message") else {
        return Ok(None);
    };
    if message.get("epoch").and_then(Value::as_u64) != Some(epoch) {
        return Ok(None);
    }
    match message.get("t").and_then(Value::as_str) {
        Some("epoch.receipt") => {
            let Some(receipt) = message
                .get("receipt")
                .filter(|value| !value.is_null())
                .cloned()
            else {
                return Ok(None);
            };
            let receipt_id = message
                .get("receipt_id")
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty())
                .map(str::to_owned)
                .unwrap_or_else(|| receipt_id(&receipt));
            Ok(Some((receipt_id, receipt)))
        }
        Some("epoch.receipt_chunk") => {
            let receipt_id =
                required_json_string_for(message, "receipt_id", "epoch receipt chunk")?;
            let payload_id =
                required_json_string_for(message, "payload_id", "epoch receipt chunk")?;
            let chunk: PayloadChunk = serde_json::from_value(
                message
                    .get("chunk")
                    .cloned()
                    .context("epoch receipt chunk missing chunk")?,
            )
            .context("decoding epoch receipt chunk")?;
            let key = epoch_receipt_payload_key(epoch, &receipt_id, &payload_id);
            let by_index = pending.chunks.entry(key.clone()).or_default();
            if let Some(existing) = by_index.get(&chunk.i) {
                if existing != &chunk {
                    bail!("conflicting epoch receipt chunk {} for {key}", chunk.i);
                }
            } else {
                by_index.insert(chunk.i, chunk);
            }
            try_reassemble_epoch_receipt_payload(pending, epoch, &receipt_id, &payload_id)
        }
        Some("epoch.receipt_ref") => {
            let receipt_id = required_json_string_for(message, "receipt_id", "epoch receipt ref")?;
            let payload_id = required_json_string_for(message, "payload_id", "epoch receipt ref")?;
            let manifest: PayloadChunkManifest = serde_json::from_value(
                message
                    .get("receipt_ref")
                    .cloned()
                    .context("epoch receipt ref missing receipt_ref")?,
            )
            .context("decoding epoch receipt ref manifest")?;
            if manifest.blake3 != payload_id {
                bail!("epoch receipt ref payload_id does not match manifest blake3");
            }
            let key = epoch_receipt_payload_key(epoch, &receipt_id, &payload_id);
            pending.manifests.insert(key, manifest);
            try_reassemble_epoch_receipt_payload(pending, epoch, &receipt_id, &payload_id)
        }
        _ => Ok(None),
    }
}

fn epoch_receipt_payload_key(epoch: u64, receipt_id: &str, payload_id: &str) -> String {
    format!("{epoch}:{receipt_id}:{payload_id}")
}

fn try_reassemble_epoch_receipt_payload(
    pending: &mut PendingEpochReceiptPayloads,
    epoch: u64,
    receipt_id: &str,
    payload_id: &str,
) -> Result<Option<(String, Value)>> {
    let key = epoch_receipt_payload_key(epoch, receipt_id, payload_id);
    let Some(manifest) = pending.manifests.get(&key) else {
        return Ok(None);
    };
    let Some(chunks_by_index) = pending.chunks.get(&key) else {
        return Ok(None);
    };
    let expected_count =
        usize::try_from(manifest.chunk_count).context("epoch receipt chunk count overflow")?;
    if chunks_by_index.len() < expected_count {
        return Ok(None);
    }
    let chunks = chunks_by_index.values().cloned().collect::<Vec<_>>();
    let receipt = reassemble_json_payload(manifest, &chunks)
        .with_context(|| format!("reassembling epoch receipt {receipt_id} payload"))?;
    pending.manifests.remove(&key);
    pending.chunks.remove(&key);
    Ok(Some((receipt_id.to_owned(), receipt)))
}

fn resolve_cli_sc_bridge(
    home: Option<&PathBuf>,
    sc_bridge_url: Option<&str>,
    sc_bridge_token: Option<&str>,
) -> Result<(String, String)> {
    let home = home.cloned().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let url = sc_bridge_url
        .filter(|value| !value.trim().is_empty())
        .map(str::to_owned)
        .or_else(|| env::var("MAYHEM_SC_BRIDGE_URL").ok())
        .or_else(|| {
            config
                .as_ref()
                .and_then(|config| config.network.as_ref())
                .and_then(|network| network.sc_bridge_url.clone())
        })
        .unwrap_or_else(|| DEFAULT_SC_BRIDGE_URL.to_owned());
    let token = sc_bridge_token
        .filter(|value| !value.trim().is_empty())
        .map(str::to_owned)
        .or_else(|| env::var("MAYHEM_SC_BRIDGE_TOKEN").ok())
        .or_else(|| {
            config
                .as_ref()
                .and_then(|config| config.network.as_ref())
                .and_then(|network| network.sc_bridge_token.clone())
        })
        .context(
            "SC-Bridge token is required; pass --sc-bridge-token or set MAYHEM_SC_BRIDGE_TOKEN",
        )?;
    Ok((url, token))
}

fn resolve_cli_rpc_url(home: Option<&PathBuf>, rpc_url: Option<&str>) -> Result<String> {
    if let Some(rpc_url) = rpc_url {
        if !rpc_url.trim().is_empty() {
            return Ok(rpc_url.to_owned());
        }
    }
    let home = home.cloned().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    Ok(config
        .and_then(|config| config.network)
        .and_then(|network| network.rpc_url)
        .unwrap_or_else(|| DEFAULT_RPC_URL.to_owned()))
}

fn resolve_cli_paygate_url(config: Option<&MayhemConfig>, paygate_url: Option<&str>) -> String {
    if let Some(paygate_url) = paygate_url {
        let paygate_url = paygate_url.trim();
        if !paygate_url.is_empty() {
            return paygate_url.trim_end_matches('/').to_owned();
        }
    }
    if let Ok(paygate_url) = env::var("MAYHEM_PAYGATE_URL") {
        let paygate_url = paygate_url.trim();
        if !paygate_url.is_empty() {
            return paygate_url.trim_end_matches('/').to_owned();
        }
    }
    config
        .and_then(|config| config.network.as_ref())
        .and_then(|network| network.paygate_url.as_deref())
        .filter(|value| !value.trim().is_empty())
        .map(|value| value.trim_end_matches('/').to_owned())
        .unwrap_or_else(|| DEFAULT_PAYGATE_URL.to_owned())
}

fn resolve_cli_tnk_treasury_address(
    config: Option<&MayhemConfig>,
    treasury_address: Option<&str>,
) -> Result<String> {
    let value = treasury_address
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_owned)
        .or_else(|| {
            env::var("MAYHEM_TNK_TREASURY_ADDRESS")
                .ok()
                .map(|value| value.trim().to_owned())
                .filter(|value| !value.is_empty())
        })
        .or_else(|| {
            config
                .and_then(|config| config.network.as_ref())
                .and_then(|network| network.tnk_treasury_address.as_deref())
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_owned)
        })
        .context(
            "TNK treasury address required; pass --treasury-address, set MAYHEM_TNK_TREASURY_ADDRESS, or set network.tnk_treasury_address",
        )?;
    if value.split_whitespace().count() != 1 {
        bail!("TNK treasury address must not contain whitespace");
    }
    Ok(value)
}

fn resolve_tnk_msb_network(
    override_network: Option<&str>,
    treasury_address: &str,
) -> Result<String> {
    if let Some(network) = override_network
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        return match network.to_ascii_lowercase().as_str() {
            "mainnet" => Ok("mainnet".to_owned()),
            "testnet" | "testnet1" => Ok("testnet1".to_owned()),
            _ => bail!("--msb-network must be mainnet or testnet1"),
        };
    }

    if treasury_address.starts_with("testtrac1") {
        Ok("testnet1".to_owned())
    } else if treasury_address.starts_with("trac1") {
        Ok("mainnet".to_owned())
    } else {
        bail!(
            "could not infer MSB network from treasury address; pass --msb-network mainnet|testnet1"
        )
    }
}

fn msb_network_address_prefix(network: &str) -> Result<&'static str> {
    match network.to_ascii_lowercase().as_str() {
        "mainnet" => Ok("trac"),
        "testnet" | "testnet1" => Ok("testtrac"),
        _ => bail!("MSB network must be mainnet or testnet1"),
    }
}

fn msb_store_from_keypair_path(keypair_path: &Path) -> Result<(PathBuf, String)> {
    let keypair_file = keypair_path
        .file_name()
        .and_then(|value| value.to_str())
        .context("wallet keypair path has no filename")?;
    if keypair_file != "keypair.json" {
        bail!("wallet keypair path must end in db/keypair.json for MSB transfer submission");
    }
    let db_dir = keypair_path
        .parent()
        .context("wallet keypair path has no db directory")?;
    let db_name = db_dir
        .file_name()
        .and_then(|value| value.to_str())
        .context("wallet keypair db directory has no name")?;
    if db_name != "db" {
        bail!("wallet keypair path must end in db/keypair.json for MSB transfer submission");
    }
    let store_dir = db_dir
        .parent()
        .context("wallet keypair path has no store directory")?;
    let store_name = store_dir
        .file_name()
        .and_then(|value| value.to_str())
        .filter(|value| !value.is_empty())
        .context("wallet store directory has no name")?
        .to_owned();
    let stores_directory = store_dir
        .parent()
        .context("wallet store directory has no parent")?
        .to_path_buf();
    Ok((stores_directory, store_name))
}

async fn resolve_cli_wallet(
    home: &Path,
    config: Option<&MayhemConfig>,
    peer_store_name: &str,
    password: &str,
) -> Result<WalletInfo> {
    resolve_cli_wallet_with_keypair(home, config, None, peer_store_name, password).await
}

async fn resolve_cli_wallet_with_keypair(
    home: &Path,
    config: Option<&MayhemConfig>,
    keypair: Option<&Path>,
    peer_store_name: &str,
    password: &str,
) -> Result<WalletInfo> {
    let store_name = config
        .and_then(|config| config.identity.as_ref())
        .and_then(|identity| identity.store_name.as_deref())
        .unwrap_or(peer_store_name);
    let keypair_path = match keypair {
        Some(path) => absolutize(path.to_path_buf())?,
        None => config
            .and_then(|config| config.identity.as_ref())
            .and_then(|identity| identity.keypair_path.as_deref())
            .map(PathBuf::from)
            .unwrap_or_else(|| {
                home.join("stores")
                    .join(store_name)
                    .join("db")
                    .join("keypair.json")
            }),
    };
    inspect_wallet(&keypair_path, password)
        .await
        .with_context(|| format!("reading wallet {}", keypair_path.display()))
}

fn pay_tnk_deposit_intent_payload(
    memo_hash: &str,
    treasury_address: &str,
    tnk_e18: u128,
    quoted_au: MoneyAu,
    rate: &PayTnkRate,
) -> Value {
    json!({
        "op": "deposit_tnk",
        "memo_hash": memo_hash,
        "treasury_address": treasury_address,
        "tnk_e18": tnk_e18.to_string(),
        "quoted_au": money_au_json(quoted_au),
        "rate_tnk_usd_au": money_au_json(rate.tnk_usd_au),
        "rate_source": rate.source,
    })
}

fn deposit_tnk_intent_message(intent: &Value) -> String {
    format!("mayhem-deposit-tnk-intent-v1{}", stable_json_value(intent))
}

async fn resolve_tnk_rate(
    rpc: Option<&PeerRpcClient>,
    override_rate: Option<MoneyAu>,
) -> Result<PayTnkRate> {
    if let Some(tnk_usd_au) = override_rate {
        if tnk_usd_au == 0 {
            bail!("--tnk-usd-au must be positive");
        }
        return Ok(PayTnkRate {
            tnk_usd_au,
            source: "cli-override".to_owned(),
            ts: None,
        });
    }

    let rpc = rpc.context(
        "contract rate/latest requires peer RPC; pass --tnk-usd-au for offline preparation",
    )?;
    let value = read_state_value(rpc, "rate/latest").await?.context(
        "contract rate/latest not found; run mayhem admin rate-oracle or pass --tnk-usd-au",
    )?;
    parse_tnk_rate(&value)
}

fn parse_tnk_rate(value: &Value) -> Result<PayTnkRate> {
    let tnk_usd_au = value
        .get("tnk_usd_au")
        .and_then(value_money_au)
        .filter(|rate| *rate > 0)
        .context("rate/latest missing positive tnk_usd_au")?;
    Ok(PayTnkRate {
        tnk_usd_au,
        source: value
            .get("source")
            .and_then(Value::as_str)
            .unwrap_or("rate/latest")
            .to_owned(),
        ts: value.get("ts").and_then(Value::as_u64),
    })
}

fn now_unix_seconds() -> Result<u64> {
    Ok(SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .context("system clock is before Unix epoch")?
        .as_secs())
}

fn resolve_tnk_operator_address(operator_tnk_address: Option<&str>) -> Result<String> {
    let value = operator_tnk_address
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_owned)
        .or_else(|| {
            env::var("MAYHEM_TNK_OPERATOR_ADDRESS")
                .ok()
                .map(|value| value.trim().to_owned())
                .filter(|value| !value.is_empty())
        })
        .context(
            "operator TNK address required; pass --operator-tnk-address or set MAYHEM_TNK_OPERATOR_ADDRESS",
        )?;
    if value.split_whitespace().count() != 1 {
        bail!("operator TNK address must not contain whitespace");
    }
    Ok(value)
}

fn validate_msb_tx_hash(value: &str) -> Result<String> {
    let value = value.trim().to_ascii_lowercase();
    if !is_hex_len(&value, 64) {
        bail!("MSB transaction hash must be 64 hex characters");
    }
    Ok(value)
}

async fn build_tnk_settlement_plan(
    rpc: &PeerRpcClient,
    epoch: u64,
    at: u64,
    network: &str,
    treasury_address: &str,
    operator_tnk_address: &str,
    msb_tx_hashes: Option<&[String]>,
) -> Result<TnkSettlementPlan> {
    for (label, value) in [
        ("MSB network", network),
        ("treasury address", treasury_address),
        ("operator TNK address", operator_tnk_address),
    ] {
        if !is_safe_key_part(value) {
            bail!("{label} is not contract-safe");
        }
    }
    if let Some(existing) = read_state_value(rpc, &format!("settle/tnk/{epoch}")).await? {
        return Ok(TnkSettlementPlan {
            payload: existing.clone(),
            msb_outputs: Vec::new(),
            skipped_providers: Vec::new(),
            already_settled: Some(existing),
        });
    }

    let apply_state = read_state_value(rpc, "epoch/apply/state")
        .await?
        .context("epoch/apply/state not found; apply the epoch before TNK settlement")?;
    let applied_epoch = apply_state
        .get("updated_epoch")
        .and_then(Value::as_u64)
        .context("epoch/apply/state missing updated_epoch")?;
    if applied_epoch != epoch {
        bail!(
            "epoch/apply/state is at epoch {applied_epoch}, not requested settlement epoch {epoch}"
        );
    }
    let epoch_apply_hash = apply_state
        .get("last_apply_hash")
        .and_then(Value::as_str)
        .filter(|hash| is_hex_len(hash, 64))
        .context("epoch/apply/state missing 32-byte last_apply_hash")?
        .to_ascii_lowercase();

    let rate_value = read_state_value(rpc, "rate/latest")
        .await?
        .context("rate/latest not found; run the TNK rate watcher before settlement")?;
    let rate = parse_tnk_rate(&rate_value)?;
    if !matches!(rate.source.as_str(), "gate-spot" | "mexc-spot") {
        bail!(
            "rate/latest source {} is not supported for TNK settlement",
            rate.source
        );
    }
    let rate_ts = rate.ts.context(
        "rate/latest missing timestamp; settlement requires a contract oracle timestamp",
    )?;

    let params = read_tnk_settlement_params(rpc, at).await?;
    if rate_ts > at {
        bail!("rate/latest timestamp {rate_ts} is in the future relative to settlement timestamp {at}");
    }
    if at.saturating_sub(rate_ts) > params.rate_staleness_seconds {
        bail!(
            "rate/latest is stale: age {}s exceeds {}s",
            at.saturating_sub(rate_ts),
            params.rate_staleness_seconds
        );
    }

    let admin = read_state_value(rpc, "admin")
        .await?
        .and_then(|value| value.as_str().map(str::to_owned))
        .context("admin key missing; provider payout targets cannot be verified")?;
    let providers = read_prefix_entries(rpc, "prov/")
        .await?
        .into_iter()
        .filter_map(|entry| {
            let provider = entry
                .value
                .get("provider")
                .and_then(Value::as_str)?
                .to_owned();
            Some((provider, entry.value))
        })
        .collect::<BTreeMap<_, _>>();

    let mut skipped_providers = Vec::new();
    let mut outputs = Vec::new();
    let mut earnings = read_prefix_values::<LedgerEarningRecord>(rpc, "earn/tnk/").await?;
    earnings.sort_by(|left, right| left.provider.cmp(&right.provider));
    for earning in earnings {
        if earning.rail != "tnk" {
            continue;
        }
        let Some(provider) = providers.get(&earning.provider) else {
            skipped_providers.push(json!({
                "provider": earning.provider,
                "au": money_au_json(0),
                "reason": "provider record missing",
            }));
            continue;
        };
        let payable_au = tnk_payable_earning_au(rpc, &earning, provider, epoch, &params).await?;
        if payable_au == 0 {
            continue;
        }
        match tnk_provider_payout_target(provider, &earning.provider, &admin) {
            Ok(to) => outputs.push(json!({
                "role": "provider",
                "provider": earning.provider,
                "to": to,
                "au": money_au_json(payable_au),
                "tnk_e18": au_to_tnk_e18_ceil_u128(payable_au, rate.tnk_usd_au)?.to_string(),
            })),
            Err(error) => skipped_providers.push(json!({
                "provider": earning.provider,
                "au": money_au_json(payable_au),
                "reason": error.to_string(),
            })),
        }
    }

    let fee = read_tnk_fee_record(rpc).await?;
    let operator_fee_au = fee
        .cum_au
        .checked_sub(fee.swept_cum_au)
        .context("fee/tnk/cum swept amount exceeds cumulative fee")?;
    if operator_fee_au > 0 {
        outputs.push(json!({
            "role": "operator_fee",
            "to": operator_tnk_address,
            "au": money_au_json(operator_fee_au),
            "tnk_e18": au_to_tnk_e18_ceil_u128(operator_fee_au, rate.tnk_usd_au)?.to_string(),
        }));
    }
    if outputs.is_empty() {
        bail!(
            "TNK settlement has no positive provider or operator fee outputs; nothing to broadcast"
        );
    }

    let totals = tnk_settlement_output_totals(&outputs)?;
    let provided_msb_tx_hashes = msb_tx_hashes
        .map(|hashes| hashes.to_vec())
        .unwrap_or_default();
    if !provided_msb_tx_hashes.is_empty() && provided_msb_tx_hashes.len() != outputs.len() {
        bail!(
            "TNK settlement requires one --msb-tx-hash per output: got {}, expected {}",
            provided_msb_tx_hashes.len(),
            outputs.len()
        );
    }
    let transfer_root = stable_value_hash(&json!({
        "domain": "mayhem-tnk-settlement-transfer-root-v1",
        "value": outputs,
    }));
    let payload = json!({
        "op": "tnk_settlement",
        "epoch": epoch,
        "at": at,
        "rail": "tnk",
        "network": network,
        "treasury_from": treasury_address,
        "operator_to": operator_tnk_address,
        "epoch_apply_hash": epoch_apply_hash,
        "rate_tnk_usd_au": money_au_json(rate.tnk_usd_au),
        "rate_source": rate.source,
        "rate_ts": rate_ts,
        "msb_tx_hashes": provided_msb_tx_hashes,
        "transfer_root": transfer_root,
        "provider_count": totals.provider_count,
        "provider_au": money_au_json(totals.provider_au),
        "operator_fee_au": money_au_json(totals.operator_fee_au),
        "gross_au": money_au_json(totals.gross_au),
        "tnk_e18": totals.tnk_e18,
        "outputs": outputs,
    });
    let msb_outputs = payload["outputs"]
        .as_array()
        .expect("outputs constructed as array")
        .iter()
        .map(|output| {
            let tnk_e18 = output
                .get("tnk_e18")
                .and_then(Value::as_str)
                .context("settlement output missing tnk_e18")?
                .parse::<u128>()
                .context("parsing settlement tnk_e18")?;
            Ok(MsbSettlementTransferOutput {
                to: output
                    .get("to")
                    .and_then(Value::as_str)
                    .context("settlement output missing recipient")?
                    .to_owned(),
                amount: tnk_e18_to_decimal(tnk_e18),
            })
        })
        .collect::<Result<Vec<_>>>()?;

    Ok(TnkSettlementPlan {
        payload,
        msb_outputs,
        skipped_providers,
        already_settled: None,
    })
}

#[derive(Debug)]
struct TnkSettlementTotals {
    provider_count: u64,
    provider_au: MoneyAu,
    operator_fee_au: MoneyAu,
    gross_au: MoneyAu,
    tnk_e18: String,
}

fn tnk_settlement_output_totals(outputs: &[Value]) -> Result<TnkSettlementTotals> {
    let mut provider_count = 0_u64;
    let mut provider_au = 0_u128;
    let mut operator_fee_au = 0_u128;
    let mut tnk_e18 = 0_u128;
    for output in outputs {
        let role = output
            .get("role")
            .and_then(Value::as_str)
            .context("TNK settlement output missing role")?;
        let au = output
            .get("au")
            .and_then(value_money_au)
            .context("TNK settlement output missing au")?;
        let amount = output
            .get("tnk_e18")
            .and_then(Value::as_str)
            .context("TNK settlement output missing tnk_e18")?
            .parse::<u128>()
            .context("parsing TNK settlement tnk_e18")?;
        tnk_e18 = tnk_e18
            .checked_add(amount)
            .context("TNK settlement amount overflow")?;
        match role {
            "provider" => {
                provider_count = provider_count
                    .checked_add(1)
                    .context("TNK settlement provider count overflow")?;
                provider_au = provider_au
                    .checked_add(au)
                    .context("TNK settlement provider amount overflow")?;
            }
            "operator_fee" => {
                operator_fee_au = operator_fee_au
                    .checked_add(au)
                    .context("TNK settlement operator amount overflow")?;
            }
            _ => bail!("invalid TNK settlement output role {role}"),
        }
    }
    let gross_au = provider_au
        .checked_add(operator_fee_au)
        .context("TNK settlement gross amount overflow")?;
    Ok(TnkSettlementTotals {
        provider_count,
        provider_au,
        operator_fee_au,
        gross_au,
        tnk_e18: tnk_e18.to_string(),
    })
}

async fn read_tnk_settlement_params(rpc: &PeerRpcClient, at: u64) -> Result<TnkSettlementParams> {
    Ok(TnkSettlementParams {
        holdback_epochs: read_param_u64_at(rpc, "holdback_epochs", DEFAULT_HOLDBACK_EPOCHS, at)
            .await?,
        new_provider_holdback_epochs: read_param_u64_at(
            rpc,
            "new_provider_holdback_epochs",
            DEFAULT_NEW_PROVIDER_HOLDBACK_EPOCHS,
            at,
        )
        .await?,
        challenge_epochs: read_param_u64_at(rpc, "challenge_epochs", DEFAULT_CHALLENGE_EPOCHS, at)
            .await?,
        probation_successful_sessions: read_param_u64_at(
            rpc,
            "probation_successful_sessions",
            DEFAULT_PROBATION_SUCCESSFUL_SESSIONS,
            at,
        )
        .await?,
        canary_probe_holdback_bps: read_param_u64_at(
            rpc,
            "canary_probe_holdback_bps",
            DEFAULT_CANARY_PROBE_HOLDBACK_BPS,
            at,
        )
        .await?,
        canary_probe_release_min_passes: read_param_u64_at(
            rpc,
            "canary_probe_release_min_passes",
            DEFAULT_CANARY_PROBE_RELEASE_MIN_PASSES,
            at,
        )
        .await?,
        rate_staleness_seconds: read_param_u64_at(
            rpc,
            "rate_staleness_seconds",
            DEFAULT_RATE_STALENESS_SECONDS,
            at,
        )
        .await?,
    })
}

async fn read_param_u64_at(rpc: &PeerRpcClient, key: &str, default: u64, at: u64) -> Result<u64> {
    let Some(record) = read_state_value(rpc, &format!("params/{key}")).await? else {
        return Ok(default);
    };
    let active = match record.get("pending") {
        Some(pending)
            if !pending.is_null()
                && pending
                    .get("effective_at")
                    .and_then(Value::as_u64)
                    .is_some_and(|effective_at| effective_at <= at) =>
        {
            pending
        }
        _ => record
            .get("current")
            .context("parameter record missing current entry")?,
    };
    active
        .get("value")
        .and_then(Value::as_u64)
        .with_context(|| format!("params/{key} active value is not a u64"))
}

async fn read_tnk_fee_record(rpc: &PeerRpcClient) -> Result<LedgerFeeRecord> {
    match read_state_value(rpc, "fee/tnk/cum").await? {
        Some(value) => serde_json::from_value(value).context("parsing fee/tnk/cum contract state"),
        None => Ok(LedgerFeeRecord {
            rail: "tnk".to_owned(),
            denom: "au_usd".to_owned(),
            cum_au: 0,
            swept_cum_au: 0,
            updated_epoch: 0,
            updated_at: None,
            last_apply_hash: None,
            last_fee_bps: None,
            last_settlement_epoch: None,
            last_settlement_msb_tx_hash: None,
        }),
    }
}

async fn tnk_payable_earning_au(
    rpc: &PeerRpcClient,
    earning: &LedgerEarningRecord,
    provider: &Value,
    epoch: u64,
    params: &TnkSettlementParams,
) -> Result<MoneyAu> {
    let locked_epochs = provider_tnk_locked_epochs(provider, params)?;
    let kept = refresh_tnk_holdbacks(rpc, earning, epoch, locked_epochs, params).await?;
    let held_au = kept
        .iter()
        .try_fold(0_u128, |sum, bucket| sum.checked_add(bucket.au))
        .context("TNK held amount overflow")?;
    let released_au = earning
        .total_au
        .checked_sub(held_au)
        .context("TNK held amount exceeds total earnings")?;
    released_au
        .checked_sub(earning.paid_cum_au)
        .context("TNK paid amount exceeds released earnings")
}

fn provider_tnk_locked_epochs(provider: &Value, params: &TnkSettlementParams) -> Result<u64> {
    let successful_sessions = provider
        .get("probation")
        .and_then(|probation| probation.get("successful_sessions"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let provider_holdback = if successful_sessions < params.probation_successful_sessions {
        params
            .holdback_epochs
            .max(params.new_provider_holdback_epochs)
    } else {
        params.holdback_epochs
    };
    Ok(provider_holdback.max(params.challenge_epochs))
}

async fn refresh_tnk_holdbacks(
    rpc: &PeerRpcClient,
    earning: &LedgerEarningRecord,
    current_epoch: u64,
    locked_epochs: u64,
    params: &TnkSettlementParams,
) -> Result<Vec<LedgerHoldbackBucket>> {
    let holdbacks = normalize_tnk_holdbacks(earning)?;
    let probe_gate_enabled =
        params.canary_probe_holdback_bps > 0 && params.canary_probe_release_min_passes > 0;
    let mut kept = Vec::new();
    for bucket in holdbacks {
        let bucket_locked_epochs = bucket.locked_epochs.unwrap_or(locked_epochs);
        if bucket.epoch.saturating_add(bucket_locked_epochs) > current_epoch {
            kept.push(bucket);
            continue;
        }
        if !probe_gate_enabled {
            continue;
        }
        if tnk_probe_passed(
            rpc,
            &earning.provider,
            bucket.epoch,
            params.canary_probe_release_min_passes,
        )
        .await?
        {
            continue;
        }
        if bucket.probe_gate {
            kept.push(bucket);
            continue;
        }
        let gated_au = bucket.au * u128::from(params.canary_probe_holdback_bps) / 10_000;
        if gated_au > 0 {
            kept.push(LedgerHoldbackBucket {
                epoch: bucket.epoch,
                au: gated_au,
                probe_gate: true,
                locked_epochs: bucket.locked_epochs,
            });
        }
    }
    Ok(kept)
}

async fn tnk_probe_passed(
    rpc: &PeerRpcClient,
    provider: &str,
    epoch: u64,
    required_passes: u64,
) -> Result<bool> {
    let Some(record) = read_state_value(rpc, &format!("probe/pass/{provider}/{epoch}")).await?
    else {
        return Ok(false);
    };
    Ok(record
        .get("pass_count")
        .and_then(Value::as_u64)
        .unwrap_or(0)
        >= required_passes)
}

fn normalize_tnk_holdbacks(earning: &LedgerEarningRecord) -> Result<Vec<LedgerHoldbackBucket>> {
    if earning.holdbacks.is_empty() {
        if earning.held_au == 0 {
            return Ok(Vec::new());
        }
        return Ok(vec![LedgerHoldbackBucket {
            epoch: earning.updated_epoch,
            au: earning.held_au,
            probe_gate: false,
            locked_epochs: None,
        }]);
    }
    let mut by_bucket = BTreeMap::<(u64, bool, Option<u64>), MoneyAu>::new();
    for bucket in &earning.holdbacks {
        if bucket.au == 0 {
            bail!("TNK holdback bucket amount must be positive");
        }
        let key = (bucket.epoch, bucket.probe_gate, bucket.locked_epochs);
        let next = by_bucket
            .get(&key)
            .copied()
            .unwrap_or(0)
            .checked_add(bucket.au)
            .context("TNK holdback bucket overflow")?;
        by_bucket.insert(key, next);
    }
    Ok(by_bucket
        .into_iter()
        .map(
            |((epoch, probe_gate, locked_epochs), au)| LedgerHoldbackBucket {
                epoch,
                au,
                probe_gate,
                locked_epochs,
            },
        )
        .collect())
}

fn tnk_provider_payout_target(provider: &Value, provider_id: &str, admin: &str) -> Result<String> {
    if !matches!(
        provider.get("status").and_then(Value::as_str),
        Some("active" | "banned")
    ) {
        bail!("provider status is not payable");
    }
    let payout = provider
        .get("payout")
        .and_then(Value::as_object)
        .context("provider payout target is not set")?;
    if payout.get("method").and_then(Value::as_str) != Some("tnk") {
        bail!("provider payout target is not TNK");
    }
    if payout.get("set_by").and_then(Value::as_str) != Some(admin) {
        bail!("provider payout target was not set by the current admin");
    }
    if payout.get("set_by_role").and_then(Value::as_str) != Some("admin") {
        bail!("provider payout target must be admin-set");
    }
    let addr = payout
        .get("addr")
        .and_then(Value::as_str)
        .context("provider payout target missing address")?;
    if !is_safe_key_part(addr) {
        bail!("provider payout target address is not contract-safe");
    }
    if provider
        .get("provider")
        .and_then(Value::as_str)
        .is_some_and(|actual| actual != provider_id)
    {
        bail!("provider payout record owner mismatch");
    }
    Ok(addr.to_owned())
}

const FIAT_MINOR_AU_CLI: MoneyAu = 10_000_000_000_000_000;

async fn build_fiat_settlement_plan(
    rpc: &PeerRpcClient,
    epoch: u64,
    at: u64,
    operator_to: &str,
    operator_currency: &str,
    operator_ref: Option<&str>,
    stripe_refs: Option<&[String]>,
) -> Result<FiatSettlementPlan> {
    if !is_safe_key_part(operator_to) {
        bail!("operator Stripe account is not contract-safe");
    }
    let operator_currency = normalize_admin_fiat_currency(operator_currency)?;
    if let Some(existing) = read_state_value(rpc, &format!("settle/fiat/{epoch}")).await? {
        return Ok(FiatSettlementPlan {
            payload: existing.clone(),
            stripe_outputs: Vec::new(),
            skipped_providers: Vec::new(),
            already_settled: Some(existing),
            epoch_apply_hash: String::new(),
        });
    }

    let apply_state = read_state_value(rpc, "epoch/apply/state")
        .await?
        .context("epoch/apply/state not found; apply the epoch before fiat settlement")?;
    let applied_epoch = apply_state
        .get("updated_epoch")
        .and_then(Value::as_u64)
        .context("epoch/apply/state missing updated_epoch")?;
    if applied_epoch != epoch {
        bail!(
            "epoch/apply/state is at epoch {applied_epoch}, not requested settlement epoch {epoch}"
        );
    }
    let epoch_apply_hash = apply_state
        .get("last_apply_hash")
        .and_then(Value::as_str)
        .filter(|hash| is_hex_len(hash, 64))
        .context("epoch/apply/state missing 32-byte last_apply_hash")?
        .to_ascii_lowercase();

    let params = read_tnk_settlement_params(rpc, at).await?;
    let admin = read_state_value(rpc, "admin")
        .await?
        .and_then(|value| value.as_str().map(str::to_owned))
        .context("admin key missing; provider payout targets cannot be verified")?;
    let providers = read_prefix_entries(rpc, "prov/")
        .await?
        .into_iter()
        .filter_map(|entry| {
            let provider = entry
                .value
                .get("provider")
                .and_then(Value::as_str)?
                .to_owned();
            Some((provider, entry.value))
        })
        .collect::<BTreeMap<_, _>>();

    let mut skipped_providers = Vec::new();
    let mut outputs = Vec::new();
    let mut earnings = read_prefix_values::<LedgerEarningRecord>(rpc, "earn/fiat/").await?;
    earnings.sort_by(|left, right| left.provider.cmp(&right.provider));
    for earning in earnings {
        if earning.rail != "fiat" {
            continue;
        }
        let Some(provider) = providers.get(&earning.provider) else {
            skipped_providers.push(json!({
                "provider": earning.provider,
                "au": money_au_json(0),
                "reason": "provider record missing",
            }));
            continue;
        };
        let payable_au = tnk_payable_earning_au(rpc, &earning, provider, epoch, &params).await?;
        let transferable_au = fiat_whole_minor_au(payable_au);
        if transferable_au == 0 {
            if payable_au > 0 {
                skipped_providers.push(json!({
                    "provider": earning.provider,
                    "au": money_au_json(payable_au),
                    "reason": "payable amount is below one Stripe minor unit",
                }));
            }
            continue;
        }
        match fiat_provider_payout_target(provider, &earning.provider, &admin) {
            Ok((to, currency)) => outputs.push(FiatSettlementOutput {
                role: "provider".to_owned(),
                provider: Some(earning.provider),
                to,
                currency,
                amount_minor: fiat_au_to_minor(transferable_au)?,
                au: transferable_au,
            }),
            Err(error) => skipped_providers.push(json!({
                "provider": earning.provider,
                "au": money_au_json(transferable_au),
                "reason": error.to_string(),
            })),
        }
    }

    let fee = read_fee_record(rpc, "fiat").await?;
    let payable_fee_au = fee
        .cum_au
        .checked_sub(fee.swept_cum_au)
        .context("fee/fiat/cum swept amount exceeds cumulative fee")?;
    let operator_fee_au = fiat_whole_minor_au(payable_fee_au);
    if operator_fee_au > 0 {
        outputs.push(FiatSettlementOutput {
            role: "operator_fee".to_owned(),
            provider: None,
            to: operator_to.to_owned(),
            currency: operator_currency,
            amount_minor: fiat_au_to_minor(operator_fee_au)?,
            au: operator_fee_au,
        });
    }
    if outputs.is_empty() {
        bail!(
            "fiat settlement has no whole-cent provider or operator fee outputs; nothing to record"
        );
    }

    let provided_refs = stripe_refs.map(|refs| refs.to_vec()).unwrap_or_default();
    if !provided_refs.is_empty() && provided_refs.len() != outputs.len() {
        bail!(
            "fiat settlement requires one --stripe-ref per output: got {}, expected {}",
            provided_refs.len(),
            outputs.len()
        );
    }
    if provided_refs.is_empty()
        && operator_ref.is_some()
        && !outputs.iter().any(|output| output.role == "operator_fee")
    {
        bail!("--operator-stripe-ref was provided but the settlement has no operator fee output");
    }
    let refs = if provided_refs.is_empty() {
        Vec::new()
    } else {
        validate_fiat_settlement_refs(&outputs, provided_refs)?
    };
    let output_values = fiat_settlement_output_values(&outputs);
    let transfer_root = stable_value_hash(&json!({
        "domain": "mayhem-fiat-settlement-transfer-root-v1",
        "value": output_values,
    }));
    let totals = fiat_settlement_output_totals(&outputs)?;
    let payload = json!({
        "op": "fiat_settlement",
        "epoch": epoch,
        "at": at,
        "rail": "fiat",
        "processor": "stripe",
        "operator_to": operator_to,
        "epoch_apply_hash": epoch_apply_hash,
        "stripe_refs": refs,
        "transfer_root": transfer_root,
        "provider_count": totals.provider_count,
        "provider_au": money_au_json(totals.provider_au),
        "operator_fee_au": money_au_json(totals.operator_fee_au),
        "gross_au": money_au_json(totals.gross_au),
        "outputs": output_values,
    });

    Ok(FiatSettlementPlan {
        payload,
        stripe_outputs: outputs,
        skipped_providers,
        already_settled: None,
        epoch_apply_hash,
    })
}

fn fiat_settlement_output_values(outputs: &[FiatSettlementOutput]) -> Vec<Value> {
    outputs
        .iter()
        .map(|output| {
            let mut value = json!({
                "role": output.role,
                "to": output.to,
                "currency": output.currency,
                "amount_minor": output.amount_minor.to_string(),
                "au": money_au_json(output.au),
            });
            if let Some(provider) = output.provider.as_ref() {
                value["provider"] = json!(provider);
            }
            value
        })
        .collect()
}

#[derive(Debug)]
struct FiatSettlementTotals {
    provider_count: u64,
    provider_au: MoneyAu,
    operator_fee_au: MoneyAu,
    gross_au: MoneyAu,
}

fn fiat_settlement_output_totals(outputs: &[FiatSettlementOutput]) -> Result<FiatSettlementTotals> {
    let mut provider_count = 0_u64;
    let mut provider_au = 0_u128;
    let mut operator_fee_au = 0_u128;
    for output in outputs {
        match output.role.as_str() {
            "provider" => {
                provider_count = provider_count
                    .checked_add(1)
                    .context("fiat settlement provider count overflow")?;
                provider_au = provider_au
                    .checked_add(output.au)
                    .context("fiat settlement provider amount overflow")?;
            }
            "operator_fee" => {
                operator_fee_au = operator_fee_au
                    .checked_add(output.au)
                    .context("fiat settlement operator amount overflow")?;
            }
            other => bail!("invalid fiat settlement output role {other}"),
        }
    }
    let gross_au = provider_au
        .checked_add(operator_fee_au)
        .context("fiat settlement gross amount overflow")?;
    Ok(FiatSettlementTotals {
        provider_count,
        provider_au,
        operator_fee_au,
        gross_au,
    })
}

async fn read_fee_record(rpc: &PeerRpcClient, rail: &str) -> Result<LedgerFeeRecord> {
    match read_state_value(rpc, &format!("fee/{rail}/cum")).await? {
        Some(value) => serde_json::from_value(value)
            .with_context(|| format!("parsing fee/{rail}/cum contract state")),
        None => Ok(LedgerFeeRecord {
            rail: rail.to_owned(),
            denom: "au_usd".to_owned(),
            cum_au: 0,
            swept_cum_au: 0,
            updated_epoch: 0,
            updated_at: None,
            last_apply_hash: None,
            last_fee_bps: None,
            last_settlement_epoch: None,
            last_settlement_msb_tx_hash: None,
        }),
    }
}

fn fiat_whole_minor_au(au: MoneyAu) -> MoneyAu {
    (au / FIAT_MINOR_AU_CLI) * FIAT_MINOR_AU_CLI
}

fn fiat_au_to_minor(au: MoneyAu) -> Result<u64> {
    if au == 0 || au % FIAT_MINOR_AU_CLI != 0 {
        bail!("fiat settlement amount must be a positive whole Stripe minor unit");
    }
    u64::try_from(au / FIAT_MINOR_AU_CLI)
        .context("fiat settlement amount exceeds Stripe u64 minor units")
}

fn fiat_provider_payout_target(
    provider: &Value,
    provider_id: &str,
    admin: &str,
) -> Result<(String, String)> {
    if !matches!(
        provider.get("status").and_then(Value::as_str),
        Some("active" | "banned")
    ) {
        bail!("provider status is not payable");
    }
    let payout = provider
        .get("payout")
        .and_then(Value::as_object)
        .context("provider payout target is not set")?;
    if payout.get("method").and_then(Value::as_str) != Some("stripe") {
        bail!("provider payout target is not Stripe");
    }
    if payout.get("set_by").and_then(Value::as_str) != Some(admin) {
        bail!("provider payout target was not set by the current admin");
    }
    if payout.get("set_by_role").and_then(Value::as_str) != Some("admin") {
        bail!("provider payout target must be admin-set");
    }
    let addr = payout
        .get("addr")
        .and_then(Value::as_str)
        .context("provider payout target missing address")?;
    if !is_safe_key_part(addr) {
        bail!("provider payout target address is not contract-safe");
    }
    let currency = payout
        .get("currency")
        .and_then(Value::as_str)
        .context("provider payout target missing fiat currency")
        .and_then(normalize_admin_fiat_currency)?;
    if provider
        .get("provider")
        .and_then(Value::as_str)
        .is_some_and(|actual| actual != provider_id)
    {
        bail!("provider payout record owner mismatch");
    }
    Ok((addr.to_owned(), currency))
}

fn normalize_fiat_settlement_ref(value: &str, label: &str) -> Result<String> {
    let value = value.trim();
    if !is_safe_key_part(value) {
        bail!("{label} is not contract-safe");
    }
    Ok(value.to_owned())
}

fn operator_fiat_settlement_ref(
    override_ref: Option<&str>,
    epoch: u64,
    epoch_apply_hash: &str,
) -> Result<String> {
    if let Some(value) = override_ref {
        return normalize_fiat_settlement_ref(value, "operator Stripe reference");
    }
    Ok(format!(
        "platform_balance:{epoch}:{}",
        epoch_apply_hash.get(..16).unwrap_or(epoch_apply_hash)
    ))
}

fn validate_fiat_settlement_refs(
    outputs: &[FiatSettlementOutput],
    refs: Vec<String>,
) -> Result<Vec<String>> {
    if refs.len() != outputs.len() {
        bail!("fiat settlement Stripe reference count must match outputs");
    }
    let mut seen = BTreeSet::new();
    let mut normalized = Vec::with_capacity(refs.len());
    for (output, reference) in outputs.iter().zip(refs.iter()) {
        let reference = normalize_fiat_settlement_ref(reference, "Stripe reference")?;
        if !seen.insert(reference.clone()) {
            bail!("duplicate fiat settlement Stripe reference");
        }
        if output.role == "provider" && !reference.starts_with("tr_") {
            bail!("provider Stripe references must be transfer ids starting with tr_");
        }
        normalized.push(reference);
    }
    Ok(normalized)
}

fn stripe_api_base_url(override_url: Option<&str>) -> Result<String> {
    let value = override_url
        .map(str::to_owned)
        .or_else(|| env::var("MAYHEM_STRIPE_API_BASE_URL").ok())
        .unwrap_or_else(|| "https://api.stripe.com".to_owned());
    let trimmed = value.trim().trim_end_matches('/').to_owned();
    if trimmed.is_empty() || !trimmed.starts_with("https://") {
        bail!("Stripe API base URL must be https");
    }
    Ok(trimmed)
}

fn load_stripe_secret_key(path: Option<&PathBuf>, home: &Path) -> Result<String> {
    if let Ok(value) =
        env::var("STRIPE_SECRET_KEY").or_else(|_| env::var("MAYHEM_STRIPE_SECRET_KEY"))
    {
        let value = value.trim();
        if !value.is_empty() {
            return Ok(value.to_owned());
        }
    }
    let candidates = if let Some(path) = path {
        vec![path.clone()]
    } else {
        vec![
            PathBuf::from(".mayhem-local/secrets/stripe.txt"),
            home.join("secrets/stripe.txt"),
        ]
    };
    for candidate in candidates {
        if !candidate.is_file() {
            continue;
        }
        let text = fs::read_to_string(&candidate)
            .with_context(|| format!("reading Stripe secret file {}", candidate.display()))?;
        if let Some(secret) = stripe_secret_key_from_text(&text) {
            return Ok(secret);
        }
    }
    bail!("missing STRIPE_SECRET_KEY; set env, MAYHEM_STRIPE_SECRET_KEY, or pass --stripe-env-file")
}

fn stripe_secret_key_from_text(text: &str) -> Option<String> {
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, value) = line.split_once('=')?;
        if matches!(key.trim(), "STRIPE_SECRET_KEY" | "MAYHEM_STRIPE_SECRET_KEY") {
            let value = value.trim().trim_matches('"').trim_matches('\'').trim();
            if !value.is_empty() {
                return Some(value.to_owned());
            }
        }
    }
    None
}

async fn stripe_create_transfer(
    client: &reqwest::Client,
    api_base_url: &str,
    secret_key: &str,
    output: &FiatSettlementOutput,
    idempotency_key: &str,
) -> Result<StripeTransferResult> {
    let provider = output
        .provider
        .as_deref()
        .context("Stripe provider transfer output missing provider")?;
    let params = [
        ("amount", output.amount_minor.to_string()),
        ("currency", output.currency.clone()),
        ("destination", output.to.clone()),
        ("metadata[mayhem_provider]", provider.to_owned()),
        ("metadata[mayhem_au]", output.au.to_string()),
    ];
    let response = client
        .post(format!(
            "{}/v1/transfers",
            api_base_url.trim_end_matches('/')
        ))
        .basic_auth(secret_key, Some(""))
        .header("Idempotency-Key", idempotency_key)
        .header("content-type", "application/x-www-form-urlencoded")
        .body(form_urlencoded_body(&params))
        .send()
        .await
        .context("calling Stripe transfers API")?;
    let status = response.status();
    let body = response.text().await.unwrap_or_default();
    if !status.is_success() {
        bail!("Stripe transfer returned {status}: {body}");
    }
    let value: Value = serde_json::from_str(&body).context("parsing Stripe transfer response")?;
    let id = value
        .get("id")
        .and_then(Value::as_str)
        .filter(|value| value.starts_with("tr_"))
        .context("Stripe transfer response missing transfer id")?
        .to_owned();
    let amount_minor = value
        .get("amount")
        .and_then(Value::as_u64)
        .context("Stripe transfer response missing amount")?;
    let currency = value
        .get("currency")
        .and_then(Value::as_str)
        .context("Stripe transfer response missing currency")
        .and_then(normalize_admin_fiat_currency)?;
    let destination = value
        .get("destination")
        .and_then(Value::as_str)
        .context("Stripe transfer response missing destination")?
        .to_owned();
    Ok(StripeTransferResult {
        id,
        amount_minor,
        currency,
        destination,
    })
}

fn form_urlencoded_body(params: &[(&str, String)]) -> String {
    params
        .iter()
        .map(|(key, value)| {
            format!(
                "{}={}",
                form_urlencode_component(key),
                form_urlencode_component(value)
            )
        })
        .collect::<Vec<_>>()
        .join("&")
}

fn form_urlencode_component(value: &str) -> String {
    let mut out = String::new();
    for byte in value.bytes() {
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(char::from(byte));
            }
            b' ' => out.push('+'),
            _ => {
                let _ = write!(&mut out, "%{byte:02X}");
            }
        }
    }
    out
}

fn resolve_tnk_nonce(
    wallet_pubkey: &str,
    amount_au: MoneyAu,
    treasury_address: &str,
    rate: &PayTnkRate,
    args: &PayTnkArgs,
) -> Result<String> {
    if let Some(nonce) = args.nonce.as_deref() {
        if !is_hex_len(nonce, 64) {
            bail!("--nonce must be a 32-byte hex string");
        }
        return Ok(nonce.to_ascii_lowercase());
    }
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .context("system clock is before Unix epoch")?
        .as_nanos();
    Ok(blake3::hash(
        format!(
            "mayhem:tnk-deposit-nonce:v1:{wallet_pubkey}:{amount_au}:{treasury_address}:{}:{now}:{}",
            rate.tnk_usd_au,
            std::process::id()
        )
        .as_bytes(),
    )
    .to_hex()
    .to_string())
}

fn derive_tnk_memo_hash(wallet_pubkey: &str, nonce: &str) -> Result<String> {
    let pubkey = hex_decode_array::<32>(wallet_pubkey, "wallet public key")?;
    let nonce = hex_decode_array::<32>(nonce, "TNK deposit nonce")?;
    let mut hasher = blake3::Hasher::new();
    hasher.update(&pubkey);
    hasher.update(&nonce);
    Ok(hasher.finalize().to_hex().to_string())
}

fn au_to_tnk_e18_ceil_u128(au: MoneyAu, rate_tnk_usd_au: MoneyAu) -> Result<u128> {
    if rate_tnk_usd_au == 0 {
        bail!("rate_tnk_usd_au must be positive");
    }
    let numerator = au.checked_mul(TNK_E18).context("TNK conversion overflow")?;
    Ok(numerator.div_ceil(rate_tnk_usd_au))
}

fn tnk_e18_to_au_floor(tnk_e18: u128, rate_tnk_usd_au: MoneyAu) -> Result<MoneyAu> {
    let au = tnk_e18
        .checked_mul(rate_tnk_usd_au)
        .context("TNK credit conversion overflow")?
        / TNK_E18;
    Ok(au)
}

fn tnk_e18_to_decimal(tnk_e18: u128) -> String {
    let whole = tnk_e18 / TNK_E18;
    let fraction = tnk_e18 % TNK_E18;
    if fraction == 0 {
        return whole.to_string();
    }
    let mut fraction = format!("{fraction:018}");
    while fraction.ends_with('0') {
        fraction.pop();
    }
    format!("{whole}.{fraction}")
}

fn pay_tnk_deposit_intent_command(
    amount: &str,
    treasury_address: &str,
    nonce: &str,
    tnk_usd_au: MoneyAu,
    keypair: Option<&Path>,
    rpc_url: Option<&str>,
) -> String {
    let mut command = format!(
        "mayhem pay tnk --amount {} --treasury-address {} --nonce {} --tnk-usd-au {} --submit-intent",
        shell_single_quote(amount),
        shell_single_quote(treasury_address),
        shell_single_quote(nonce),
        tnk_usd_au
    );
    if let Some(keypair) = keypair {
        command.push_str(" --keypair ");
        command.push_str(&shell_single_quote(&keypair.display().to_string()));
    }
    if let Some(rpc_url) = rpc_url.filter(|value| !value.trim().is_empty()) {
        command.push_str(" --rpc-url ");
        command.push_str(&shell_single_quote(rpc_url));
    }
    command
}

fn emit_tnk_handoff(
    json_output: bool,
    amount_au: MoneyAu,
    msb_transfer_command: &str,
    deposit_binding: &str,
    deposit_intent_command: &str,
) -> Result<()> {
    let lines = [
        format!("Mayhem tnk deposit for {}", au_to_usd_amount(amount_au)),
        format!("Copy/paste deposit intent command: {deposit_intent_command}"),
        format!("Copy/paste MSB transfer command: {msb_transfer_command}"),
        format!("Deposit binding: {deposit_binding}"),
    ];
    if json_output {
        let mut stderr = io::stderr().lock();
        for line in lines {
            writeln!(stderr, "{line}")?;
        }
        stderr.flush()?;
    } else {
        let mut stdout = io::stdout().lock();
        for line in lines {
            writeln!(stdout, "{line}")?;
        }
        stdout.flush()?;
    }
    Ok(())
}

async fn submit_msb_transfer(
    network: &str,
    stores_directory: &Path,
    store_name: &str,
    to: &str,
    amount: &str,
    timeout_seconds: u64,
    max_retries: u64,
    expected_balance_before: Option<&str>,
) -> Result<MsbTransferOutput> {
    let mut args = vec![
        "transfer".to_owned(),
        "--network".to_owned(),
        network.to_owned(),
        "--stores-directory".to_owned(),
        stores_directory.display().to_string(),
        "--store-name".to_owned(),
        store_name.to_owned(),
        "--to".to_owned(),
        to.to_owned(),
        "--amount".to_owned(),
        amount.to_owned(),
        "--timeout-seconds".to_owned(),
        timeout_seconds.to_string(),
        "--max-retries".to_owned(),
        max_retries.to_string(),
    ];
    if let Some(balance) = expected_balance_before {
        args.extend([
            "--expected-balance-before".to_owned(),
            balance.trim().to_owned(),
        ]);
    }
    run_msb_transfer_helper(args).await
}

async fn run_msb_transfer_helper<T>(args: Vec<String>) -> Result<T>
where
    T: DeserializeOwned,
{
    let msb_app = repo_path("intercom/trac/msb")?;
    let pear_runtime = resolve_pear_runtime_path()?;
    let mut helper_args = vec!["--transfer-helper".to_owned()];
    helper_args.extend(args);
    let output = Command::new(&pear_runtime)
        .arg("run")
        .arg(&msb_app)
        .args(helper_args)
        .output()
        .await
        .with_context(|| {
            format!(
                "running MSB transfer helper via pear-runtime app {}",
                msb_app.display()
            )
        })?;
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        let stdout = String::from_utf8_lossy(&output.stdout);
        bail!(
            "MSB transfer helper failed via pear-runtime: {}{}{}",
            stderr.trim(),
            if stderr.trim().is_empty() || stdout.trim().is_empty() {
                ""
            } else {
                "; stdout: "
            },
            stdout.trim()
        );
    }
    parse_msb_transfer_helper_json(&output.stdout, &output.stderr)
}

fn parse_msb_transfer_helper_json<T>(stdout: &[u8], stderr: &[u8]) -> Result<T>
where
    T: DeserializeOwned,
{
    if let Ok(value) = serde_json::from_slice(stdout) {
        return Ok(value);
    }
    let stdout_text = String::from_utf8_lossy(stdout);
    for (idx, _) in stdout_text.match_indices('{') {
        if let Ok(value) = serde_json::from_str::<T>(stdout_text[idx..].trim()) {
            return Ok(value);
        }
    }
    let stderr_text = String::from_utf8_lossy(stderr);
    bail!(
        "parsing Pear MSB transfer helper JSON output failed; stdout: {}; stderr: {}",
        truncate_log_for_error(stdout_text.trim()),
        truncate_log_for_error(stderr_text.trim())
    )
}

fn truncate_log_for_error(value: &str) -> String {
    const MAX: usize = 2_000;
    if value.len() <= MAX {
        return value.to_owned();
    }
    let end = value
        .char_indices()
        .map(|(idx, _)| idx)
        .take_while(|idx| *idx <= MAX)
        .last()
        .unwrap_or(0);
    format!("{}...(truncated)", &value[..end])
}

