#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct ProviderLoadSnapshot {
    active_slots: u64,
    active_requests: u64,
    free_slots: u64,
    engine_backlog: u64,
    est_wait_ms: u64,
    ttft_ms: u64,
    measured_tok_s_milli: Option<u64>,
    accepting_new: bool,
}

impl Default for ProviderLoadSnapshot {
    fn default() -> Self {
        Self {
            active_slots: 0,
            active_requests: 0,
            free_slots: 0,
            engine_backlog: 0,
            est_wait_ms: 0,
            ttft_ms: 0,
            measured_tok_s_milli: None,
            accepting_new: true,
        }
    }
}

impl ProviderLoadSnapshot {
    #[cfg(test)]
    fn from_sessions(sessions: &HashMap<String, ActiveProviderSession>) -> Self {
        Self {
            active_slots: u64::try_from(sessions.len()).unwrap_or(u64::MAX),
            active_requests: 0,
            free_slots: 0,
            engine_backlog: 0,
            est_wait_ms: 0,
            ttft_ms: 0,
            measured_tok_s_milli: None,
            accepting_new: true,
        }
    }
}

#[derive(Clone, Debug)]
struct ProviderHeartbeatLoad {
    active_slots: Arc<AtomicU64>,
    active_requests: Arc<AtomicU64>,
    rolling_turn_ms: Arc<AtomicU64>,
    rolling_ttft_ms: Arc<AtomicU64>,
    rolling_tok_s_milli: Arc<AtomicU64>,
    accepting_new: Arc<AtomicBool>,
    stop: Arc<AtomicBool>,
}

impl Default for ProviderHeartbeatLoad {
    fn default() -> Self {
        Self {
            active_slots: Arc::new(AtomicU64::new(0)),
            active_requests: Arc::new(AtomicU64::new(0)),
            rolling_turn_ms: Arc::new(AtomicU64::new(0)),
            rolling_ttft_ms: Arc::new(AtomicU64::new(0)),
            rolling_tok_s_milli: Arc::new(AtomicU64::new(0)),
            accepting_new: Arc::new(AtomicBool::new(true)),
            stop: Arc::new(AtomicBool::new(false)),
        }
    }
}

impl ProviderHeartbeatLoad {
    fn snapshot(&self) -> ProviderLoadSnapshot {
        let active_slots = self.active_slots.load(Ordering::Relaxed);
        let active_requests = self.active_requests.load(Ordering::Relaxed);
        let free_slots = active_slots.saturating_sub(active_requests);
        let engine_backlog = active_requests.saturating_sub(active_slots);
        let rolling_turn_ms = self.rolling_turn_ms.load(Ordering::Relaxed);
        let est_wait_ms = if engine_backlog > 0 && rolling_turn_ms > 0 {
            rolling_turn_ms.saturating_mul(engine_backlog)
        } else {
            0
        };
        let measured_tok_s_milli = match self.rolling_tok_s_milli.load(Ordering::Relaxed) {
            0 => None,
            value => Some(value),
        };
        ProviderLoadSnapshot {
            active_slots,
            active_requests,
            free_slots,
            engine_backlog,
            est_wait_ms,
            ttft_ms: self.rolling_ttft_ms.load(Ordering::Relaxed),
            measured_tok_s_milli,
            accepting_new: self.accepting_new.load(Ordering::Relaxed),
        }
    }

    fn set_active_sessions(&self, sessions: usize) {
        let active = u64::try_from(sessions).unwrap_or(u64::MAX);
        self.active_slots.store(active, Ordering::Relaxed);
    }

    fn begin_request(&self) -> ProviderRequestLoadGuard {
        self.active_requests.fetch_add(1, Ordering::Relaxed);
        ProviderRequestLoadGuard {
            load: self.clone(),
            started: Instant::now(),
            finished: false,
        }
    }

    fn record_ttft_ms(&self, ttft_ms: u64) {
        self.store_rolling_ms(&self.rolling_ttft_ms, ttft_ms.max(1));
    }

    fn record_turn_result(&self, elapsed: Duration, throughput_units: u64) {
        let elapsed_ms = duration_millis_u64(elapsed).max(1);
        self.store_rolling_ms(&self.rolling_turn_ms, elapsed_ms);
        if throughput_units > 0 {
            let tok_s_milli = ((u128::from(throughput_units) * 1_000_000_u128)
                / u128::from(elapsed_ms))
            .min(u128::from(u64::MAX)) as u64;
            self.store_rolling_ms(&self.rolling_tok_s_milli, tok_s_milli.max(1));
        }
    }

    fn set_accepting_new(&self, accepting_new: bool) {
        self.accepting_new.store(accepting_new, Ordering::Relaxed);
    }

    fn is_accepting_new(&self) -> bool {
        self.accepting_new.load(Ordering::Relaxed)
    }

    fn finish_request(&self) {
        let _ =
            self.active_requests
                .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |current| {
                    current.checked_sub(1)
                });
    }

    fn store_rolling_ms(&self, target: &AtomicU64, sample: u64) {
        let previous = target.load(Ordering::Relaxed);
        let next = if previous == 0 {
            sample
        } else {
            previous
                .saturating_mul(3)
                .saturating_add(sample)
                .saturating_add(2)
                / 4
        };
        target.store(next, Ordering::Relaxed);
    }

    fn stop(&self) {
        self.stop.store(true, Ordering::Relaxed);
    }

    fn is_stopped(&self) -> bool {
        self.stop.load(Ordering::Relaxed)
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct ProviderProtectionConfig {
    max_sessions: u32,
    accept_rate_per_minute: u32,
    budget_au: MoneyAu,
    budget_units: u64,
    budget_period: Duration,
}

impl ProviderProtectionConfig {
    fn from_provider_args(args: &ProviderStartArgs, selected: &ProviderCandidate) -> Result<Self> {
        let max_sessions = args.max_sessions.unwrap_or(selected.verdict.max_sessions);
        if max_sessions == 0 {
            bail!("provider --max-sessions must be greater than zero");
        }
        if (args.serve_budget_au > 0 || args.serve_budget_units > 0)
            && args.serve_budget_period_seconds == 0
        {
            bail!("provider --serve-budget-period-seconds must be greater than zero when a serving budget is set");
        }
        Ok(Self {
            max_sessions,
            accept_rate_per_minute: args.accept_rate_per_minute,
            budget_au: args.serve_budget_au,
            budget_units: args.serve_budget_units,
            budget_period: Duration::from_secs(args.serve_budget_period_seconds.max(1)),
        })
    }

    #[cfg(test)]
    fn unlimited_for_tests(max_sessions: u32) -> Self {
        Self {
            max_sessions,
            accept_rate_per_minute: 0,
            budget_au: 0,
            budget_units: 0,
            budget_period: Duration::from_secs(86_400),
        }
    }
}

#[derive(Clone, Debug)]
struct ProviderProtectionState {
    config: ProviderProtectionConfig,
    accepted_at: VecDeque<Instant>,
    period_started: Instant,
    used_au: MoneyAu,
    used_units: u64,
}

impl ProviderProtectionState {
    fn new(config: ProviderProtectionConfig) -> Self {
        Self {
            config,
            accepted_at: VecDeque::new(),
            period_started: Instant::now(),
            used_au: 0,
            used_units: 0,
        }
    }

    fn acceptance_decision(&mut self, active_sessions: usize) -> ProviderSessionDecision {
        let now = Instant::now();
        self.reset_if_period_elapsed(now);
        self.prune_accept_window(now);
        if active_sessions >= self.config.max_sessions as usize {
            return ProviderSessionDecision::Reject {
                code: "CAPACITY",
                reason: format!(
                    "provider has reached its local max_sessions cap of {}",
                    self.config.max_sessions
                ),
            };
        }
        if self.config.accept_rate_per_minute > 0
            && self.accepted_at.len() >= self.config.accept_rate_per_minute as usize
        {
            return ProviderSessionDecision::Reject {
                code: "RATE",
                reason: format!(
                    "provider has reached its local accept-rate limit of {} session(s)/minute",
                    self.config.accept_rate_per_minute
                ),
            };
        }
        if self.config.budget_au > 0 && self.used_au >= self.config.budget_au {
            return ProviderSessionDecision::Reject {
                code: "QUOTA",
                reason: format!(
                    "provider has reached its local serving budget of {} for this period",
                    au_to_usd_amount(self.config.budget_au)
                ),
            };
        }
        if self.config.budget_units > 0 && self.used_units >= self.config.budget_units {
            return ProviderSessionDecision::Reject {
                code: "QUOTA",
                reason: format!(
                    "provider has reached its local serving budget of {} usage unit(s) for this period",
                    self.config.budget_units
                ),
            };
        }
        ProviderSessionDecision::Accept
    }

    fn record_accept(&mut self) {
        let now = Instant::now();
        self.prune_accept_window(now);
        self.accepted_at.push_back(now);
    }

    fn record_usage(&mut self, usage: &ReceiptUsage, au_owed: MoneyAu) {
        self.reset_if_period_elapsed(Instant::now());
        self.used_au = self.used_au.saturating_add(au_owed);
        self.used_units = self
            .used_units
            .saturating_add(provider_session_usage_units(usage));
    }

    fn reset_if_period_elapsed(&mut self, now: Instant) {
        if now.duration_since(self.period_started) >= self.config.budget_period {
            self.period_started = now;
            self.used_au = 0;
            self.used_units = 0;
        }
    }

    fn prune_accept_window(&mut self, now: Instant) {
        while self
            .accepted_at
            .front()
            .is_some_and(|accepted| now.duration_since(*accepted) >= Duration::from_secs(60))
        {
            self.accepted_at.pop_front();
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ProviderRuntimeFloorRejection {
    code: &'static str,
    reason: String,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ProviderRuntimeDiskObservation {
    path: PathBuf,
    available_bytes: Option<u64>,
    reserve_bytes: u64,
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum ProviderRuntimeMemoryObservation {
    NotChecked,
    #[cfg_attr(target_os = "macos", allow(dead_code))]
    AvailableBytes {
        pool: String,
        available_bytes: Option<u64>,
        reserve_bytes: u64,
    },
    #[cfg(any(target_os = "macos", test))]
    MacosPressure {
        level: Option<i32>,
        stop_level: i32,
    },
}

#[derive(Clone, Debug)]
struct ProviderRuntimeFloorMonitor {
    disk_paths: Vec<PathBuf>,
    disk_reserve_bytes: u64,
    memory_pool: String,
    memory_reserve_bytes: u64,
}

impl ProviderRuntimeFloorMonitor {
    fn new(args: &ProviderStartArgs, home: &Path, selected: &ProviderCandidate) -> Result<Self> {
        let downloads_dir = args
            .downloads_dir
            .clone()
            .unwrap_or_else(|| home.join("downloads"));
        let downloads_dir = absolutize(downloads_dir)?;
        let mut disk_paths = vec![home.to_path_buf(), downloads_dir];
        disk_paths.sort();
        disk_paths.dedup();
        let (disk_reserve_bytes, _) = provider_disk_reserve_bytes(args.disk_reserve.as_deref())?;
        Ok(Self {
            disk_paths,
            disk_reserve_bytes,
            memory_pool: selected.feasibility.memory_budget.pool.clone(),
            memory_reserve_bytes: selected.feasibility.memory_budget.reserve_bytes,
        })
    }

    fn check(&self) -> Option<ProviderRuntimeFloorRejection> {
        let disk = self
            .disk_paths
            .iter()
            .map(|path| ProviderRuntimeDiskObservation {
                path: path.clone(),
                available_bytes: available_bytes_for_path(path).ok().flatten(),
                reserve_bytes: self.disk_reserve_bytes,
            })
            .collect::<Vec<_>>();
        let memory = provider_runtime_memory_observation(
            self.memory_reserve_bytes,
            self.memory_pool.as_str(),
        );
        provider_runtime_floor_rejection_from_observations(&disk, memory)
    }

    fn memory_check(&self) -> Option<ProviderRuntimeFloorRejection> {
        provider_runtime_floor_rejection_from_observations(
            &[],
            provider_runtime_memory_observation(self.memory_reserve_bytes, &self.memory_pool),
        )
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ProviderEngineRssObservation {
    pids: Vec<u32>,
    total_rss_bytes: Option<u64>,
    limit_bytes: u64,
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum ProviderEngineWatchdogAction {
    Healthy,
    RefuseNew(ProviderRuntimeFloorRejection),
    RestartNow(ProviderRuntimeFloorRejection),
}

#[derive(Clone, Debug)]
struct ProviderEngineWatchdog {
    limit_bytes: u64,
    sustained_samples: u32,
    cooldown_until: Option<Instant>,
}

impl ProviderEngineWatchdog {
    fn new(selected: &ProviderCandidate) -> Self {
        Self {
            limit_bytes: selected.feasibility.memory_budget.budget_bytes,
            sustained_samples: 0,
            cooldown_until: None,
        }
    }

    fn check(
        &mut self,
        memory_floor: Option<ProviderRuntimeFloorRejection>,
        rss: ProviderEngineRssObservation,
        active_sessions: usize,
        now: Instant,
    ) -> ProviderEngineWatchdogAction {
        let Some(reject) = provider_engine_watchdog_rejection(memory_floor, &rss) else {
            self.sustained_samples = 0;
            return ProviderEngineWatchdogAction::Healthy;
        };
        self.sustained_samples = self.sustained_samples.saturating_add(1);
        if self.sustained_samples < PROVIDER_ENGINE_WATCHDOG_SUSTAINED_SAMPLES {
            return ProviderEngineWatchdogAction::RefuseNew(reject);
        }
        if active_sessions > 0 {
            return ProviderEngineWatchdogAction::RefuseNew(reject);
        }
        if self.cooldown_until.is_some_and(|until| now < until) {
            return ProviderEngineWatchdogAction::RefuseNew(reject);
        }
        self.cooldown_until =
            Some(now + Duration::from_secs(PROVIDER_ENGINE_WATCHDOG_RESTART_COOLDOWN_SECONDS));
        ProviderEngineWatchdogAction::RestartNow(reject)
    }

    fn reset_after_restart(&mut self) {
        self.sustained_samples = 0;
    }
}

fn provider_runtime_memory_observation(
    reserve_bytes: u64,
    pool: &str,
) -> ProviderRuntimeMemoryObservation {
    if reserve_bytes == 0 {
        return ProviderRuntimeMemoryObservation::NotChecked;
    }
    #[cfg(target_os = "macos")]
    {
        let _ = pool;
        return ProviderRuntimeMemoryObservation::MacosPressure {
            level: provider_macos_memory_pressure_level(),
            stop_level: PROVIDER_MACOS_MEMORY_PRESSURE_STOP_LEVEL,
        };
    }
    #[cfg(not(target_os = "macos"))]
    {
        ProviderRuntimeMemoryObservation::AvailableBytes {
            pool: pool.to_owned(),
            available_bytes: provider_live_memory_available_bytes(),
            reserve_bytes,
        }
    }
}

#[cfg(target_os = "macos")]
fn provider_macos_memory_pressure_level() -> Option<i32> {
    let output = std::process::Command::new("sysctl")
        .args(["-n", "kern.memorystatus_vm_pressure_level"])
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    String::from_utf8_lossy(&output.stdout)
        .trim()
        .parse::<i32>()
        .ok()
}

#[cfg(target_os = "linux")]
fn provider_live_memory_available_bytes() -> Option<u64> {
    let text = fs::read_to_string("/proc/meminfo").ok()?;
    for line in text.lines() {
        let Some(rest) = line.strip_prefix("MemAvailable:") else {
            continue;
        };
        let kib = rest.split_whitespace().next()?.parse::<u64>().ok()?;
        return kib.checked_mul(1024);
    }
    None
}

#[cfg(target_os = "windows")]
fn provider_live_memory_available_bytes() -> Option<u64> {
    let output = std::process::Command::new("powershell")
        .args([
            "-NoProfile",
            "-Command",
            "(Get-CimInstance Win32_OperatingSystem).FreePhysicalMemory",
        ])
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    let kib = String::from_utf8_lossy(&output.stdout)
        .trim()
        .parse::<u64>()
        .ok()?;
    kib.checked_mul(1024)
}

#[cfg(not(any(target_os = "linux", target_os = "windows", target_os = "macos")))]
fn provider_live_memory_available_bytes() -> Option<u64> {
    None
}

fn provider_runtime_floor_rejection_from_observations(
    disk: &[ProviderRuntimeDiskObservation],
    memory: ProviderRuntimeMemoryObservation,
) -> Option<ProviderRuntimeFloorRejection> {
    for observation in disk {
        if let Some(available_bytes) = observation.available_bytes {
            if available_bytes < observation.reserve_bytes {
                return Some(ProviderRuntimeFloorRejection {
                    code: "CAPACITY",
                    reason: format!(
                        "provider disk floor is active: {} has {} free, below reserve {}; refusing new sessions until space frees",
                        observation.path.display(),
                        human_bytes(available_bytes),
                        human_bytes(observation.reserve_bytes)
                    ),
                });
            }
        }
    }
    match memory {
        ProviderRuntimeMemoryObservation::AvailableBytes {
            pool,
            available_bytes: Some(available_bytes),
            reserve_bytes,
        } if available_bytes < reserve_bytes => Some(ProviderRuntimeFloorRejection {
            code: "CAPACITY",
            reason: format!(
                "provider memory floor is active: {pool} has {} available, below reserve {}; refusing new sessions until memory frees",
                human_bytes(available_bytes),
                human_bytes(reserve_bytes)
            ),
        }),
        #[cfg(any(target_os = "macos", test))]
        ProviderRuntimeMemoryObservation::MacosPressure {
            level: Some(level),
            stop_level,
        } if level >= stop_level => Some(ProviderRuntimeFloorRejection {
            code: "CAPACITY",
            reason: format!(
                "provider macOS memory-pressure floor is active: pressure level {level} reached stop level {stop_level}; refusing new sessions until pressure clears"
            ),
        }),
        _ => None,
    }
}

fn provider_engine_watchdog_rejection(
    memory_floor: Option<ProviderRuntimeFloorRejection>,
    rss: &ProviderEngineRssObservation,
) -> Option<ProviderRuntimeFloorRejection> {
    if let Some(memory_floor) = memory_floor {
        return Some(ProviderRuntimeFloorRejection {
            code: memory_floor.code,
            reason: format!(
                "{}; provider engine watchdog will keep refusing new sessions and reload the engine after active sessions drain",
                memory_floor.reason
            ),
        });
    }
    let Some(total_rss_bytes) = rss.total_rss_bytes else {
        return None;
    };
    if rss.limit_bytes > 0 && total_rss_bytes > rss.limit_bytes {
        return Some(ProviderRuntimeFloorRejection {
            code: "CAPACITY",
            reason: format!(
                "provider engine watchdog is active: engine/process RSS {} across pid(s) {} exceeds budget {}; refusing new sessions and reloading the engine after active sessions drain",
                human_bytes(total_rss_bytes),
                rss.pids
                    .iter()
                    .map(u32::to_string)
                    .collect::<Vec<_>>()
                    .join(","),
                human_bytes(rss.limit_bytes)
            ),
        });
    }
    None
}

fn provider_engine_rss_observation(
    responder: &dyn ProviderSessionResponder,
    limit_bytes: u64,
) -> ProviderEngineRssObservation {
    let mut pids = responder.process_ids();
    pids.push(std::process::id());
    pids.sort_unstable();
    pids.dedup();
    let mut total = 0_u64;
    let mut observed_any = false;
    for pid in &pids {
        if let Some(rss) = provider_process_rss_bytes(*pid) {
            observed_any = true;
            total = total.saturating_add(rss);
        }
    }
    ProviderEngineRssObservation {
        pids,
        total_rss_bytes: observed_any.then_some(total),
        limit_bytes,
    }
}

#[cfg(target_os = "linux")]
fn provider_process_rss_bytes(pid: u32) -> Option<u64> {
    let text = fs::read_to_string(format!("/proc/{pid}/status")).ok()?;
    for line in text.lines() {
        let Some(rest) = line.strip_prefix("VmRSS:") else {
            continue;
        };
        let kib = rest.split_whitespace().next()?.parse::<u64>().ok()?;
        return kib.checked_mul(1024);
    }
    None
}

#[cfg(target_os = "macos")]
fn provider_process_rss_bytes(pid: u32) -> Option<u64> {
    let output = std::process::Command::new("ps")
        .args(["-o", "rss=", "-p", &pid.to_string()])
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    let kib = String::from_utf8_lossy(&output.stdout)
        .split_whitespace()
        .next()?
        .parse::<u64>()
        .ok()?;
    kib.checked_mul(1024)
}

#[cfg(target_os = "windows")]
fn provider_process_rss_bytes(pid: u32) -> Option<u64> {
    let output = std::process::Command::new("powershell")
        .args([
            "-NoProfile",
            "-Command",
            &format!("(Get-Process -Id {pid}).WorkingSet64"),
        ])
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    String::from_utf8_lossy(&output.stdout)
        .trim()
        .parse::<u64>()
        .ok()
}

#[cfg(not(any(target_os = "linux", target_os = "macos", target_os = "windows")))]
fn provider_process_rss_bytes(_pid: u32) -> Option<u64> {
    None
}

fn provider_session_usage_units(usage: &ReceiptUsage) -> u64 {
    usage
        .units()
        .values()
        .copied()
        .fold(0_u64, u64::saturating_add)
}

fn provider_session_throughput_units(usage: &ReceiptUsage) -> u64 {
    for unit in [
        mayhem_proto::USAGE_OUTPUT_TOKEN,
        USAGE_IMAGE,
        USAGE_AUDIO_SECOND,
        mayhem_proto::USAGE_INPUT_TOKEN,
    ] {
        let value = usage.get(unit);
        if value > 0 {
            return value;
        }
    }
    provider_session_usage_units(usage)
}

fn provider_session_throughput_unit(usage: &ReceiptUsage) -> &'static str {
    if usage.output_tokens() > 0 {
        "output_tok_s"
    } else if usage.get(USAGE_IMAGE) > 0 {
        "images_s"
    } else if usage.get(USAGE_AUDIO_SECOND) > 0 {
        "audio_rtf"
    } else if usage.input_tokens() > 0 {
        "input_tok_s"
    } else {
        "usage_units_s"
    }
}

fn provider_session_quality_value(
    output: &ProviderSessionOutput,
    elapsed: Duration,
    first_ttft_ms: Option<u64>,
) -> Value {
    let elapsed_ms = duration_millis_u64(elapsed).max(1);
    let throughput_units = provider_session_throughput_units(&output.usage);
    let throughput = throughput_units as f64 * 1000.0 / elapsed_ms as f64;
    json!({
        "ttft_ms": first_ttft_ms.unwrap_or(elapsed_ms),
        "compute_ms": elapsed_ms,
        "throughput": throughput,
        "unit": provider_session_throughput_unit(&output.usage),
    })
}

struct ProviderRequestLoadGuard {
    load: ProviderHeartbeatLoad,
    started: Instant,
    finished: bool,
}

impl ProviderRequestLoadGuard {
    fn started(&self) -> Instant {
        self.started
    }

    fn finish_with_output(&mut self, output: &ProviderSessionOutput) {
        self.load.record_turn_result(
            self.started.elapsed(),
            provider_session_throughput_units(&output.usage),
        );
        self.finish();
    }

    fn finish(&mut self) {
        if !self.finished {
            self.load.finish_request();
            self.finished = true;
        }
    }
}

impl Drop for ProviderRequestLoadGuard {
    fn drop(&mut self) {
        self.finish();
    }
}

