    #[test]
    fn config_set_persists_aliases_and_rejects_home() {
        let home = test_temp_dir("mayhem-config-set");
        fs::create_dir_all(&home).unwrap();
        let args = ConfigSetArgs {
            home: Some(home.clone()),
            key: "rpc_url".to_owned(),
            value: "http://127.0.0.1:49223/v1".to_owned(),
            json: false,
        };
        config_set(args).unwrap();
        let config = read_config_toml_value(&config_path_for_home(&home)).unwrap();
        assert_eq!(
            toml_get_path(&config, "network.rpc_url").and_then(toml::Value::as_str),
            Some("http://127.0.0.1:49223/v1")
        );
        assert_eq!(
            canonical_config_key("sc-bridge-token").unwrap(),
            "network.sc_bridge_token"
        );
        assert_eq!(canonical_config_key("network").unwrap(), "network.name");
        assert_eq!(
            canonical_config_key("subnet-bootstrap").unwrap(),
            "network.subnet_bootstrap"
        );
        assert_eq!(
            canonical_config_key("msb-bootstrap").unwrap(),
            "network.msb_bootstrap"
        );
        assert_eq!(canonical_config_key("min-ctx").unwrap(), "user.min_ctx");
        assert_eq!(
            canonical_config_key("memory-reserve").unwrap(),
            "provider.limits.memory_reserve"
        );
        assert_eq!(
            canonical_config_key("disk-reserve").unwrap(),
            "provider.limits.disk_reserve"
        );
        config_set(ConfigSetArgs {
            home: Some(home.clone()),
            key: "min-ctx".to_owned(),
            value: "128000".to_owned(),
            json: true,
        })
        .unwrap();
        let config = read_config_toml_value(&config_path_for_home(&home)).unwrap();
        assert_eq!(
            toml_get_path(&config, "user.min_ctx").and_then(toml::Value::as_integer),
            Some(128_000)
        );
        config_set(ConfigSetArgs {
            home: Some(home.clone()),
            key: "memory-reserve".to_owned(),
            value: "15%".to_owned(),
            json: true,
        })
        .unwrap();
        config_set(ConfigSetArgs {
            home: Some(home.clone()),
            key: "disk-reserve".to_owned(),
            value: "20GB".to_owned(),
            json: true,
        })
        .unwrap();
        let config = read_config_toml_value(&config_path_for_home(&home)).unwrap();
        assert_eq!(
            toml_get_path(&config, "provider.limits.memory_reserve").and_then(toml::Value::as_str),
            Some("15%")
        );
        assert_eq!(
            toml_get_path(&config, "provider.limits.disk_reserve").and_then(toml::Value::as_str),
            Some("20GB")
        );
        let typed = read_mayhem_config(&home).unwrap().unwrap();
        assert_eq!(typed.user.and_then(|user| user.min_ctx), Some(128_000));
        assert!(canonical_config_key("home").is_err());
        fs::remove_dir_all(&home).unwrap();
    }

    #[test]
    fn config_max_price_and_generic_alias_persist_string_toml() {
        let home = test_temp_dir("mayhem-config-max-price");
        config_max_price(ConfigMaxPriceArgs {
            home: Some(home.clone()),
            au: Some(12_345),
            clear: false,
            json: true,
        })
        .unwrap();
        let config = read_config_toml_value(&config_path_for_home(&home)).unwrap();
        assert_eq!(
            toml_get_path(&config, "user.max_price_au").and_then(toml::Value::as_str),
            Some("12345")
        );
        let typed = read_mayhem_config(&home).unwrap().unwrap();
        assert_eq!(typed.user.and_then(|user| user.max_price_au), Some(12_345));

        config_set(ConfigSetArgs {
            home: Some(home.clone()),
            key: "max-price".to_owned(),
            value: "54321".to_owned(),
            json: true,
        })
        .unwrap();
        config_set(ConfigSetArgs {
            home: Some(home.clone()),
            key: "max-wait".to_owned(),
            value: "0".to_owned(),
            json: true,
        })
        .unwrap();
        let config = read_config_toml_value(&config_path_for_home(&home)).unwrap();
        assert_eq!(
            toml_get_path(&config, "user.max_price_au").and_then(toml::Value::as_str),
            Some("54321")
        );
        assert_eq!(
            toml_get_path(&config, "user.max_wait_seconds").and_then(toml::Value::as_integer),
            Some(0)
        );
        let typed = read_mayhem_config(&home).unwrap().unwrap();
        assert_eq!(typed.user.and_then(|user| user.max_wait_seconds), Some(0));

        config_max_price(ConfigMaxPriceArgs {
            home: Some(home.clone()),
            au: None,
            clear: true,
            json: true,
        })
        .unwrap();
        let config = read_config_toml_value(&config_path_for_home(&home)).unwrap();
        assert!(toml_get_path(&config, "user.max_price_au").is_none());
        fs::remove_dir_all(&home).unwrap();
    }

