    #[test]
    fn marketplace_cli_parses_short_operator_commands() {
        let min_ask = Cli::try_parse_from([
            "mayhem",
            "provider",
            "min-ask",
            "set",
            "test/model:T3",
            "900",
            "--json",
        ])
        .unwrap();
        let Commands::Provider { command, .. } = min_ask.command else {
            panic!("expected provider command");
        };
        let ProviderCommands::MinAsk { command } = *command else {
            panic!("expected min-ask command");
        };
        let ProviderMinAskCommands::Set(args) = command else {
            panic!("expected min-ask set");
        };
        assert_eq!(args.target, "test/model:T3");
        assert_eq!(args.au, 900);
        assert!(args.json);

        let limits = Cli::try_parse_from([
            "mayhem",
            "provider",
            "limits",
            "set",
            "--enclave",
            "test/model:T3",
            "--max-concurrent",
            "2",
            "--accept-rate",
            "10/min",
            "--budget",
            "2.50usd/day",
            "--json",
        ])
        .unwrap();
        let Commands::Provider { command, .. } = limits.command else {
            panic!("expected provider command");
        };
        let ProviderCommands::Limits { command } = *command else {
            panic!("expected limits command");
        };
        let ProviderLimitsCommands::Set(args) = command else {
            panic!("expected limits set");
        };
        assert_eq!(args.enclave.as_deref(), Some("test/model:T3"));
        assert_eq!(args.max_concurrent, Some(2));
        assert_eq!(args.accept_rate.as_deref(), Some("10/min"));
        assert_eq!(args.budget.as_deref(), Some("2.50usd/day"));
        assert!(args.json);

        let price = Cli::try_parse_from([
            "mayhem",
            "price",
            "show",
            "test/model",
            "--tier",
            "3",
            "--json",
        ])
        .unwrap();
        let Commands::Price { command } = price.command else {
            panic!("expected price command");
        };
        let args = match command {
            PriceCommands::Show(args) => args,
        };
        assert_eq!(args.model, "test/model");
        assert_eq!(args.tier, Some(3));
        assert!(args.json);
    }

    #[test]
    fn admin_publish_catalog_payload_anchors_signed_release_urls() {
        let args = AdminPublishCatalogArgs {
            tx: test_admin_tx_args(),
            catalog_path: None,
            signature_path: None,
            keys_dir: None,
            canaries_dir: None,
            catalog_url: "https://huggingface.co/TracNetwork/mayhem-catalog/resolve/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/models.json".to_owned(),
            signature_url: "https://huggingface.co/TracNetwork/mayhem-catalog/resolve/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/models.json.sig".to_owned(),
            canaries_base_url: "https://huggingface.co/TracNetwork/mayhem-catalog/resolve/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/canaries".to_owned(),
            source_kind: "huggingface".to_owned(),
        };

        let payload = admin_publish_catalog_payload(&args).unwrap();

        assert_eq!(payload["op"], "publish_catalog");
        assert_eq!(payload["source_kind"], "huggingface");
        assert!(is_hex_len(payload["catalog_hash"].as_str().unwrap(), 64));
        assert!(is_hex_len(payload["signature_hash"].as_str().unwrap(), 64));
        let catalog_doc =
            catalog::load_document(&repo_path("catalog/models.json").unwrap()).unwrap();
        let expected_artifact_count = catalog_doc
            .models
            .iter()
            .map(|model| model.artifacts.len())
            .sum::<usize>();
        assert_eq!(payload["model_count"], catalog_doc.models.len());
        assert_eq!(payload["artifact_count"], expected_artifact_count);
        assert!(payload["canaries"].as_array().unwrap().iter().any(|entry| {
            entry["set_id"] == "canary-launch-v1"
                && entry["url"]
                    .as_str()
                    .unwrap()
                    .ends_with("/canaries/canary-launch-v1.json")
        }));
    }

