    #[test]
    fn admin_register_enclave_requires_greenlit_catalog_artifact() {
        let temp = env::temp_dir().join(format!(
            "mayhem-cli-admin-catalog-gate-{}-{}",
            std::process::id(),
            unix_epoch_millis().unwrap()
        ));
        fs::create_dir_all(&temp).unwrap();
        let catalog_path = temp.join("models.json");
        let artifact_root = "aa".repeat(32);
        let source_sha256 = "bb".repeat(32);
        fs::write(
            &catalog_path,
            format!(
                r#"{{
  "schema_version": 1,
  "catalog_id": "test-admin-catalog",
  "generated_at": "2026-07-04T00:00:00Z",
  "models": [{{
    "model_id": "test/model@4bit",
    "family": "test",
    "params_b": 1.0,
    "tier": "dev",
    "provenance": {{
      "source": {{ "kind": "huggingface", "repo": "test/source", "revision": "{source_revision}" }},
      "conversion": [],
      "license": "test",
      "license_sha256": "{license_sha}"
    }},
    "artifacts": {{
      "gguf-q4_k_m": {{
        "engine": "llama.cpp",
        "source": {{ "kind": "huggingface", "repo": "admin/model", "revision": "{artifact_revision}" }},
        "path": "model.gguf",
        "artifact_root": "{artifact_root}",
        "artifact_root_kind": "blake3_merkle_v1",
        "weights_bytes": 42,
        "source_sha256": "{source_sha256}"
      }}
    }},
    "caps": {{ "tools": true, "json": true, "ctx_max": 8192, "vision": false }},
    "requirements": {{ "min_ram_gb": 1, "min_vram_gb_full_offload": 0, "cpu_flags": [], "backends": ["llama.cpp"] }},
    "canary": {{ "set_id": "canary-dev-v1", "match_min": 0.9, "fingerprints": {{}} }},
    "price_ref_au": {{ "denom": "au_usd", "in_per_1k": "20", "out_per_1k": "60" }}
  }}]
}}
"#,
                source_revision = "11".repeat(20),
                artifact_revision = "22".repeat(20),
                license_sha = "33".repeat(32),
            ),
        )
        .unwrap();

        let args = AdminRegisterEnclaveArgs {
            tx: test_admin_tx_args(),
            enclave_id: "44".repeat(32),
            model: "test/model@4bit".to_owned(),
            backend: "llama.cpp".to_owned(),
            artifact_root: artifact_root.clone(),
            artifact_root_kind: "blake3_merkle_v1".to_owned(),
            artifact_repo: "admin/model".to_owned(),
            artifact_revision: "22".repeat(20),
            artifact_path: "model.gguf".to_owned(),
            source_sha256: Some(source_sha256),
            catalog_path: Some(catalog_path),
            signature_path: None,
            keys_dir: None,
            canaries_dir: None,
            dev_skip_catalog_verify: true,
            manifest_hash: "55".repeat(32),
            binary_hash: "66".repeat(32),
            launch_measurements_json: None,
            launch_measurements_file: None,
            att_tier: 1,
            quant: None,
            caps_json: Some(r#"{"tools":true,"json":true,"ctx":8192}"#.to_owned()),
            caps_file: None,
        };

        let payload = admin_register_enclave_payload(&args).unwrap();
        assert_eq!(payload["artifact_source"]["repo"], "admin/model");
        assert_eq!(payload["artifact_root"], artifact_root);
        assert_eq!(payload["model_class"], DEFAULT_MODEL_CLASS);
        assert_eq!(payload["quant"], "int4");

        let mut tier2_args = args;
        tier2_args.att_tier = 2;
        let tier2_payload = admin_register_enclave_payload(&tier2_args)
            .expect("Tier-2 enclave hardware registration is launch-advertisable");
        assert_eq!(tier2_payload["att_tier"], json!(2));

        let mut tier3_missing_measurement = tier2_args;
        tier3_missing_measurement.att_tier = 3;
        let err = admin_register_enclave_payload(&tier3_missing_measurement)
            .expect_err("Tier 3 requires admin-published golden measurements");
        assert!(err.to_string().contains("launch-measurements"), "{err:#}");

        let mut tier3_args = tier3_missing_measurement;
        tier3_args.launch_measurements_json = Some(
            r#"{"schema_version":1,"effective_epoch":0,"platform":"azure-h100-sev-snp-nvidia-cc","layers":{"workload":{"vtpm_pcr_0":"abababababababababababababababababababababababababababababababababababababababababababababababab"}}}"#
                .to_owned(),
        );
        let tier3_payload = admin_register_enclave_payload(&tier3_args)
            .expect("Tier 3 accepts admin-published golden measurements");
        assert_eq!(tier3_payload["att_tier"], json!(3));
        assert_eq!(
            tier3_payload["launch_measurements"]["layers"]["workload"]["vtpm_pcr_0"],
            json!("abababababababababababababababababababababababababababababababababababababababababababababababab")
        );

        let mut tier4_args = tier3_args;
        tier4_args.att_tier = 4;
        let err = admin_register_enclave_payload(&tier4_args)
            .expect_err("Tier 4 is provider KYB, not enclave hardware");
        assert!(
            err.to_string().contains("Tier 4 is provider KYB"),
            "{err:#}"
        );

        let mut fake_repo = tier4_args;
        fake_repo.att_tier = 1;
        fake_repo.artifact_repo = "provider/fake-model".to_owned();
        let err = admin_register_enclave_payload(&fake_repo)
            .expect_err("fake provider model must not be greenlit");
        assert!(err.to_string().contains("not greenlit"), "{err:#}");

        let _ = fs::remove_dir_all(temp);
    }

    #[test]
    fn admin_register_enclave_rejects_tool_caps_for_non_tool_backends() {
        let mut caps = json!({ "tools": true, "json": true, "ctx": 8192 });
        let err = enforce_backend_caps("mlx", &mut caps)
            .expect_err("MLX must not advertise fake tool calls");
        assert!(err.to_string().contains("caps.tools=true"), "{err:#}");

        let mut caps = json!({ "json": true, "ctx": 8192 });
        enforce_backend_caps("trt-llm", &mut caps).unwrap();
        assert_eq!(caps["tools"], json!(false));

        let mut caps = json!({ "tools": true, "json": true, "ctx": 8192 });
        enforce_backend_caps("llama.cpp", &mut caps).unwrap();
        assert_eq!(caps["tools"], json!(true));
    }

