    #[test]
    fn admin_epoch_payloads_accept_recomputed_outputs() {
        let roots = json!({
            "dep": "d".repeat(64),
            "use": "u".repeat(64),
            "earn": "e".repeat(64),
            "fee": "f".repeat(64),
        });
        let totals = json!({
            "dep_count": 0,
            "dep_au": "0",
            "use_count": 1,
            "use_au": "2000",
            "provider_count": 1,
            "earn_au": "1700",
            "fee_au": "300",
            "fee_cum_au": "300",
        });

        let commit = admin_epoch_commit_payload(&AdminEpochCommitArgs {
            tx: test_admin_tx_args(),
            epoch: Some(7),
            at: 25_200,
            recomputed_file: None,
            roots_json: Some(roots.to_string()),
            roots_file: None,
            totals_json: Some(totals.to_string()),
            totals_file: None,
        })
        .unwrap();
        assert_eq!(
            commit,
            json!({
                "op": "epoch_commit",
                "epoch": 7,
                "at": 25_200,
                "roots": roots,
                "totals": totals,
            })
        );

        let apply = admin_epoch_apply_payload(&AdminEpochApplyArgs {
            tx: test_admin_tx_args(),
            epoch: Some(7),
            at: 25_200,
            page: None,
            last_page: false,
            recomputed_file: None,
            debits_json: Some(r#"[{"user":"user-a","au": "2000"}]"#.to_owned()),
            debits_file: None,
            earnings_json: Some(r#"[{"provider":"provider-a","gross_au": "2000"}]"#.to_owned()),
            earnings_file: None,
            market_usage_json: Some(
                r#"[{"enclave_id":"enclave-a","demand_au": "2000","session_count":1,"provider_count":1}]"#
                    .to_owned(),
            ),
            market_usage_file: None,
            roots_json: Some(commit["roots"].to_string()),
            roots_file: None,
            totals_json: Some(commit["totals"].to_string()),
            totals_file: None,
        })
        .unwrap();
        assert_eq!(
            apply,
            json!({
                "op": "epoch_apply",
                "epoch": 7,
                "at": 25_200,
                "debits": [{"user": "user-a", "au": "2000"}],
                "earnings": [{"provider": "provider-a", "gross_au": "2000"}],
                "market_usage": [{"enclave_id": "enclave-a", "demand_au": "2000", "session_count": 1, "provider_count": 1}],
                "roots": commit["roots"],
                "totals": commit["totals"],
            })
        );
        let apply_key = epoch_apply_feature_key(&apply).unwrap();
        assert!(apply_key.starts_with("epoch/apply/7/"));
        assert_eq!(apply_key.len(), "epoch/apply/7/".len() + 64);
        assert_eq!(
            apply_key,
            epoch_apply_feature_key(&json!({
                "totals": commit["totals"],
                "roots": commit["roots"],
                "earnings": [{"gross_au": "2000", "provider": "provider-a"}],
                "debits": [{"au": "2000", "user": "user-a"}],
                "market_usage": [{"demand_au": "2000", "enclave_id": "enclave-a", "session_count": 1, "provider_count": 1}],
                "at": 25_200,
                "epoch": 7,
                "op": "epoch_apply",
            }))
            .unwrap()
        );
        let recomputed_market_usage = json!([{
            "enclave_id": "enclave-a",
            "demand_au": "2000",
            "session_count": 1,
            "provider_count": 1,
        }]);
        assert_eq!(
            recomputed_market_usage_for_apply(Some(&json!({
                "totals": { "price_count": 0 },
                "market_usage": recomputed_market_usage,
            }))),
            None
        );
        assert_eq!(
            recomputed_market_usage_for_apply(Some(&json!({
                "totals": { "price_count": 1 },
                "market_usage": recomputed_market_usage,
            }))),
            Some(recomputed_market_usage)
        );

        let paged_apply = admin_epoch_apply_payload(&AdminEpochApplyArgs {
            tx: test_admin_tx_args(),
            epoch: Some(8),
            at: 28_800,
            page: Some(0),
            last_page: false,
            recomputed_file: None,
            debits_json: Some(r#"[{"user":"user-a","au": "2000"}]"#.to_owned()),
            debits_file: None,
            earnings_json: Some(r#"[{"provider":"provider-a","gross_au": "2000"}]"#.to_owned()),
            earnings_file: None,
            market_usage_json: None,
            market_usage_file: None,
            roots_json: None,
            roots_file: None,
            totals_json: None,
            totals_file: None,
        })
        .unwrap();
        assert_eq!(
            paged_apply,
            json!({
                "op": "epoch_apply",
                "epoch": 8,
                "at": 28_800,
                "debits": [{"user": "user-a", "au": "2000"}],
                "earnings": [{"provider": "provider-a", "gross_au": "2000"}],
                "page": 0,
                "last_page": false,
            })
        );
    }

