    #[test]
    fn provider_lifecycle_intents_are_current_version_and_limited_to_opt_in_and_out_ops() {
        let provider = "11".repeat(32);
        let intent = json!({
            "op": "join_room",
            "provider": provider,
            "enclave_id": "enclave-a",
            "room_id": "room-a",
            "nonce": "22".repeat(32),
        });
        assert!(provider_lifecycle_intent_message(&intent).contains("\"signing_version\":2"));
        assert_eq!(
            provider_lifecycle_feature_key(&intent).unwrap(),
            format!(
                "intent/provider/{}/join_room/{}",
                provider,
                blake3::hash(provider_lifecycle_intent_message(&intent).as_bytes()).to_hex()
            )
        );

        let register = provider_lifecycle_intent(&provider, "register_provider", None, None)
            .expect("register intent");
        assert_eq!(register["op"], "register_provider");
        assert_eq!(register["provider"], provider);
        assert!(is_hex_len(register["nonce"].as_str().unwrap(), 64));

        let enclave =
            provider_lifecycle_intent(&provider, "leave_enclave", Some("enclave-a"), None)
                .expect("enclave intent");
        assert_eq!(
            enclave,
            json!({
                "op": "leave_enclave",
                "provider": provider,
                "enclave_id": "enclave-a",
                "nonce": enclave["nonce"].as_str().unwrap(),
            })
        );
        let join_terms = ProviderJoinContextTerms {
            served_ctx: 8192,
            ctx_bracket: Some(ctx_bracket_for_tokens(8192).to_owned()),
            ctx_bracket_table_ver: Some(CTX_BRACKET_TABLE_VERSION),
        };
        let join = provider_lifecycle_intent_with_anchors(
            &provider,
            "join_enclave",
            Some("enclave-a"),
            None,
            None,
            None,
            Some(&join_terms),
        )
        .expect("join intent");
        assert_eq!(join["served_ctx"], 8192);
        assert_eq!(join["ctx_bracket"], ctx_bracket_for_tokens(8192));
        assert_eq!(join["ctx_bracket_table_ver"], CTX_BRACKET_TABLE_VERSION);
    }

    #[test]
    fn provider_lifecycle_resolves_admin_enclave_and_rejects_ambiguous_model() {
        let root = "aa".repeat(32);
        let mut contract = test_contract(&root);
        let resolved =
            resolve_provider_lifecycle_enclave(&contract.enclaves, "test/model@4bit").unwrap();
        assert_eq!(resolved.enclave_id, "11".repeat(32));

        let unknown =
            resolve_provider_lifecycle_enclave(&contract.enclaves, "provider/custom@4bit")
                .unwrap_err();
        assert!(unknown
            .to_string()
            .contains("not an active admin-created enclave id or model lookup"));

        contract.enclaves.push(LedgerEnclave {
            enclave_id: "22".repeat(32),
            model_id: "test/model@4bit".to_owned(),
            model_class: DEFAULT_MODEL_CLASS.to_owned(),
            backend: "llama.cpp".to_owned(),
            artifact_root: root.clone(),
            artifact_root_kind: "blake3_merkle_v1".to_owned(),
            artifact_source: LedgerArtifactSource {
                kind: "huggingface".to_owned(),
                repo: "test/model".to_owned(),
                revision: "1".repeat(40),
                path: "model.gguf".to_owned(),
            },
            artifact_sidecars: BTreeMap::new(),
            source_sha256: None,
            manifest_hash: "cc".repeat(32),
            att_tier: 1,
            quant: "int4".to_owned(),
            binary_hash: "dd".repeat(32),
            launch_measurements: Value::Null,
            caps: json!({}),
            status: "active".to_owned(),
            created_by: "admin".to_owned(),
            created_by_role: Some("admin".to_owned()),
        });
        let err =
            resolve_provider_lifecycle_enclave(&contract.enclaves, "test/model@4bit").unwrap_err();
        assert!(err.to_string().contains("multiple active"));

        contract.enclaves[0].status = "retired".to_owned();
        let resolved =
            resolve_provider_lifecycle_enclave(&contract.enclaves, &"22".repeat(32)).unwrap();
        assert_eq!(resolved.enclave_id, "22".repeat(32));

        let mut missing_role = test_contract(&"aa".repeat(32));
        missing_role.enclaves[0].created_by_role = None;
        let missing_role_err =
            resolve_provider_lifecycle_enclave(&missing_role.enclaves, "test/model@4bit")
                .unwrap_err();
        assert!(missing_role_err
            .to_string()
            .contains("not an active admin-created enclave"));

        let mut provider_created = test_contract(&"aa".repeat(32));
        provider_created.enclaves[0].created_by_role = Some("provider".to_owned());
        let by_id = resolve_provider_lifecycle_enclave(
            &provider_created.enclaves,
            &provider_created.enclaves[0].enclave_id,
        )
        .unwrap_err();
        assert!(format!("{by_id:#}").contains("created_by_role"));
        let by_model =
            resolve_provider_lifecycle_enclave(&provider_created.enclaves, "test/model@4bit")
                .unwrap_err();
        assert!(by_model
            .to_string()
            .contains("not an active admin-created enclave"));
    }

    #[test]
    fn provider_leave_resolves_retired_enclave_from_provider_serves() {
        let root = "aa".repeat(32);
        let mut contract = test_contract(&root);
        let provider = "55".repeat(32);
        contract.enclaves[0].status = "retired".to_owned();
        let serves = vec![LedgerServe {
            provider: provider.clone(),
            enclave_id: contract.enclaves[0].enclave_id.clone(),
            model_id: contract.enclaves[0].model_id.clone(),
            status: "active".to_owned(),
            served_ctx: None,
            rooms: vec!["room-a".to_owned()],
        }];

        let resolved =
            resolve_provider_leave_enclave(&contract.enclaves, &serves, "test/model@4bit").unwrap();
        assert_eq!(resolved.enclave_id, "11".repeat(32));
        assert_eq!(resolved.status, "retired");

        let resolved =
            resolve_provider_leave_enclave(&contract.enclaves, &serves, &"11".repeat(32)).unwrap();
        assert_eq!(resolved.enclave_id, "11".repeat(32));

        contract.enclaves.push(LedgerEnclave {
            enclave_id: "22".repeat(32),
            model_id: "test/model@4bit".to_owned(),
            model_class: DEFAULT_MODEL_CLASS.to_owned(),
            backend: "llama.cpp".to_owned(),
            artifact_root: root.clone(),
            artifact_root_kind: "blake3_merkle_v1".to_owned(),
            artifact_source: LedgerArtifactSource {
                kind: "huggingface".to_owned(),
                repo: "test/model".to_owned(),
                revision: "1".repeat(40),
                path: "model.gguf".to_owned(),
            },
            artifact_sidecars: BTreeMap::new(),
            source_sha256: None,
            manifest_hash: "cc".repeat(32),
            att_tier: 1,
            quant: "int4".to_owned(),
            binary_hash: "dd".repeat(32),
            launch_measurements: Value::Null,
            caps: json!({}),
            status: "retired".to_owned(),
            created_by: "admin".to_owned(),
            created_by_role: Some("admin".to_owned()),
        });
        let mut ambiguous_serves = serves;
        ambiguous_serves.push(LedgerServe {
            provider,
            enclave_id: "22".repeat(32),
            model_id: "test/model@4bit".to_owned(),
            status: "active".to_owned(),
            served_ctx: None,
            rooms: vec![],
        });
        let err = resolve_provider_leave_enclave(
            &contract.enclaves,
            &ambiguous_serves,
            "test/model@4bit",
        )
        .unwrap_err();
        assert!(err.to_string().contains("multiple active provider"));
    }

    #[test]
    fn provider_lifecycle_requires_current_admin_price() {
        let root = "aa".repeat(32);
        let mut contract = test_contract(&root);
        assert!(require_current_au_usd_price(&contract.prices, &"11".repeat(32)).is_ok());

        contract.prices.clear();
        let err = require_current_au_usd_price(&contract.prices, &"11".repeat(32)).unwrap_err();
        assert!(err.to_string().contains("has no admin price"));

        let mut contract = test_contract(&root);
        contract.prices[0].current = None;
        let err = require_current_au_usd_price(&contract.prices, &"11".repeat(32)).unwrap_err();
        assert!(err
            .to_string()
            .contains("has no current au_usd admin price"));

        let mut contract = test_contract(&root);
        contract.prices[0].current.as_mut().unwrap().denom = "provider_points".to_owned();
        let err = require_current_au_usd_price(&contract.prices, &"11".repeat(32)).unwrap_err();
        assert!(err
            .to_string()
            .contains("has no current au_usd admin price"));
    }

    #[test]
    fn provider_rooms_to_leave_are_provider_and_enclave_scoped() {
        let rows = vec![
            LedgerRoomServe {
                room_id: "room-b".to_owned(),
                provider: "provider-a".to_owned(),
                enclave_id: "enclave-a".to_owned(),
                model_id: "model".to_owned(),
                status: "active".to_owned(),
            },
            LedgerRoomServe {
                room_id: "room-a".to_owned(),
                provider: "provider-a".to_owned(),
                enclave_id: "enclave-a".to_owned(),
                model_id: "model".to_owned(),
                status: "active".to_owned(),
            },
            LedgerRoomServe {
                room_id: "room-other".to_owned(),
                provider: "provider-b".to_owned(),
                enclave_id: "enclave-a".to_owned(),
                model_id: "model".to_owned(),
                status: "active".to_owned(),
            },
        ];

        assert_eq!(
            select_provider_rooms_to_leave(&rows, "provider-a", "enclave-a", "auto").unwrap(),
            vec!["room-a".to_owned(), "room-b".to_owned()]
        );
        assert_eq!(
            select_provider_rooms_to_leave(&rows, "provider-a", "enclave-a", "room-b").unwrap(),
            vec!["room-b".to_owned()]
        );
        assert!(
            select_provider_rooms_to_leave(&rows, "provider-a", "enclave-a", "room-other").is_err()
        );
    }

    #[test]
    fn provider_list_summary_matches_stop_plan_and_gateway_routes() {
        let root = "aa".repeat(32);
        let contract = test_contract(&root);
        let provider = "55".repeat(32);
        let summary = provider_list_summary(&contract, &provider);

        assert_eq!(summary["provider"].as_str(), Some(provider.as_str()));
        assert_eq!(summary["active_serves"].as_array().map(Vec::len), Some(1));
        assert_eq!(summary["active_rooms"].as_array().map(Vec::len), Some(1));
        assert_eq!(
            summary["stop_plan"]["enclaves"].as_array().map(Vec::len),
            Some(1)
        );
        assert_eq!(
            summary["stop_plan"]["rooms"].as_array().map(Vec::len),
            Some(1)
        );
        assert_eq!(
            summary["active_serves"][0]["enclave_id"].as_str(),
            Some("11".repeat(32).as_str())
        );
        assert_eq!(summary["active_serves"][0]["room_count"].as_u64(), Some(1));
        assert_eq!(
            summary["active_rooms"][0]["room_id"].as_str(),
            Some("aa".repeat(16).as_str())
        );

        let models = gateway_models_from_contract(&contract)
            .unwrap()
            .into_iter()
            .map(serde_json::to_value)
            .collect::<std::result::Result<Vec<_>, _>>()
            .unwrap();
        let routes = provider_gateway_route_summaries(&models, &provider);
        assert_eq!(routes.len(), 1);
        assert_eq!(routes[0]["provider"].as_str(), Some(provider.as_str()));
        assert_eq!(routes[0]["model_id"].as_str(), Some("test/model@4bit"));

        let inactive = provider_list_summary(&contract, &"66".repeat(32));
        assert_eq!(inactive["active_serves"].as_array().map(Vec::len), Some(0));
        assert_eq!(
            inactive["stop_plan"]["rooms"].as_array().map(Vec::len),
            Some(0)
        );
    }

    #[test]
    fn provider_heartbeat_cache_reports_live_and_stale() {
        let temp = test_temp_dir("mayhem-provider-heartbeat-cache");
        let provider = "55".repeat(32);
        let enclave = "11".repeat(32);
        let written = write_provider_heartbeat_cache(
            &temp,
            &provider,
            &enclave,
            &[json!({
                "t": "hb",
                "provider": &provider,
                "enclave_id": &enclave,
                "room_id": "aa".repeat(16),
            })],
        )
        .unwrap();
        assert_eq!(written["ok"].as_bool(), Some(true));

        let live = read_provider_heartbeat_cache(&temp, &provider);
        assert_eq!(live["ok"].as_bool(), Some(true));
        assert_eq!(live["live"].as_bool(), Some(true));
        assert_eq!(
            live["ttl_ms"].as_u64(),
            Some(DEFAULT_PROVIDER_HEARTBEAT_TTL_MILLIS)
        );

        let path = provider_heartbeat_cache_path(&temp, &provider);
        write_json_file(
            &path,
            &json!({
                "provider": &provider,
                "enclave_id": &enclave,
                "updated_at_ms": 1,
                "heartbeat_count": 1,
                "heartbeats": [],
            }),
        )
        .unwrap();
        let stale = read_provider_heartbeat_cache(&temp, &provider);
        assert_eq!(stale["live"].as_bool(), Some(false));

        let _ = fs::remove_dir_all(temp);
    }

    #[test]
    fn provider_lifecycle_cli_parses_join_leave_and_room_commands() {
        let join = Cli::try_parse_from([
            "mayhem",
            "provider",
            "join",
            "--enclave",
            "enclave-a",
            "--rooms",
            "room-a,room-b",
            "--sim",
            "--json",
        ])
        .unwrap();
        let Commands::Provider { verbose, command } = join.command else {
            panic!("expected provider command");
        };
        assert!(!verbose);
        let ProviderCommands::Join(args) = *command else {
            panic!("expected provider join command");
        };
        assert_eq!(args.enclave, "enclave-a");
        assert_eq!(args.rooms, "room-a,room-b");
        assert!(args.tx.sim);
        assert!(args.tx.json);

        let rooms = Cli::try_parse_from([
            "mayhem",
            "provider",
            "rooms",
            "leave",
            "--room",
            "room-a",
            "--enclave",
            "enclave-a",
        ])
        .unwrap();
        let Commands::Provider { command, .. } = rooms.command else {
            panic!("expected provider command");
        };
        let ProviderCommands::Rooms { command } = *command else {
            panic!("expected provider rooms command");
        };
        let ProviderRoomsCommands::Leave(args) = command else {
            panic!("expected provider rooms leave command");
        };
        assert_eq!(args.room, "room-a");
        assert_eq!(args.enclave, "enclave-a");

        let list =
            Cli::try_parse_from(["mayhem", "provider", "list", "--provider", "55", "--json"])
                .unwrap();
        let Commands::Provider { command, .. } = list.command else {
            panic!("expected provider command");
        };
        let ProviderCommands::List(args) = *command else {
            panic!("expected provider list command");
        };
        assert_eq!(args.read.provider.as_deref(), Some("55"));
        assert!(args.read.json);

        let health = Cli::try_parse_from([
            "mayhem",
            "provider",
            "health",
            "--provider",
            "55",
            "--gateway-url",
            "http://127.0.0.1:11435",
            "--timeout-seconds",
            "2",
        ])
        .unwrap();
        let Commands::Provider { command, .. } = health.command else {
            panic!("expected provider command");
        };
        let ProviderCommands::Health(args) = *command else {
            panic!("expected provider health command");
        };
        assert_eq!(args.read.provider.as_deref(), Some("55"));
        assert_eq!(
            args.read.gateway_url.as_deref(),
            Some("http://127.0.0.1:11435")
        );
        assert_eq!(args.timeout_seconds, 2);

        let rails = Cli::try_parse_from([
            "mayhem",
            "provider",
            "rails",
            "set",
            "--rails",
            "tnk,fiat,tap",
            "--submit",
            "--sim",
            "--json",
        ])
        .unwrap();
        let Commands::Provider { command, .. } = rails.command else {
            panic!("expected provider command");
        };
        let ProviderCommands::Rails { command } = *command else {
            panic!("expected provider rails command");
        };
        let ProviderRailsCommands::Set(args) = command else {
            panic!("expected provider rails set command");
        };
        assert_eq!(args.rails, "tnk,fiat,tap");
        assert!(args.tx.submit);
        assert!(args.tx.sim);
        assert!(args.tx.json);

        assert_eq!(
            normalize_provider_accepted_rails_arg("tnk,fiat,tap").unwrap(),
            vec!["fiat".to_owned(), "tap".to_owned(), "tnk".to_owned()]
        );
        assert!(normalize_provider_accepted_rails_arg("fiat,fiat").is_err());
        assert!(normalize_provider_accepted_rails_arg("unsupported").is_err());

        let serve_plan = Cli::try_parse_from([
            "mayhem",
            "provider",
            "serve",
            "plan",
            "--fixture",
            "linux-nvidia",
            "--ctx",
            "8192",
            "--json",
        ])
        .unwrap();
        let Commands::Provider { command, .. } = serve_plan.command else {
            panic!("expected provider command");
        };
        let ProviderCommands::Serve { command } = *command else {
            panic!("expected provider serve command");
        };
        let ProviderServeCommands::Plan(args) = command else {
            panic!("expected provider serve plan command");
        };
        assert_eq!(args.fixture.as_deref(), Some("linux-nvidia"));
        assert_eq!(args.ctx, Some(8192));
        assert!(args.json);

        let serve_add = Cli::try_parse_from([
            "mayhem",
            "provider",
            "serve",
            "add",
            "enclave-a",
            "--gpu-layers",
            "35",
            "--json",
        ])
        .unwrap();
        let Commands::Provider { command, .. } = serve_add.command else {
            panic!("expected provider command");
        };
        let ProviderCommands::Serve { command } = *command else {
            panic!("expected provider serve command");
        };
        let ProviderServeCommands::Add(args) = command else {
            panic!("expected provider serve add command");
        };
        assert_eq!(args.enclave, "enclave-a");
        assert_eq!(args.gpu_layers, Some(35));
        assert!(args.json);

        let serve_remove = Cli::try_parse_from([
            "mayhem",
            "provider",
            "serve",
            "remove",
            "enclave-a",
            "--json",
        ])
        .unwrap();
        let Commands::Provider { command, .. } = serve_remove.command else {
            panic!("expected provider command");
        };
        let ProviderCommands::Serve { command } = *command else {
            panic!("expected provider serve command");
        };
        let ProviderServeCommands::Remove(args) = command else {
            panic!("expected provider serve remove command");
        };
        assert_eq!(args.target, "enclave-a");
        assert!(args.json);

        assert!(Cli::try_parse_from(["mayhem", "pay", "unsupported"]).is_err());
    }

    #[test]
    fn provider_cli_parses_verbose_for_technical_errors() {
        let cli =
            Cli::try_parse_from(["mayhem", "provider", "--verbose", "start", "--sim"]).unwrap();
        let Commands::Provider { verbose, command } = cli.command else {
            panic!("expected provider command");
        };
        assert!(verbose);
        assert!(matches!(*command, ProviderCommands::Start(_)));

        let cli =
            Cli::try_parse_from(["mayhem", "provider", "start", "--verbose", "--sim"]).unwrap();
        let Commands::Provider { verbose, command } = cli.command else {
            panic!("expected provider command");
        };
        assert!(verbose);
        assert!(matches!(*command, ProviderCommands::Start(_)));
    }

    fn test_auto_fit_candidate(
        nibble: char,
        model_id: &str,
        modality: &str,
        required_gib: u64,
        budget_gib: u64,
        per_1k_au: MoneyAu,
        tok_s: f64,
    ) -> ProviderCandidate {
        let mut catalog = test_catalog(&"aa".repeat(32));
        let mut model = catalog.models.remove(0);
        model.model_id = model_id.to_owned();
        model.model_class = if modality == "text" {
            DEFAULT_MODEL_CLASS.to_owned()
        } else {
            modality.to_owned()
        };
        model.caps.output_modality = Some(modality.to_owned());
        model.caps.output_modalities = vec![modality.to_owned()];
        model.caps.image = modality == "image";
        model.caps.audio = matches!(modality, "audio" | "stt" | "tts");
        model.adapter.modality_set = vec![modality.to_owned()];
        let artifact_name = "gguf-q4_k_m".to_owned();
        let artifact = model.artifacts[&artifact_name].clone();
        let enclave_id = nibble.to_string().repeat(64);
        ProviderCandidate {
            enclave: LedgerEnclave {
                enclave_id: enclave_id.clone(),
                model_id: model_id.to_owned(),
                model_class: model.model_class.clone(),
                backend: "llama.cpp".to_owned(),
                artifact_root: artifact.artifact_root.clone(),
                artifact_root_kind: artifact.artifact_root_kind.clone(),
                artifact_source: LedgerArtifactSource {
                    kind: artifact.source.kind.clone(),
                    repo: artifact.source.repo.clone(),
                    revision: artifact.source.revision.clone(),
                    path: artifact.path.clone(),
                },
                artifact_sidecars: BTreeMap::new(),
                source_sha256: artifact.source_sha256.clone(),
                manifest_hash: "22".repeat(32),
                att_tier: 1,
                quant: "int4".to_owned(),
                binary_hash: "33".repeat(32),
                launch_measurements: Value::Null,
                caps: json!({ "ctx": 8192 }),
                status: "active".to_owned(),
                created_by: "44".repeat(32),
                created_by_role: Some("admin".to_owned()),
            },
            model,
            artifact_name,
            artifact,
            verdict: BackendVerdict {
                backend: "llama.cpp".to_owned(),
                status: VerdictStatus::FullOffload,
                reason: None,
                est_tok_s: Some(tok_s),
                n_layers_gpu: None,
                max_sessions: 1,
                kv_cache_bytes_budget: 0,
            },
            price: Some(LedgerPriceSchedule {
                enclave_id,
                model_id: model_id.to_owned(),
                denom: "au_usd".to_owned(),
                ctx_bracket: Some(ctx_bracket_for_tokens(8192).to_owned()),
                ctx_bracket_table_ver: Some(CTX_BRACKET_TABLE_VERSION),
                current: Some(LedgerPriceRecord {
                    ver: 1,
                    denom: "au_usd".to_owned(),
                    ctx_bracket: Some(ctx_bracket_for_tokens(8192).to_owned()),
                    ctx_bracket_table_ver: Some(CTX_BRACKET_TABLE_VERSION),
                    rate_map: vec![RateMapEntry {
                        unit: "output_token".to_owned(),
                        per_unit_au: per_1k_au,
                        granularity: 1000,
                    }],
                    per_req_au: 0,
                    min_session_au: 0,
                    effective_at: 0,
                    set_by_role: Some("admin".to_owned()),
                    derivation: None,
                }),
                pending: None,
            }),
            served_ctx: 8192,
            feasibility: ProviderCtxFeasibility {
                requested_ctx: 8192,
                served_ctx: 8192,
                catalog_ctx_max: 8192,
                fallback_applied: false,
                message: None,
                estimated_required_bytes: required_gib * GIB_BYTES,
                estimated_weights_bytes: required_gib * GIB_BYTES,
                estimated_kv_bytes: 0,
                estimated_overhead_bytes: 0,
                memory_budget: ProviderMemoryBudget {
                    pool: "dedicated_vram".to_owned(),
                    source: "test".to_owned(),
                    unified: false,
                    total_bytes: (budget_gib + 1) * GIB_BYTES,
                    available_bytes: (budget_gib + 1) * GIB_BYTES,
                    reserve_bytes: GIB_BYTES,
                    claimed_bytes: 0,
                    budget_bytes: budget_gib * GIB_BYTES,
                },
            },
            ctx_bracket_schedule: default_ctx_bracket_schedule(),
        }
    }

    #[test]
    fn provider_auto_fit_selects_price_weighted_multimodality_set() {
        let heavy =
            test_auto_fit_candidate('1', "expensive/chat-heavy", "text", 23, 24, 10_000, 80.0);
        let chat = test_auto_fit_candidate('2', "launch/chat-small", "text", 8, 24, 4_000, 80.0);
        let embedding =
            test_auto_fit_candidate('3', "launch/embed-small", "embedding", 2, 24, 60_000, 20.0);
        let stt = test_auto_fit_candidate('4', "launch/stt-small", "stt", 2, 24, 50_000, 10.0);

        let selection = select_provider_auto_fit_set(&[heavy, chat, embedding, stt]).unwrap();
        let models = selection
            .candidates
            .iter()
            .map(|candidate| candidate.enclave.model_id.as_str())
            .collect::<BTreeSet<_>>();
        assert_eq!(
            models,
            BTreeSet::from([
                "launch/chat-small",
                "launch/embed-small",
                "launch/stt-small"
            ])
        );
        assert_eq!(selection.total_required_bytes, 12 * GIB_BYTES);
        assert_eq!(selection.total_budget_bytes, 24 * GIB_BYTES);
        assert_eq!(
            selection.modalities,
            vec!["embedding".to_owned(), "stt".to_owned(), "text".to_owned()]
        );
        assert!(selection.rationale.contains("best current earnings mix"));
    }

    #[test]
    fn provider_auto_fit_never_selects_set_over_shared_budget() {
        let a = test_auto_fit_candidate('5', "launch/a", "text", 15, 24, 100_000, 40.0);
        let b = test_auto_fit_candidate('6', "launch/b", "embedding", 15, 24, 100_000, 40.0);
        let c = test_auto_fit_candidate('7', "launch/c", "stt", 15, 24, 100_000, 40.0);

        let selection = select_provider_auto_fit_set(&[a, b, c]).unwrap();
        assert_eq!(selection.candidates.len(), 1);
        assert!(selection.total_required_bytes <= selection.total_budget_bytes);

        let too_large =
            test_auto_fit_candidate('8', "launch/too-large", "text", 25, 24, 100_000, 40.0);
        let err = select_provider_auto_fit_set(&[too_large]).unwrap_err();
        assert!(err.to_string().contains("no auto-fit candidate set fits"));
    }

    #[test]
    fn provider_explicit_set_uses_one_shared_budget() {
        let chat = test_auto_fit_candidate('9', "launch/chat", "text", 8, 24, 4_000, 80.0);
        let embedding =
            test_auto_fit_candidate('a', "launch/embed", "embedding", 2, 24, 60_000, 20.0);
        let stt = test_auto_fit_candidate('b', "launch/stt", "stt", 2, 24, 50_000, 10.0);
        let candidates = vec![chat, embedding, stt];
        let requested = vec![
            "launch/chat".to_owned(),
            "launch/embed".to_owned(),
            "launch/stt".to_owned(),
        ];

        let selection = select_provider_explicit_set(&candidates, &requested).unwrap();
        assert_eq!(selection.candidates.len(), 3);
        assert_eq!(selection.total_required_bytes, 12 * GIB_BYTES);
        assert_eq!(selection.total_budget_bytes, 24 * GIB_BYTES);
        assert!(selection.rationale.contains("one OS reserve"));
    }

    #[test]
    fn provider_explicit_set_refuses_over_shared_budget() {
        let a = test_auto_fit_candidate('c', "launch/huge-a", "text", 15, 24, 100_000, 40.0);
        let b = test_auto_fit_candidate('d', "launch/huge-b", "embedding", 15, 24, 100_000, 40.0);
        let candidates = vec![a, b];
        let requested = vec!["launch/huge-a".to_owned(), "launch/huge-b".to_owned()];

        let err = select_provider_explicit_set(&candidates, &requested).unwrap_err();
        assert!(err
            .to_string()
            .contains("does not fit the shared memory budget"));
    }

    #[test]
    fn provider_friendly_error_hides_raw_backend_failures_by_default() {
        let cases = [
            (
                "loading vLLM provider session engine: could not import vLLM API: Traceback ... OutOfMemoryError: CUDA out of memory. Tried to allocate 12.50 GiB",
                "Not enough memory",
            ),
            (
                "download failed from HuggingFace: HTTP status 503 while fetching model.safetensors",
                "could not download",
            ),
            (
                "artifact hash does not match admin artifact_root sha256 mismatch",
                "does not match the admin-signed enclave",
            ),
            (
                "binding provider gateway failed: address already in use",
                "port is already in use",
            ),
            (
                "TensorRT-LLM requires a compatible NVIDIA GPU",
                "cannot serve the selected enclave/backend",
            ),
            (
                "connecting to SC-Bridge for provider heartbeats: connection refused",
                "could not reach the local peer or bridge",
            ),
        ];
        for (raw, expected) in cases {
            let err = anyhow::anyhow!(raw);
            let friendly = provider_friendly_error(&err);
            assert!(
                friendly.contains(expected),
                "expected {expected:?} in {friendly:?}"
            );
            for leaked in [
                "Traceback",
                "CUDA out of memory",
                "OutOfMemoryError",
                "safetensors",
            ] {
                assert!(
                    !friendly.contains(leaked),
                    "friendly error leaked raw detail {leaked:?}: {friendly}"
                );
            }
            assert!(friendly.contains("--verbose"));
        }
    }

