    #[test]
    fn provider_session_open_enforces_admin_terms() {
        let terms = test_provider_session_terms();
        let frame = test_session_open_frame(&terms);
        assert!(provider_session_open_targets_enclave(&frame, &terms));
        assert_eq!(
            provider_session_open_decision(&frame, &terms),
            ProviderSessionDecision::Accept
        );
        let mut missing_at = frame.clone();
        missing_at.as_object_mut().unwrap().remove("at");
        assert!(matches!(
            provider_session_open_decision(&missing_at, &terms),
            ProviderSessionDecision::Reject { code: "SCHEMA", .. }
        ));
        let mut priced_out_terms = terms.clone();
        priced_out_terms.min_ask_au = 1001;
        assert!(matches!(
            provider_session_open_decision(&frame, &priced_out_terms),
            ProviderSessionDecision::Reject {
                code: "PRICE_FLOOR",
                ..
            }
        ));
        let mut outdated_open = frame.clone();
        outdated_open
            .as_object_mut()
            .expect("s.open object")
            .remove("contract_version");
        outdated_open["voucher"]["user_sig"] = json!("11".repeat(64));
        outdated_open["sig"] = json!("11".repeat(64));
        match provider_session_open_decision(&outdated_open, &terms) {
            ProviderSessionDecision::Reject { code, reason } => {
                assert_eq!(code, "UPGRADE_REQUIRED");
                assert!(reason.contains("contract upgrade required"));
                assert!(reason.contains("missing/outdated"));
            }
            other => panic!("outdated contract version should reject before signatures: {other:?}"),
        }

        let mut future_open = frame.clone();
        future_open["contract_version"] = json!(terms.contract_version + 1);
        match provider_session_open_decision(&future_open, &terms) {
            ProviderSessionDecision::Reject { code, reason } => {
                assert_eq!(code, "UPGRADE_REQUIRED");
                assert!(reason.contains("contract upgrade required"));
                assert!(reason.contains(&(terms.contract_version + 1).to_string()));
            }
            other => panic!("future contract version should reject before signatures: {other:?}"),
        }

        let mut wrong_enclave = frame.clone();
        wrong_enclave["enclave_id"] = json!("22".repeat(32));
        assert!(!provider_session_open_targets_enclave(
            &wrong_enclave,
            &terms
        ));
        assert!(matches!(
            provider_session_open_decision(&wrong_enclave, &terms),
            ProviderSessionDecision::Reject {
                code: "ENCLAVE",
                ..
            }
        ));

        let mut wrong_price = frame.clone();
        wrong_price["price_ver"] = json!(terms.price_ver + 1);
        assert!(matches!(
            provider_session_open_decision(&wrong_price, &terms),
            ProviderSessionDecision::Reject {
                code: "PRICE_VER",
                ..
            }
        ));

        let mut stale_rules = frame.clone();
        stale_rules["rules_ver"] = json!(terms.rules_ver + 1);
        assert!(matches!(
            provider_session_open_decision(&stale_rules, &terms),
            ProviderSessionDecision::Reject {
                code: "CONSENT",
                ..
            }
        ));

        let mut bad_att_nonce = frame.clone();
        bad_att_nonce["att_nonce"] = json!("not-hex");
        assert!(matches!(
            provider_session_open_decision(&bad_att_nonce, &terms),
            ProviderSessionDecision::Reject {
                code: "ATTESTATION",
                ..
            }
        ));

        let mut bad_user = frame.clone();
        bad_user["user"] = json!("not-hex");
        assert!(matches!(
            provider_session_open_decision(&bad_user, &terms),
            ProviderSessionDecision::Reject { code: "USER", .. }
        ));

        let mut missing_rail = frame.clone();
        missing_rail.as_object_mut().unwrap().remove("rail");
        assert!(matches!(
            provider_session_open_decision(&missing_rail, &terms),
            ProviderSessionDecision::Reject { code: "RAIL", .. }
        ));

        let mut bad_rail = frame.clone();
        bad_rail["rail"] = json!("unsupported");
        assert!(matches!(
            provider_session_open_decision(&bad_rail, &terms),
            ProviderSessionDecision::Reject { code: "RAIL", .. }
        ));

        let mut rail_mismatch = frame.clone();
        rail_mismatch["voucher"]["rail"] = json!("tap");
        assert!(matches!(
            provider_session_open_decision(&rail_mismatch, &terms),
            ProviderSessionDecision::Reject {
                code: "VOUCHER",
                ..
            }
        ));

        let mut bad_voucher = frame;
        bad_voucher["voucher"]["price_ver"] = json!(terms.price_ver + 1);
        assert!(matches!(
            provider_session_open_decision(&bad_voucher, &terms),
            ProviderSessionDecision::Reject {
                code: "VOUCHER",
                ..
            }
        ));

        let frame = test_session_open_frame(&terms);
        let mut bad_voucher_sig = frame.clone();
        bad_voucher_sig["voucher"]["user_sig"] = json!("11".repeat(64));
        bad_voucher_sig["sig"] = json!("11".repeat(64));
        assert!(matches!(
            provider_session_open_decision(&bad_voucher_sig, &terms),
            ProviderSessionDecision::Reject {
                code: "SIGNATURE",
                ..
            }
        ));

        let mut mismatched_open_sig = frame;
        mismatched_open_sig["sig"] = json!("11".repeat(64));
        assert!(matches!(
            provider_session_open_decision(&mismatched_open_sig, &terms),
            ProviderSessionDecision::Reject {
                code: "SIGNATURE",
                ..
            }
        ));
    }

    #[test]
    fn provider_session_open_uses_admin_ctx_bracket_schedule() {
        let mut terms = test_provider_session_terms();
        terms.ctx = 12_000;
        terms.ctx_bracket = Some("le16k".to_owned());
        terms.ctx_bracket_table_ver = Some(2);
        terms.ctx_bracket_schedule = CtxBracketSchedule {
            current: mayhem_proto::CtxBracketTableRecord {
                ver: 2,
                submitted_at: 1,
                effective_at: 1,
                brackets: vec![
                    mayhem_proto::CtxBracketEntry {
                        id: "le16k".to_owned(),
                        max_ctx: Some(16_384),
                    },
                    mayhem_proto::CtxBracketEntry {
                        id: "gt16k".to_owned(),
                        max_ctx: None,
                    },
                ],
            },
            pending: None,
        };
        let frame = test_session_open_frame(&terms);
        assert_eq!(
            provider_session_open_decision(&frame, &terms),
            ProviderSessionDecision::Accept
        );

        let mut stale_table = frame.clone();
        stale_table["ctx_bracket"] = json!("le32k");
        stale_table["voucher"]["ctx_bracket"] = json!("le32k");
        let mut stale_terms = terms.clone();
        stale_terms.ctx_bracket = Some("le32k".to_owned());
        match provider_session_open_decision(&stale_table, &stale_terms) {
            ProviderSessionDecision::Reject { code, reason } => {
                assert_eq!(code, "VOUCHER");
                assert!(reason.contains("active admin context table"));
            }
            other => panic!("stale context table should reject: {other:?}"),
        }
    }

    #[test]
    fn provider_session_open_accepts_unbracketed_non_text_terms() {
        let mut terms = test_provider_session_terms();
        terms.ctx_bracket = None;
        terms.ctx_bracket_table_ver = None;
        terms.rate_map = vec![RateMapEntry {
            unit: "input_token".to_owned(),
            per_unit_au: 2,
            granularity: 1000,
        }];
        let frame = test_session_open_frame(&terms);
        assert!(frame["ctx_bracket"].is_null());
        assert!(frame["ctx_bracket_table_ver"].is_null());
        assert!(frame["voucher"]["ctx_bracket"].is_null());
        assert!(frame["voucher"]["ctx_bracket_table_ver"].is_null());
        assert_eq!(
            provider_session_open_decision(&frame, &terms),
            ProviderSessionDecision::Accept
        );

        let mut bracketed = frame;
        bracketed["ctx_bracket"] = json!("le8k");
        bracketed["ctx_bracket_table_ver"] = json!(CTX_BRACKET_TABLE_VERSION);
        bracketed["voucher"]["ctx_bracket"] = json!("le8k");
        bracketed["voucher"]["ctx_bracket_table_ver"] = json!(CTX_BRACKET_TABLE_VERSION);
        match provider_session_open_decision(&bracketed, &terms) {
            ProviderSessionDecision::Reject { code, reason } => {
                assert_eq!(code, "VOUCHER");
                assert!(reason.contains("provider price context"));
            }
            other => panic!("bracketed non-text session should reject: {other:?}"),
        }
    }

    #[test]
    fn provider_session_spend_reservation_feature_is_contract_shaped() {
        let terms = test_provider_session_terms();
        let frame = test_session_open_frame(&terms);
        let value =
            provider_session_spend_reservation_value(&terms, &frame, "fiat", 7, 25_200).unwrap();

        assert_eq!(value["op"], "spend_reserve");
        assert_eq!(value["contract_version"], CONTRACT_VERSION);
        assert_eq!(value["epoch"], 7);
        assert_eq!(value["at"], 25_200);
        assert_eq!(value["provider"], terms.provider);
        assert_eq!(value["enclave_id"], terms.enclave_id);
        assert_eq!(value["price_ver"], terms.price_ver);
        assert_eq!(value["rules_ver"], terms.rules_ver);
        assert_eq!(value["max_spend_au"], "1000");
        assert_eq!(value["provider_sig"], "");

        let message = spend_reservation_message(&value);
        assert!(message.starts_with("mayhem-spend-reservation-v1"));
        assert!(message.contains("\"max_spend_au\":\"1000\""));
        assert!(!message.contains("provider_sig"));

        let key = spend_reservation_feature_key(&value).unwrap();
        assert!(key.starts_with(&format!(
            "hold/reserve/fiat/{}/7/{}/",
            value["user"].as_str().unwrap(),
            value["session_id"].as_str().unwrap()
        )));
        assert_eq!(key.split('/').last().unwrap().len(), 64);

        let mut signed = value.clone();
        signed["provider_sig"] = json!("11".repeat(64));
        assert_eq!(
            spend_reservation_feature_key(&signed).unwrap(),
            key,
            "provider signature is not part of the reservation feature key"
        );
    }

    #[test]
    fn provider_session_open_rechecks_current_admin_contract_state() {
        let terms = test_provider_session_terms();
        let contract = test_contract(&"aa".repeat(32));
        let startup_rooms = contract.rooms[..1].to_vec();

        assert_eq!(
            provider_session_contract_decision(&contract, &terms, &startup_rooms, "fiat"),
            ProviderSessionDecision::Accept
        );

        let mut missing_role = contract.clone();
        missing_role.enclaves[0].created_by_role = None;
        missing_role.rooms[0].creator_role = None;
        missing_role.prices[0].current.as_mut().unwrap().set_by_role = None;
        let mut missing_role_startup_rooms = startup_rooms.clone();
        missing_role_startup_rooms[0].creator_role = None;
        assert!(matches!(
            provider_session_contract_decision(
                &missing_role,
                &terms,
                &missing_role_startup_rooms,
                "fiat"
            ),
            ProviderSessionDecision::Reject { .. }
        ));

        let mut banned = contract.clone();
        banned.providers[0].status = "banned".to_owned();
        assert!(matches!(
            provider_session_contract_decision(&banned, &terms, &startup_rooms, "fiat"),
            ProviderSessionDecision::Reject { code: "BANNED", .. }
        ));

        let mut rail_rejected = contract.clone();
        rail_rejected.providers[0].accepted_rails = vec!["tnk".to_owned()];
        assert!(matches!(
            provider_session_contract_decision(&rail_rejected, &terms, &startup_rooms, "fiat"),
            ProviderSessionDecision::Reject { code: "RAIL", .. }
        ));

        let mut retired = contract.clone();
        retired.enclaves[0].status = "retired".to_owned();
        assert!(matches!(
            provider_session_contract_decision(&retired, &terms, &startup_rooms, "fiat"),
            ProviderSessionDecision::Reject {
                code: "ENCLAVE",
                ..
            }
        ));

        let mut provider_created_enclave = contract.clone();
        provider_created_enclave.enclaves[0].created_by_role = Some("provider".to_owned());
        assert!(matches!(
            provider_session_contract_decision(
                &provider_created_enclave,
                &terms,
                &startup_rooms,
                "fiat"
            ),
            ProviderSessionDecision::Reject {
                code: "ENCLAVE",
                ..
            }
        ));

        let mut stale_rules = contract.clone();
        stale_rules.rules.as_mut().unwrap().ver = terms.rules_ver + 1;
        assert!(matches!(
            provider_session_contract_decision(&stale_rules, &terms, &startup_rooms, "fiat"),
            ProviderSessionDecision::Reject {
                code: "CONSENT",
                ..
            }
        ));

        let mut stale_price = contract.clone();
        stale_price.prices[0].current.as_mut().unwrap().ver = terms.price_ver + 1;
        assert_eq!(
            provider_session_contract_decision(&stale_price, &terms, &startup_rooms, "fiat"),
            ProviderSessionDecision::Accept
        );

        let mut provider_priced = contract.clone();
        provider_priced.prices[0]
            .current
            .as_mut()
            .unwrap()
            .set_by_role = Some("provider".to_owned());
        assert!(matches!(
            provider_session_contract_decision(&provider_priced, &terms, &startup_rooms, "fiat"),
            ProviderSessionDecision::Reject {
                code: "PRICE_VER",
                ..
            }
        ));

        let mut provider_created_room = contract.clone();
        provider_created_room.rooms[0].creator_role = Some("provider".to_owned());
        assert!(matches!(
            provider_session_contract_decision(
                &provider_created_room,
                &terms,
                &startup_rooms,
                "fiat"
            ),
            ProviderSessionDecision::Reject { code: "ROOM", .. }
        ));

        let mut provider_startup_room = startup_rooms.clone();
        provider_startup_room[0].creator_role = Some("provider".to_owned());
        assert!(matches!(
            provider_session_contract_decision(&contract, &terms, &provider_startup_room, "fiat"),
            ProviderSessionDecision::Reject { code: "ROOM", .. }
        ));

        let mut wrong_live_sidechannel = contract.clone();
        wrong_live_sidechannel.rooms[0].sidechannel = "mx/room/provider-made".to_owned();
        assert!(matches!(
            provider_session_contract_decision(
                &wrong_live_sidechannel,
                &terms,
                &startup_rooms,
                "fiat"
            ),
            ProviderSessionDecision::Reject { code: "ROOM", .. }
        ));

        let mut wrong_startup_sidechannel = startup_rooms.clone();
        wrong_startup_sidechannel[0].sidechannel = "mx/room/provider-made".to_owned();
        assert!(matches!(
            provider_session_contract_decision(
                &contract,
                &terms,
                &wrong_startup_sidechannel,
                "fiat"
            ),
            ProviderSessionDecision::Reject { code: "ROOM", .. }
        ));

        let mut tombstoned_roomserve = contract.clone();
        tombstoned_roomserve.roomserve[0].status = "inactive".to_owned();
        assert!(matches!(
            provider_session_contract_decision(
                &tombstoned_roomserve,
                &terms,
                &startup_rooms,
                "fiat"
            ),
            ProviderSessionDecision::Reject { code: "ROOM", .. }
        ));

        let mut tombstoned_serve = contract.clone();
        tombstoned_serve.serves[0].status = "inactive".to_owned();
        assert!(matches!(
            provider_session_contract_decision(&tombstoned_serve, &terms, &startup_rooms, "fiat"),
            ProviderSessionDecision::Reject { code: "SERVE", .. }
        ));
    }

    #[test]
    fn provider_session_accept_signing_payload_is_bound_and_sig_excluded() {
        let mut frame = json!({
            "t": "s.accept",
            "v": 1,
            "session_id": "aa".repeat(32),
            "open_head": "bb".repeat(32),
            "att_nonce": "88".repeat(32),
            "att_report": {
                "enclave_id": "11".repeat(32),
                "provider_pubkey": "55".repeat(32),
                "sig_provider": "66".repeat(64),
            },
            "engine": { "ctx": 8192 },
            "ts": 123,
            "nonce": "77".repeat(32),
        });
        let payload = session_accept_signing_bytes(&frame).unwrap();

        frame["sig"] = json!("88".repeat(64));
        assert_eq!(session_accept_signing_bytes(&frame).unwrap(), payload);

        frame["session_id"] = json!("bb".repeat(32));
        assert_ne!(session_accept_signing_bytes(&frame).unwrap(), payload);
    }

    #[test]
    fn provider_session_attestation_draft_binds_open_nonce() {
        let terms = test_provider_session_terms();
        let frame = test_session_open_frame(&terms);
        let att_nonce = frame.get("att_nonce").and_then(Value::as_str).unwrap();
        let binary_path = std::env::current_exe().unwrap();
        let identity = CatalogEnclaveIdentity {
            admin_pubkey: "44".repeat(32),
            model_id: terms.model_id.clone(),
            artifact_root: "aa".repeat(32),
            artifact_sidecar_roots: BTreeMap::new(),
            manifest_hash: "bb".repeat(32),
            binary_hash: measure_binary(&binary_path).unwrap(),
        };
        let runtime_keypair = RuntimeKeypair::from_seed([9; 32]);
        let runtime_config = AttestationRuntimeConfig {
            model_class: DEFAULT_MODEL_CLASS.to_owned(),
            backend: "trt-llm".to_owned(),
            ctx: 8192,
            tp_degree: 2,
            max_batch_size: Some(4),
            max_num_tokens: Some(4096),
        };
        let draft = prepare_provider_session_attestation(ProviderSessionAttestationInput {
            identity: &identity,
            runtime_keypair: &runtime_keypair,
            provider_pubkey: &terms.provider,
            binary_path: &binary_path,
            boot_epoch: 100,
            report_ts: 101,
            att_nonce,
            runtime_config: runtime_config.clone(),
        })
        .unwrap();

        assert_eq!(draft.body.nonce_u, att_nonce);
        assert_eq!(draft.body.provider_pubkey, terms.provider.as_str());
        assert_eq!(draft.body.runtime_config, runtime_config);

        let other_nonce = "99".repeat(32);
        let other_draft = prepare_provider_session_attestation(ProviderSessionAttestationInput {
            identity: &identity,
            runtime_keypair: &runtime_keypair,
            provider_pubkey: &terms.provider,
            binary_path: &binary_path,
            boot_epoch: 100,
            report_ts: 101,
            att_nonce: &other_nonce,
            runtime_config,
        })
        .unwrap();
        assert_eq!(other_draft.body.nonce_u, other_nonce);
        assert_ne!(draft.sig_enclave, other_draft.sig_enclave);
        assert_ne!(
            draft.provider_signing_message_hex,
            other_draft.provider_signing_message_hex
        );
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn provider_boot_hardware_attestation_is_fresh_per_boot() {
        use std::os::unix::fs::PermissionsExt;

        let temp = test_temp_dir("mayhem-provider-boot-attestation");
        let quote_command = temp.join("quote.sh");
        fs::write(
            &quote_command,
            r#"#!/bin/sh
printf '{"kind":"nvidia_nvtrust_offline_jwt","evidence":"boot:%s:%s","platform_id":"azure-ncc"}\n' "$MAYHEM_ATTESTATION_NONCE_U" "$MAYHEM_HW_QUOTE_BINDING"
"#,
        )
        .unwrap();
        fs::set_permissions(&quote_command, fs::Permissions::from_mode(0o755)).unwrap();

        let binary_path = std::env::current_exe().unwrap();
        let identity = CatalogEnclaveIdentity {
            admin_pubkey: "44".repeat(32),
            model_id: "test/model@tier3".to_owned(),
            artifact_root: "aa".repeat(32),
            artifact_sidecar_roots: BTreeMap::new(),
            manifest_hash: "bb".repeat(32),
            binary_hash: measure_binary(&binary_path).unwrap(),
        };
        let runtime_keypair = RuntimeKeypair::from_seed([9; 32]);
        let config = ProviderHardwareQuoteConfig {
            kind: HardwareQuoteKind::NvidiaNvtrustOfflineJwt,
            command: quote_command.clone(),
            timeout: Duration::from_secs(5),
        };
        let provider_pubkey = "55".repeat(32);
        let runtime_config = AttestationRuntimeConfig {
            model_class: DEFAULT_MODEL_CLASS.to_owned(),
            backend: "vllm".to_owned(),
            ctx: 8192,
            tp_degree: 1,
            max_batch_size: None,
            max_num_tokens: None,
        };

        let first = provider_attestation_report(
            Some(&config),
            identity.clone(),
            &runtime_keypair,
            &provider_pubkey,
            Some([7; 32]),
            &quote_command,
            "",
            &binary_path,
            100,
            101,
            "88".repeat(32),
            runtime_config.clone(),
        )
        .await
        .unwrap();
        let second = provider_attestation_report(
            Some(&config),
            identity,
            &runtime_keypair,
            &provider_pubkey,
            Some([7; 32]),
            &quote_command,
            "",
            &binary_path,
            200,
            201,
            "99".repeat(32),
            runtime_config,
        )
        .await
        .unwrap();

        assert_eq!(first.report.boot_epoch, 100);
        assert_eq!(second.report.boot_epoch, 200);
        assert_ne!(first.report_head, second.report_head);
        let first_quote = first.report.hw_quote.as_ref().unwrap();
        let second_quote = second.report.hw_quote.as_ref().unwrap();
        assert!(first_quote.evidence.contains(&"88".repeat(32)));
        assert!(second_quote.evidence.contains(&"99".repeat(32)));
        assert_ne!(first_quote.binding, second_quote.binding);

        let _ = fs::remove_dir_all(temp);
    }

    #[test]
    fn provider_session_receipt_binds_admin_terms_usage_and_runtime_key() {
        let terms = test_provider_session_terms();
        let active = ActiveProviderSession {
            remote: "peer-a".to_owned(),
            user_pubkey: "66".repeat(32),
            session_id: "aa".repeat(32),
            rail: "fiat".to_owned(),
            price_ver: terms.price_ver,
            locked_rate_map: normalize_rate_map(terms.rate_map.clone()),
            locked_per_req_au: terms.per_req_au,
            locked_min_session_au: terms.min_session_au,
            served_ctx: u32::try_from(terms.ctx).unwrap(),
            ctx_bracket: terms.ctx_bracket.clone(),
            ctx_bracket_table_ver: terms.ctx_bracket_table_ver,
            checkpoint_every: CheckpointPolicy { tokens: 1, ms: 0 },
        };
        let body = json!({
            "messages": [
                { "role": "system", "content": "be precise" },
                { "role": "user", "content": "hello mayhem" }
            ],
            "stream": true
        });
        let output = ProviderSessionOutput {
            content: "receipt ok".to_owned(),
            tool: None,
            embeddings: None,
            artifacts: Vec::new(),
            finish_reason: "stop".to_owned(),
            prompt_tokens: 3,
            completion_tokens: 4,
            token_ids: vec![1, 2, 3, 4],
            usage: ReceiptUsage::text(3, 4),
        };
        let runtime_keypair = RuntimeKeypair::from_seed([9; 32]);
        let receipt =
            provider_session_receipt(&terms, &active, &body, &output, &runtime_keypair).unwrap();

        assert_eq!(receipt.body.session_id, active.session_id);
        assert_eq!(receipt.body.rail, active.rail);
        assert_eq!(receipt.body.user, active.user_pubkey);
        assert_eq!(receipt.body.provider, terms.provider);
        assert_eq!(receipt.body.enclave_id, terms.enclave_id);
        assert_eq!(receipt.body.model_id, terms.model_id);
        assert_eq!(receipt.body.price_ver, active.price_ver);
        assert_eq!(receipt.body.locked_rate_map, active.locked_rate_map);
        assert_eq!(receipt.body.locked_per_req_au, active.locked_per_req_au);
        assert_eq!(
            receipt.body.locked_min_session_au,
            active.locked_min_session_au
        );
        assert_eq!(receipt.body.served_ctx, active.served_ctx);
        assert_eq!(receipt.body.rules_ver, terms.rules_ver);
        assert_eq!(receipt.body.usage.input_tokens(), 3);
        assert_eq!(receipt.body.usage.output_tokens(), 4);
        assert_eq!(receipt.body.au_owed_cum, 1);
        assert_eq!(
            receipt.body.prompt_hash,
            provider_session_prompt_hash(&body)
        );

        let key_bytes: [u8; 32] = test_hex_decode(&runtime_keypair.public_key_hex())
            .try_into()
            .unwrap();
        let sig_bytes: [u8; 64] = test_hex_decode(&receipt.enclave_sig).try_into().unwrap();
        let verifying_key = VerifyingKey::from_bytes(&key_bytes).unwrap();
        let signature = Signature::from_bytes(&sig_bytes);
        verifying_key
            .verify(&receipt_signing_bytes(&receipt.body).unwrap(), &signature)
            .unwrap();
    }

