    #[test]
    fn provider_session_artifact_delta_frames_are_chunked_and_addressed() {
        let artifact = ProviderSessionArtifact {
            id: "image-1".to_owned(),
            content_type: "image/png".to_owned(),
            bytes: vec![7; PROVIDER_SESSION_ARTIFACT_CHUNK_SIZE + 3],
        };
        let frames =
            provider_session_artifact_delta_frames("rid-1", 2, std::slice::from_ref(&artifact));
        let expected_hash = blake3_bytes_hex(&artifact.bytes);

        assert_eq!(frames.len(), 2);
        assert_eq!(frames[0]["i"], 2);
        assert_eq!(frames[0]["artifact"]["id"], "image-1");
        assert_eq!(frames[0]["artifact"]["encoding"], "hex");
        assert_eq!(frames[0]["artifact"]["offset"], 0);
        assert_eq!(
            frames[0]["artifact"]["len"],
            PROVIDER_SESSION_ARTIFACT_CHUNK_SIZE
        );
        assert_eq!(frames[0]["artifact"]["blake3"], expected_hash);
        assert_eq!(frames[0]["artifact"]["final"], false);
        assert_eq!(frames[1]["i"], 3);
        assert_eq!(
            frames[1]["artifact"]["offset"],
            PROVIDER_SESSION_ARTIFACT_CHUNK_SIZE
        );
        assert_eq!(frames[1]["artifact"]["len"], 3);
        assert_eq!(frames[1]["artifact"]["blake3"], expected_hash);
        assert_eq!(frames[1]["artifact"]["final"], true);
    }

    #[test]
    fn provider_engine_session_response_requires_valid_tool_json() {
        let mut backend = FakeEngineBackend::new("not json");
        let body = json!({
            "messages": [{ "role": "user", "content": "write a file" }],
            "tools": [{
                "type": "function",
                "function": { "name": "write", "parameters": { "type": "object" } }
            }],
            "tool_choice": "auto"
        });
        let err = provider_engine_session_response(
            &mut backend,
            &catalog::CatalogAdapter::default(),
            &body,
            None,
        )
        .expect_err("tool mode requires valid tool-call JSON");

        assert!(
            format!("{err:#}").contains("provider engine did not return valid tool-call JSON"),
            "{err:#}"
        );
        assert!(matches!(
            backend
                .last_request
                .expect("engine request")
                .grammar
                .expect("tool grammar"),
            GrammarSpec::ToolCall { .. }
        ));
    }

    #[test]
    fn provider_engine_session_response_normalizes_openai_tool_calls_adapter() {
        let adapter = catalog::CatalogAdapter {
            tool_call_strategy: "openai_tool_calls".to_owned(),
            ..catalog::CatalogAdapter::default()
        };
        let mut backend = FakeEngineBackend::new(
            r#"{ "tool_calls": [{ "id": "call-openai", "type": "function", "function": { "name": "write", "arguments": "{\"filePath\":\"ok.txt\"}" } }] }"#,
        );
        let body = json!({
            "messages": [{ "role": "user", "content": "write a file" }],
            "tools": [{
                "type": "function",
                "function": { "name": "write", "parameters": { "type": "object" } }
            }],
            "tool_choice": "auto"
        });
        let output = provider_engine_session_response(&mut backend, &adapter, &body, None).unwrap();

        assert_eq!(output.finish_reason, "tool_calls");
        assert_eq!(output.content, "");
        let tool = output.tool.expect("tool call");
        assert_eq!(tool["id"], "call-openai");
        assert_eq!(tool["name"], "write");
        assert_eq!(tool["arguments"], r#"{"filePath":"ok.txt"}"#);
        assert!(matches!(
            backend
                .last_request
                .expect("engine request")
                .grammar
                .expect("OpenAI tool_calls schema"),
            GrammarSpec::JsonSchema { .. }
        ));
    }

