    #[test]
    fn provider_bridge_drop_clears_active_session_slots_without_exiting() {
        let mut sessions = HashMap::new();
        let mut pending_requests = HashMap::new();
        let mut pending_payloads = HashMap::new();
        for id in ["s1", "s2"] {
            sessions.insert(
                id.to_owned(),
                ActiveProviderSession {
                    remote: format!("remote-{id}"),
                    rail: "fiat".to_owned(),
                    user_pubkey: "aa".repeat(32),
                    session_id: id.to_owned(),
                    price_ver: 1,
                    locked_rate_map: text_generation_rate_map(1, 2),
                    locked_per_req_au: 0,
                    locked_min_session_au: 0,
                    served_ctx: 8192,
                    ctx_bracket: Some(ctx_bracket_for_tokens(8192).to_owned()),
                    ctx_bracket_table_ver: Some(CTX_BRACKET_TABLE_VERSION),
                    checkpoint_every: CheckpointPolicy { tokens: 1, ms: 0 },
                },
            );
            pending_requests.insert(id.to_owned(), Instant::now() + Duration::from_secs(30));
        }
        pending_payloads.insert(
            provider_session_payload_key("s1", "r1", &"bb".repeat(32)),
            PendingProviderPayload::default(),
        );
        let load = ProviderHeartbeatLoad::default();
        load.set_active_sessions(sessions.len());

        let dropped = clear_provider_sessions_after_bridge_drop(
            &mut sessions,
            &mut pending_requests,
            &mut pending_payloads,
            &load,
        );

        assert_eq!(dropped, 2);
        assert!(sessions.is_empty());
        assert!(pending_requests.is_empty());
        assert!(pending_payloads.is_empty());
        assert_eq!(load.snapshot().active_slots, 0);
    }

    #[test]
    fn provider_session_reassembles_chunked_request_body() {
        let body = json!({
            "messages": [
                { "role": "system", "content": "be precise" },
                { "role": "user", "content": "x".repeat(4097) }
            ],
            "stream": true,
        });
        let (manifest, chunks) = mayhem_proto::chunk_json_payload(&body, 512).unwrap();
        let session_id = "sess-chunk";
        let request_id = "req-chunk";
        let mut pending_payloads = HashMap::new();
        for chunk in chunks {
            provider_session_collect_request_chunk(
                &mut pending_payloads,
                session_id,
                &json!({
                    "t": "s.req_chunk",
                    "rid": request_id,
                    "payload_id": manifest.blake3,
                    "chunk": chunk,
                }),
            )
            .unwrap();
        }

        let restored = provider_session_request_body_from_frame(
            &mut pending_payloads,
            session_id,
            &json!({
                "t": "s.req",
                "rid": request_id,
                "body_ref": manifest,
            }),
        )
        .unwrap();

        assert_eq!(restored, body);
        assert!(pending_payloads.is_empty());
    }

    #[test]
    fn provider_session_rejects_corrupt_chunked_request_body() {
        let body = json!({ "messages": [{ "role": "user", "content": "hello" }], "stream": true });
        let (manifest, mut chunks) = mayhem_proto::chunk_json_payload(&body, 8).unwrap();
        chunks[0].data = "00".repeat(8);
        let session_id = "sess-corrupt";
        let request_id = "req-corrupt";
        let mut pending_payloads = HashMap::new();
        for chunk in chunks {
            provider_session_collect_request_chunk(
                &mut pending_payloads,
                session_id,
                &json!({
                    "t": "s.req_chunk",
                    "rid": request_id,
                    "payload_id": manifest.blake3,
                    "chunk": chunk,
                }),
            )
            .unwrap();
        }

        let err = provider_session_request_body_from_frame(
            &mut pending_payloads,
            session_id,
            &json!({
                "t": "s.req",
                "rid": request_id,
                "body_ref": manifest,
            }),
        )
        .unwrap_err();

        assert!(err
            .to_string()
            .contains("reassembling s.req body_ref failed"));
    }

    #[test]
    fn provider_session_content_deltas_distribute_token_ids_incrementally() {
        let parts = provider_stream_parts("one two three four five");
        let token_ids = vec![10, 11, 12, 13, 14, 15, 16];
        let mut observed = Vec::new();

        for (index, part) in parts.iter().enumerate() {
            let delta = provider_token_ids_delta_for_part(&token_ids, index, parts.len());
            let frame = provider_session_content_delta_frame("rid", index as u64, part, delta);
            observed.extend(
                frame["token_ids_delta"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|value| value.as_i64().unwrap() as i32),
            );
        }

        assert_eq!(observed, token_ids);
    }

    #[test]
    fn provider_session_final_delta_frames_chunk_large_fields_under_transport_limit() {
        let output = ProviderSessionOutput {
            content: String::new(),
            tool: Some(json!({
                "id": "call-large",
                "name": "write_file",
                "arguments": "x".repeat(20_000),
            })),
            embeddings: Some(vec![vec![0.25_f32; 2048], vec![0.5_f32; 2048]]),
            artifacts: Vec::new(),
            finish_reason: "tool_calls".to_owned(),
            prompt_tokens: 3,
            completion_tokens: 4,
            token_ids: (0..5000).collect::<Vec<i32>>(),
            usage: ReceiptUsage::text(3, 4),
        };
        let max_frame_bytes = 12 * 1024;

        let frames = provider_session_final_delta_frames(
            "rid-large",
            7,
            &output,
            false,
            &json!({
                "ttft_ms": 50,
                "compute_ms": 100,
                "throughput": 40.0,
                "unit": "output_tok_s",
            }),
            max_frame_bytes,
        )
        .unwrap();

        assert!(frames.len() > 3);
        assert!(frames
            .iter()
            .all(|frame| provider_session_frame_json_len(frame).unwrap() <= max_frame_bytes));
        assert!(frames[..frames.len() - 1]
            .iter()
            .all(|frame| { frame.get("t").and_then(Value::as_str) == Some("s.delta_chunk") }));
        let final_frame = frames.last().unwrap();
        assert_eq!(
            final_frame.get("t").and_then(Value::as_str),
            Some("s.delta")
        );
        assert!(final_frame["tool"].is_null());
        assert!(final_frame["embeddings"].is_null());
        assert!(final_frame["token_ids"].is_null());
        assert_eq!(final_frame["quality"]["unit"], json!("output_tok_s"));
        for field in ["tool", "embeddings", "token_ids"] {
            let manifest_key = format!("{field}_ref");
            let manifest: PayloadChunkManifest =
                serde_json::from_value(final_frame[manifest_key.as_str()].clone()).unwrap();
            let chunks = frames[..frames.len() - 1]
                .iter()
                .filter(|frame| frame.get("field").and_then(Value::as_str) == Some(field))
                .map(|frame| {
                    serde_json::from_value::<PayloadChunk>(frame["chunk"].clone()).unwrap()
                })
                .collect::<Vec<_>>();
            let restored = reassemble_json_payload(&manifest, &chunks).unwrap();
            match field {
                "tool" => assert_eq!(restored["arguments"], json!("x".repeat(20_000))),
                "embeddings" => assert_eq!(restored.as_array().unwrap().len(), 2),
                "token_ids" => assert_eq!(restored.as_array().unwrap().len(), 5000),
                _ => unreachable!(),
            }
        }
    }

    #[test]
    fn provider_heartbeat_load_tracks_live_active_slots() {
        let load = ProviderHeartbeatLoad::default();
        assert_eq!(load.snapshot(), ProviderLoadSnapshot::default());
        load.set_active_sessions(2);
        assert_eq!(
            load.snapshot(),
            ProviderLoadSnapshot {
                active_slots: 2,
                active_requests: 0,
                free_slots: 2,
                engine_backlog: 0,
                est_wait_ms: 0,
                ttft_ms: 0,
                measured_tok_s_milli: None,
                accepting_new: true
            }
        );
        load.set_accepting_new(false);
        assert!(!load.snapshot().accepting_new);
        assert!(!load.is_stopped());
        load.stop();
        assert!(load.is_stopped());
    }

    #[test]
    fn provider_heartbeat_load_tracks_queue_and_measured_perf() {
        let load = ProviderHeartbeatLoad::default();
        load.set_active_sessions(3);
        let mut request = load.begin_request();

        let busy = load.snapshot();
        assert_eq!(busy.active_slots, 3);
        assert_eq!(busy.active_requests, 1);
        assert_eq!(busy.free_slots, 2);
        assert_eq!(busy.engine_backlog, 0);
        assert_eq!(busy.ttft_ms, 0);

        load.record_ttft_ms(125);
        load.record_turn_result(Duration::from_millis(500), 10);
        request.finish();

        let measured = load.snapshot();
        assert_eq!(measured.active_requests, 0);
        assert_eq!(measured.free_slots, 3);
        assert_eq!(measured.engine_backlog, 0);
        assert_eq!(measured.ttft_ms, 125);
        assert_eq!(measured.measured_tok_s_milli, Some(20_000));
        assert_eq!(
            provider_heartbeat_tok_s(measured, Some(30.0)),
            (Some(20.0), "measured")
        );
    }

    #[test]
    fn provider_throughput_units_follow_modality_usage() {
        let text = ReceiptUsage::text(40, 8);
        assert_eq!(provider_session_throughput_units(&text), 8);
        assert_eq!(provider_session_throughput_unit(&text), "output_tok_s");

        let image = ReceiptUsage::from_units([(USAGE_IMAGE, 2), (USAGE_STEP, 40)]);
        assert_eq!(provider_session_throughput_units(&image), 2);
        assert_eq!(provider_session_throughput_unit(&image), "images_s");

        let audio = ReceiptUsage::from_units([(USAGE_AUDIO_SECOND, 6)]);
        assert_eq!(provider_session_throughput_units(&audio), 6);
        assert_eq!(provider_session_throughput_unit(&audio), "audio_rtf");

        let embedding = ReceiptUsage::text(128, 0);
        assert_eq!(provider_session_throughput_units(&embedding), 128);
        assert_eq!(provider_session_throughput_unit(&embedding), "input_tok_s");
    }

    #[test]
    fn provider_protection_rejects_capacity_rate_and_quota_cleanly() {
        let mut capacity =
            ProviderProtectionState::new(ProviderProtectionConfig::unlimited_for_tests(1));
        assert_eq!(
            capacity.acceptance_decision(0),
            ProviderSessionDecision::Accept
        );
        assert!(matches!(
            capacity.acceptance_decision(1),
            ProviderSessionDecision::Reject {
                code: "CAPACITY",
                ..
            }
        ));

        let mut rate = ProviderProtectionState::new(ProviderProtectionConfig {
            max_sessions: 4,
            accept_rate_per_minute: 1,
            budget_au: 0,
            budget_units: 0,
            budget_period: Duration::from_secs(86_400),
        });
        assert_eq!(rate.acceptance_decision(0), ProviderSessionDecision::Accept);
        rate.record_accept();
        assert!(matches!(
            rate.acceptance_decision(0),
            ProviderSessionDecision::Reject { code: "RATE", .. }
        ));

        let mut quota_au = ProviderProtectionState::new(ProviderProtectionConfig {
            max_sessions: 4,
            accept_rate_per_minute: 0,
            budget_au: 10,
            budget_units: 0,
            budget_period: Duration::from_secs(1),
        });
        quota_au.record_usage(&ReceiptUsage::text(1, 1), 10);
        assert!(matches!(
            quota_au.acceptance_decision(0),
            ProviderSessionDecision::Reject { code: "QUOTA", .. }
        ));
        quota_au.period_started = Instant::now() - Duration::from_secs(2);
        assert_eq!(
            quota_au.acceptance_decision(0),
            ProviderSessionDecision::Accept
        );

        let mut quota_units = ProviderProtectionState::new(ProviderProtectionConfig {
            max_sessions: 4,
            accept_rate_per_minute: 0,
            budget_au: 0,
            budget_units: 3,
            budget_period: Duration::from_secs(86_400),
        });
        quota_units.record_usage(&ReceiptUsage::text(1, 2), 0);
        assert!(matches!(
            quota_units.acceptance_decision(0),
            ProviderSessionDecision::Reject { code: "QUOTA", .. }
        ));
    }

    #[test]
    fn provider_runtime_floor_rejects_new_sessions_as_capacity() {
        let healthy_disk = ProviderRuntimeDiskObservation {
            path: PathBuf::from("/tmp/mayhem-downloads"),
            available_bytes: Some(20 * GIB_BYTES),
            reserve_bytes: 10 * GIB_BYTES,
        };
        assert!(provider_runtime_floor_rejection_from_observations(
            std::slice::from_ref(&healthy_disk),
            ProviderRuntimeMemoryObservation::NotChecked,
        )
        .is_none());

        let disk_reject = provider_runtime_floor_rejection_from_observations(
            &[ProviderRuntimeDiskObservation {
                available_bytes: Some(GIB_BYTES),
                ..healthy_disk.clone()
            }],
            ProviderRuntimeMemoryObservation::NotChecked,
        )
        .expect("low disk must reject");
        assert_eq!(disk_reject.code, "CAPACITY");
        assert!(disk_reject.reason.contains("disk floor is active"));

        let memory_reject = provider_runtime_floor_rejection_from_observations(
            &[healthy_disk.clone()],
            ProviderRuntimeMemoryObservation::AvailableBytes {
                pool: "system_memory".to_owned(),
                available_bytes: Some(GIB_BYTES),
                reserve_bytes: 2 * GIB_BYTES,
            },
        )
        .expect("low memory must reject");
        assert_eq!(memory_reject.code, "CAPACITY");
        assert!(memory_reject.reason.contains("memory floor is active"));

        let mac_reject = provider_runtime_floor_rejection_from_observations(
            &[healthy_disk],
            ProviderRuntimeMemoryObservation::MacosPressure {
                level: Some(PROVIDER_MACOS_MEMORY_PRESSURE_STOP_LEVEL),
                stop_level: PROVIDER_MACOS_MEMORY_PRESSURE_STOP_LEVEL,
            },
        )
        .expect("macOS pressure floor must reject");
        assert_eq!(mac_reject.code, "CAPACITY");
        assert!(mac_reject.reason.contains("memory-pressure floor"));
    }

    #[test]
    fn provider_engine_watchdog_rejects_rss_over_budget() {
        let reject = provider_engine_watchdog_rejection(
            None,
            &ProviderEngineRssObservation {
                pids: vec![11, 22],
                total_rss_bytes: Some(9 * GIB_BYTES),
                limit_bytes: 8 * GIB_BYTES,
            },
        )
        .expect("rss above budget must reject");

        assert_eq!(reject.code, "CAPACITY");
        assert!(reject.reason.contains("engine watchdog is active"));
        assert!(reject.reason.contains("11,22"));

        assert!(provider_engine_watchdog_rejection(
            None,
            &ProviderEngineRssObservation {
                pids: vec![11],
                total_rss_bytes: Some(7 * GIB_BYTES),
                limit_bytes: 8 * GIB_BYTES,
            },
        )
        .is_none());
    }

    #[test]
    fn provider_engine_watchdog_restarts_only_after_sustained_pressure_and_drain() {
        let mut watchdog = ProviderEngineWatchdog {
            limit_bytes: 8 * GIB_BYTES,
            sustained_samples: 0,
            cooldown_until: None,
        };
        let rss = ProviderEngineRssObservation {
            pids: vec![std::process::id()],
            total_rss_bytes: Some(9 * GIB_BYTES),
            limit_bytes: 8 * GIB_BYTES,
        };
        let now = Instant::now();

        assert!(matches!(
            watchdog.check(None, rss.clone(), 1, now),
            ProviderEngineWatchdogAction::RefuseNew(_)
        ));
        assert!(matches!(
            watchdog.check(None, rss.clone(), 1, now + Duration::from_secs(1)),
            ProviderEngineWatchdogAction::RefuseNew(_)
        ));
        assert!(matches!(
            watchdog.check(None, rss.clone(), 1, now + Duration::from_secs(2)),
            ProviderEngineWatchdogAction::RefuseNew(_)
        ));
        assert!(matches!(
            watchdog.check(None, rss.clone(), 0, now + Duration::from_secs(3)),
            ProviderEngineWatchdogAction::RestartNow(_)
        ));
        assert!(matches!(
            watchdog.check(None, rss, 0, now + Duration::from_secs(4)),
            ProviderEngineWatchdogAction::RefuseNew(_)
        ));
        watchdog.reset_after_restart();
        assert!(matches!(
            watchdog.check(
                None,
                ProviderEngineRssObservation {
                    pids: vec![std::process::id()],
                    total_rss_bytes: Some(GIB_BYTES),
                    limit_bytes: 8 * GIB_BYTES,
                },
                0,
                now + Duration::from_secs(5),
            ),
            ProviderEngineWatchdogAction::Healthy
        ));
    }

