    #[test]
    fn pay_checkout_extraction_requires_hosted_urls() {
        let stripe = checkout_from_paygate_response(
            PayRail::Stripe,
            &json!({
                "rail": "fiat",
                "processor_rail": "stripe",
                "copy_paste": {
                    "checkout_url": "https://checkout.stripe.com/c/pay/cs_test"
                },
                "checkout_session": {
                    "id": "cs_test",
                    "url": "https://checkout.stripe.com/c/pay/cs_test",
                    "payment_intent": "pi_test"
                }
            }),
        )
        .unwrap();
        assert_eq!(stripe.id, "cs_test");
        assert_eq!(stripe.reference.as_deref(), Some("pi_test"));

        assert!(checkout_from_paygate_response(
            PayRail::Stripe,
            &json!({
                "rail": "fiat",
                "processor_rail": "stripe",
                "checkout_session": {
                    "id": "cs_test",
                    "url": "javascript:alert(1)"
                }
            }),
        )
        .is_err());
        assert!(checkout_from_paygate_response(
            PayRail::Stripe,
            &json!({
                "rail": "fiat",
                "processor_rail": "stripe",
                "checkout_session": {
                    "id": "cs_test",
                    "url": "https://checkout.stripe.com.evil.example/c/pay/cs_test"
                }
            }),
        )
        .is_err());
        assert!(checkout_from_paygate_response(
            PayRail::Stripe,
            &json!({
                "rail": "fiat",
                "processor_rail": "stripe",
                "copy_paste": {
                    "checkout_url": "https://checkout.stripe.com/c/pay/other"
                },
                "checkout_session": {
                    "id": "cs_test",
                    "url": "https://checkout.stripe.com/c/pay/cs_test"
                }
            }),
        )
        .is_err());
    }

