    fn canary_apply_updates_catalog_fingerprint_from_bound_report() {
        let mut catalog = test_catalog(&"aa".repeat(32));
        catalog.models[0].tier = "launch".to_owned();
        catalog.models[0]
            .canary
            .fingerprints
            .insert("gguf-q4_k_m".to_owned(), "00".repeat(32));
        let canaries_dir = test_canary_dir("test-canary", 0.0);
        let mut calibration = test_calibration_report("aa".repeat(32), Some("00".repeat(32)));
        calibration.model_id = "test/model@4bit".to_owned();
        stamp_test_calibration_report(&mut calibration, &canaries_dir);
        let report_path = write_temp_calibration_report(&calibration);

        let report = catalog_canary_evidence_report(
            &catalog,
            PathBuf::from("catalog.json"),
            canaries_dir,
            true,
            &[report_path],
            CatalogCanaryReportMode::ApplyToCatalog,
        );
        assert!(report.ok, "{:?}", report.errors);
        assert_eq!(report.entries[0].matches_catalog, Some(false));

        let mut catalog_value = json!({
            "models": [{
                "model_id": "test/model@4bit",
                "canary": {
                    "fingerprints": {
                        "gguf-q4_k_m": "00".repeat(32)
                    }
                }
            }]
        });
        let applied = apply_canary_report_fingerprints(&mut catalog_value, &report).unwrap();

        assert_eq!(applied, 1);
        assert_eq!(
            catalog_value["models"][0]["canary"]["fingerprints"]["gguf_q4_k_m"],
            Value::Null
        );
        assert_eq!(
            catalog_value["models"][0]["canary"]["fingerprints"]["gguf-q4_k_m"],
            json!("aa".repeat(32))
        );
        assert_eq!(
            catalog_value["models"][0]["canary"]["token_prefixes"]["gguf-q4_k_m"]["p1"],
            json!([1])
        );
    }

    #[test]
    fn artifact_metadata_computes_launch_catalog_patch() {
        let path = env::temp_dir().join(format!(
            "mayhem-artifact-metadata-{}-{}.bin",
            std::process::id(),
            now_millis_for_path()
        ));
        fs::write(&path, b"mayhem artifact metadata").unwrap();
        let merkle = build_merkle_manifest(&path, 5).unwrap();
        let sha256 = file_sha256_hex(&path).unwrap();
        let catalog = test_catalog(&"00".repeat(32));

        let report = catalog_artifact_metadata_report(
            Some((
                &catalog,
                PathBuf::from("catalog.json"),
                "test/model@4bit",
                "gguf-q4_k_m",
            )),
            path.clone(),
            5,
            None,
        )
        .unwrap();

        assert!(report.ok);
        assert_eq!(report.catalog_patch.artifact_root_kind, "blake3_merkle_v1");
        assert_eq!(report.catalog_patch.artifact_root, merkle.root);
        assert_eq!(report.catalog_patch.source_sha256, sha256);
        assert_eq!(report.catalog_patch.weights_bytes, merkle.total_bytes);
        let binding = report.catalog_binding.as_ref().unwrap();
        assert!(binding.update_needed);
        assert!(!binding.matches_current_artifact_root);
        assert_eq!(binding.matches_current_source_sha256, None);
        assert!(!binding.matches_current_weights_bytes);

        let mut matching_catalog = test_catalog(&report.catalog_patch.artifact_root);
        matching_catalog.models[0]
            .artifacts
            .get_mut("gguf-q4_k_m")
            .unwrap()
            .source_sha256 = Some(report.catalog_patch.source_sha256.clone());
        matching_catalog.models[0]
            .artifacts
            .get_mut("gguf-q4_k_m")
            .unwrap()
            .weights_bytes = report.catalog_patch.weights_bytes;

        let matching = catalog_artifact_metadata_report(
            Some((
                &matching_catalog,
                PathBuf::from("catalog.json"),
                "test/model@4bit",
                "gguf-q4_k_m",
            )),
            path.clone(),
            5,
            None,
        )
        .unwrap();
        let binding = matching.catalog_binding.as_ref().unwrap();
        assert!(!binding.update_needed);
        assert!(binding.matches_current_artifact_root);
        assert_eq!(binding.matches_current_source_sha256, Some(true));
        assert!(binding.matches_current_weights_bytes);

        let _ = fs::remove_file(path);
    }

